  ui_story_5082_50820100_10_dialog_content = "Bem, eu pensei muito e profundamente sobre isso por dias e percebi que a Oficial Vivian estava me testando - o combate não é algo que você pode aprender com um livro, miau!",
  ui_story_5082_50820100_11_dialog_content = "Você está apenas empurrando seu trabalho para outra pessoa, não está?!",
