  ui_story_5082_50820100_23_dialog_content = "Ela realmente me levou para o campo de treinamento sem adormecer...",
  ui_story_5082_50820100_24_dialog_content = "Desculpe Philyshy, eu estava errado em duvidar de você. Eu não percebi que você também poderia ser tão trabalhador.",
  ui_story_5082_50820100_25_dialog_content = "Pedido de desculpas e elogio aceitos! Há uma razão pela qual te trouxe direto para cá, sabe!",
