  ui_story_5082_50820100_31_dialog_content = "É a equipe do Barton. Parece que eles estão no meio do treinamento.",
  ui_story_5082_50820100_32_dialog_content = "Perfeito! Agora vá e junte-se a eles!",
  ui_story_5082_50820100_33_dialog_content = "Espere... Eu?",
  ui_story_5082_50820100_34_dialog_content = "Sim, você!",
  ui_story_5082_50820100_35_dialog_content = "Este é o novo campo de treinamento do Comandante Barton, onde ele molda nossos recrutas inexperientes! É o lugar perfeito para você, PlayerName!",
