  ui_story_5082_50820100_38_dialog_content = "Haha, eu gosto do seu espírito, criança!",
  ui_story_5082_50820100_39_dialog_content = "Mas se você quer ter uma chance contra nossos inimigos na Zona Cega, nosso treinamento aqui não será suficiente.",
