  ui_story_5082_50820100_42_dialog_content = "S-Sim, senhor!",
  ui_story_5082_50820100_43_dialog_content = "(A presença de Barton é tão avassaladora... Eu nem pensei em dizer não agora mesmo...)",
  ui_story_5082_50820100_44_dialog_content = "Bom de se ouvir.",
  ui_story_5082_50820100_45_dialog_content = "Vamos ver, como posso transformar um pequeno e fraco Celestita em uma máquina de luta enxuta e cruel no menor tempo possível?",
  ui_story_5082_50820100_46_dialog_content = "Hum, por que eu não posso fazer o mesmo treinamento que todos os outros?",
  ui_story_5082_50820100_47_dialog_content = "Hmph, leve isso aos velhos tolos do Comitê. Eles são os que insistem que usemos seus novos métodos de treinamento \"científico\".",
  ui_story_5082_50820100_48_dialog_content = "Eles estabelecem todos os tipos de referências e modelos, como se estivessem tentando ditar cada segundo de treinamento!",
  ui_story_5082_50820100_49_dialog_content = "Mas não é meio que o ponto?",
  ui_story_5082_50820100_50_dialog_content = "Talvez para apenas treinamento físico, claro.",
  ui_story_5082_50820100_51_dialog_content = "Mas eu treino soldados de verdade aqui, não um monte de marionetes produzidas em massa! Meu trabalho é prepará-los para combater inimigos na linha de frente!",
  ui_story_5082_50820100_52_dialog_content = "Métodos de treinamento rígidos como este nunca produzirão soldados verdadeiramente excepcionais. É o que eu penso, de qualquer forma.",
  ui_story_5082_50820100_53_dialog_content = "No passado, o Grande Marechal e eu sempre participávamos de treinamentos de combate ao vivo com outros, mesmo que não estivéssemos na linha de frente.",
  ui_story_5082_50820100_54_dialog_content = "Independentemente de posição ou patente, todos nós entraríamos no mesmo território desconhecido e testaríamos nossa força uns contra os outros.",
  ui_story_5082_50820100_55_dialog_content = "Além de um número escasso de munições e suprimentos, tudo o que tínhamos para confiar eram nossos corpos e nossa inteligência.",
  ui_story_5082_50820100_56_dialog_content = "Nessas circunstâncias, os poderosos e altivos não estavam necessariamente à frente da competição. Até os participantes menos notáveis tinham uma chance de vencer.",
  ui_story_5082_50820100_57_dialog_content = "Combate, estratégia, derrota e vitória.",
  ui_story_5082_50820100_58_dialog_content = "A dor de ser pisoteado na lama pelos fortes, e a determinação de vencer por todos os meios necessários.",
  ui_story_5082_50820100_59_dialog_content = "Somente experimentando essas coisas em primeira mão um soldado pode se transformar em algo verdadeiramente poderoso.",
  ui_story_5082_50820100_60_dialog_content = "Um cenário de combate realista onde qualquer coisa pode acontecer a qualquer momento é a melhor maneira de aprimorar suas habilidades!",
  ui_story_5082_50820100_61_dialog_content = "Bem dito, Barton.",
  ui_story_5082_50820100_62_dialog_content = "Reinhardt! Você está aqui também?",
  ui_story_5082_50820100_63_dialog_content = "Vim ver o progresso dos nossos soldados antes de entrarmos na Zona Cega. Parece que apareci bem na hora certa.",
  ui_story_5082_50820100_64_dialog_content = "Não competimos cara a cara há um tempo, Barton. Gostaria de ver qual de nós melhorou mais desde a última vez?",
  ui_story_5082_50820100_65_dialog_content = "É tudo que eu poderia pedir!",
  ui_story_5082_50820100_66_dialog_content = "Espera, vocês dois não vão...",
  ui_story_5082_50820100_67_dialog_content = "Isso mesmo! Estamos tendo um exercício de combate ao vivo, bem aqui e agora!",
  ui_story_5082_50820100_68_dialog_content = "Sem fugir, entendeu, criança?!",
  ui_story_5082_50820100_69_dialog_content = "E-Eu jamais! Não sou do tipo que desiste antes mesmo de começar!",
  ui_story_5082_50820100_70_dialog_content = "Bom, então considere isso uma parte do seu treinamento especial, PlayerName. Naturalmente, seu manipulador também estará participando.",
  ui_story_5082_50820100_71_dialog_content = "Não é isso mesmo, Chefe de Inteligência Philyshy?",
  ui_story_5082_50820100_72_dialog_content = "Agora que você mencionou, eu não ouvi ela dizer nada há um tempo... Ei! Quando você se esgueirou para lá?!",
  ui_story_5082_50820100_73_dialog_content = "Suspiro... Se você diz isso, Grande Marechal.",
  ui_story_5082_50820100_74_dialog_content = "Philyshy entrou na batalha!",
  ui_story_5082_50820100_75_dialog_content = "<color=#e8d9bb>Momentos depois</color>",
  ui_story_5082_50820100_76_dialog_content = "Boa tarde, todos. Embora não fosse parte do programa original-",
  ui_story_5082_50820100_77_dialog_content = "A pedido do Grande Marechal, vim servir como juiz neste exercício de treinamento.",
  ui_story_5082_50820100_78_dialog_content = "O exercício, que durará dois dias e duas noites, será composto por quatro equipes de duas pessoas cada. Sinta-se à vontade para dar uma olhada na lista de participantes.",
  ui_story_5082_50820100_79_dialog_content = "Equipe 1 é Reinhardt e Philyshy.",
  ui_story_5082_50820100_80_dialog_content = "Barton e eu estamos na Equipe 2. As duas últimas equipes são compostas por oficiais da 2ª Legião...",
  ui_story_5082_50820100_81_dialog_content = "Então, onde exatamente estamos lutando?",
  ui_story_5082_50820100_82_dialog_content = "Isso é simples o suficiente para responder.",
  ui_story_5082_50820100_83_dialog_content = "<color=#e8d9bb>Balança, balança, balança—Rola—</color>",
  ui_story_5082_50820100_84_dialog_content = "Ele realmente carrega os dados para simulação militar com ele...?",
  ui_story_5082_50820100_85_dialog_content = "Ha! Parece que vamos levar essa pequena competição para aquela Cidade Baixa próxima.",
  ui_story_5082_50820100_86_dialog_content = "Você está com sorte, criança. Essa Cidade Baixa foi abandonada por anos, e estou no processo de adquiri-la para o meu campo de treinamento.",
  ui_story_5082_50820100_87_dialog_content = "É uma área enorme com toneladas de estruturas abandonadas.",
  ui_story_5082_50820100_88_dialog_content = "O layout é perfeito para lançar ataques surpresa - Embora eu tenho certeza que nossos oponentes estão pensando exatamente a mesma coisa.",
  ui_story_5082_50820100_89_dialog_content = "Você parece incrivelmente calmo com isso. Tem certeza de que isso não vai ser um problema?",
  ui_story_5082_50820100_90_dialog_content = "Os Eclipsitas não levam essas coisas em consideração quando atacam. Esse nível de incerteza é apenas outra parte da simulação de combate; Eu sugiro que você se acostume com isso.",
  ui_story_5082_50820100_91_dialog_content = "Espere... Como juiz, não deveria ser eu a designar o local?",
  ui_story_5082_50820100_92_dialog_content = "Hahahaha! Desculpe, fiquei tão empolgado que acabei fazendo o trabalho da Chefe de Gabinete por ela!",
  ui_story_5082_50820100_93_dialog_content = "...",
  ui_story_5082_50820100_94_dialog_content = "Apenas vá com a escolha de Barton, Vivian.",
  ui_story_5082_50820100_95_dialog_content = "Muito bem então. Vocês têm trinta minutos para se preparar antes de entrar no local do concurso. Quando o sino tocar, a partida começará oficialmente.",
  ui_story_5082_50820100_96_dialog_content = "Esta é uma oportunidade preciosa para ganhar valiosa experiência de combate, então por favor, leve a sério e lute com todas as suas forças.",
  ui_story_5082_50820100_97_dialog_content = "Entendido!",
  ui_story_5082_50820100_98_dialog_content = "A Subcidade próxima... Nós mal temos qualquer informação sobre ela. Barton definitivamente sabe como escolher suas batalhas.",
  ui_story_5082_50820201_1_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5082_50820201_2_dialog_content = "Hahahaha, nada mal! Vamos ver a Grande Marechal nos impedir agora que seu forte está em ruínas!",
  ui_story_5082_50820201_3_dialog_content = "*cof*",
  ui_story_5082_50820201_4_dialog_content = "Tanta fumaça e destroços... Ugh... Uma explosão como essa certamente vai revelar nossa posição.",
  ui_story_5082_50820201_5_dialog_content = "Não deveríamos tentar nos distanciar deste local?",
  ui_story_5082_50820201_6_dialog_content = "Isso mesmo. Podemos deixar os outros jogar pelo resto da partida.",
  ui_story_5082_50820201_7_dialog_content = "Vamos nos separar e reunir qualquer comida e recursos que pudermos encontrar, PlayerName!",
  ui_story_5082_50820201_8_dialog_content = "Entendido!",
  ui_story_5082_50820201_9_dialog_content = "Vou apenas por aqui... Hã?",
  ui_story_5082_50820201_10_dialog_content = "Sinto como se alguém estivesse me observando...",
  ui_story_5082_50820201_11_dialog_content = "Suspiro... Eu trabalhei tanto naquela fortaleza também.",
  ui_story_5082_50820201_12_dialog_content = "Você não precisava ter explodido dessa maneira, sabe!",
  ui_story_5082_50820201_13_dialog_content = "(Ela já voltou?!)",
  ui_story_5082_50820201_14_dialog_content = "(Mas parece que Philyshy está sozinho...)",
  ui_story_5082_50820201_15_dialog_content = "Espere, Philyshy! Só me ouça!",
  ui_story_5082_50820201_16_dialog_content = "Barton não está muito longe da nossa localização. Se você me atacar agora, ele estará aqui antes que você perceba.",
  ui_story_5082_50820201_17_dialog_content = "Lutar contra nós dois sozinho não é do seu melhor interesse.",
  ui_story_5082_50820201_18_dialog_content = "Então, por que não recuar por agora? Se fizer isso, prometo que não atacaremos sua equipe nas próximas duas horas.",
  ui_story_5082_50820201_19_dialog_content = "Até vamos ajudá-lo derrubando as outras duas equipes! Você terá duas horas inteiras para fazer o que quiser, mesmo que não seja nada!",
  ui_story_5082_50820201_20_dialog_content = "Hmm, isso soa bem.",
  ui_story_5082_50820201_21_dialog_content = "Então—",
  ui_story_5082_50820201_22_dialog_content = "Infelizmente, nunca deixo um rato sair da minha vista uma vez que o encurralei!",
  ui_story_5082_50820201_23_dialog_content = "Ah não... É a Yumi!",
  ui_story_5082_50820201_24_dialog_content = "Agora é tarde demais!",
  ui_story_5082_50820201_25_dialog_content = "(Se eu não conseguir negociar uma saída para isso... Então eu só tenho que correr!)",
  ui_story_5082_50820201_26_dialog_content = "Fique quieto, vai?!",
  ui_story_5082_50820201_27_dialog_content = "Não suporto quando minha presa continua correndo por aí!",
  ui_story_5082_50820201_28_dialog_content = "PlayerName! Espere, estou quase lá!",
  ui_story_5082_50820201_29_dialog_content = "Hum? Foi isso...",
  ui_story_5082_50820201_30_dialog_content = "Olhe para cima, PlayerName!",
  ui_story_5082_50820201_31_dialog_content = "!!",
  ui_story_5082_50820201_32_dialog_content = "Isso é... É o Reinhardt! Agora eu estou realmente acabado!",
  ui_story_5082_50820201_33_dialog_content = "Eu sabia que construir uma fortaleza em um lugar tão óbvio era a decisão certa.",
  ui_story_5082_50820201_34_dialog_content = "Desculpe PlayerName, mas parece que seu treinamento especial está sendo cortado.",
  ui_story_5082_50820201_35_dialog_content = "Cuidado, criança! A Grande Marechal vai te transformar em picadinho se isso continuar!",
  ui_story_5082_50820201_36_dialog_content = "Apresse-se e corra!",
  ui_story_5082_50820201_37_dialog_content = "Você pode correr tão rápido quanto quiser, mas—",
  ui_story_5082_50820201_38_dialog_content = "Corram!",
  ui_story_5082_50820201_39_dialog_content = "Corram!",
  ui_story_5082_50820201_40_dialog_content = "... Quem está aí?",
  ui_story_5082_50820201_41_dialog_content = "Não deixe que eles roubem seu poder—",
  ui_story_5082_50820201_42_dialog_content = "Essa voz...",
  ui_story_5082_50820201_43_dialog_content = "Corra!",
  ui_story_5082_50820201_44_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5082_50820201_45_dialog_content = "...!",
  ui_story_5082_50820201_46_dialog_content = "Nada é mais feio do que perder uma batalha por causa da sua própria indecisão!",
  ui_story_5082_50820201_47_dialog_content = "Barton— Ah!",
  ui_story_5082_50820201_48_dialog_content = "PlayerName foi garantido!",
  ui_story_5082_50820201_49_dialog_content = "\"Protegido\"? O que eu sou, um pacote?!",
  ui_story_5082_50820201_50_dialog_content = "Isso é... Um carrinho de mina? De onde veio isso?!",
  ui_story_5082_50820201_51_dialog_content = "Aqui está outra lição valiosa para você, criança: na batalha, não existe tal coisa como um objeto inútil!",
  ui_story_5082_50820201_52_dialog_content = "E a isso, gostaria de acrescentar algumas das minhas próprias palavras.",
  ui_story_5082_50820201_53_dialog_content = "Na batalha, não existe uma solução perfeita para todos os problemas.",
  ui_story_5082_50820201_54_dialog_content = "Reinhardt está alcançando!",
  ui_story_5082_50820201_55_dialog_content = "Mesmo que ela não esteja interessada, acho que ela ainda é a Grande Marechal.",
  ui_story_5082_50820201_56_dialog_content = "Algumas feridas antigas se abriram agora, só isso. Confie em mim, você não terá outra chance como essa novamente.",
  ui_story_5082_50820201_57_dialog_content = "Tch! Segure firme, PlayerName!",
  ui_story_5082_50820201_58_dialog_content = "O Expresso Barton está indo a toda velocidade!",
  ui_story_5082_50820201_59_dialog_content = "Ahhhhh—",
  ui_story_5082_50820201_60_dialog_content = "Se você vai me tratar como carga, pelo menos me manuseie com cuidado!!!",
  ui_story_5082_50820201_61_dialog_content = "Hahahaha!",
  ui_story_5082_50820201_62_dialog_content = "E-Espere, olhe ali! É um beco sem saída! Nós vamos bater—!",
  ui_story_5082_50820201_63_dialog_content = "Então vamos explodir nosso caminho!",
  ui_story_5082_50820201_64_dialog_content = "O quê?!",
  ui_story_5082_50820201_65_dialog_content = "Não há tempo para explicar! Cuidado com sua cabeça!",
  ui_story_5082_50820201_66_dialog_content = "Espere aí—",
  ui_story_5082_50820201_67_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5082_50820201_68_dialog_content = "<color=#e8d9bb>Ping! Bam! Clam, clam, clam!</color>",
  ui_story_5082_50820201_69_dialog_content = "Ugh...",
  ui_story_5082_50820201_70_dialog_content = "Finalmente paramos... Eu pensei que estava morto com certeza...",
  ui_story_5082_50820201_71_dialog_content = "Do que você tem medo? Eu te salvei do Grande Marechal, não salvei?",
  ui_story_5082_50820201_72_dialog_content = "Não, esse não é o ponto... Ei Barton?",
  ui_story_5082_50820201_73_dialog_content = "Claro?",
  ui_story_5082_50820201_74_dialog_content = "Você realmente não deveria ser autorizado a dirigir.",
  ui_story_5082_50820201_75_dialog_content = "?",
  ui_story_5082_50820201_76_dialog_content = "De qualquer forma, que lugar é esse?",
  ui_story_5082_50820201_77_dialog_content = "Corremos por tanto tempo que perdi meu senso de direção. Talvez eu deva usar meus poderes para sentir o ambiente ao nosso redor.",
  ui_story_5082_50820201_78_dialog_content = "Antes de fazer isso, tente observar seus arredores primeiro.",
  ui_story_5082_50820201_79_dialog_content = "Meu redor?",
  ui_story_5082_50820201_80_dialog_content = "Uau, olhe todas essas caixas! Será que eles poderiam ser...?!",
  ui_story_5082_50820201_81_dialog_content = "Eles estão! Caixotes de abastecimento!",
  ui_story_5082_50820201_82_dialog_content = "Você não achou que eu estava apenas te levando para um passeio selvagem, não é?",
  ui_story_5082_50820201_83_dialog_content = "Na batalha, nenhuma ação única é completamente independente do resto da situação.",
  ui_story_5082_50820201_84_dialog_content = "Ser capaz de absorver tudo em seu campo de visão o trará um passo mais perto da vitória.",
  ui_story_5082_50820201_85_dialog_content = "O primeiro dia da competição está quase acabando. Assumir o controle desses suprimentos nos dará uma das maiores vantagens possíveis.",
  ui_story_5082_50820201_86_dialog_content = "Infelizmente, essa grande vantagem também faz de você um alvo principal para todos os outros.",
  ui_story_5082_50820201_87_dialog_content = "Não é diferente de ter uma lança apontada para sua cabeça o tempo todo.",
  ui_story_5082_50820201_88_dialog_content = "Barton!",
  ui_story_5082_50820201_89_dialog_content = "Relaxa, criança. Ainda não perdemos.",
  ui_story_5082_50820201_90_dialog_content = "Venha agora, Grande Marechal. Até as crianças da escola sabem que quem tem os melhores lanches sempre será alvo de inveja.",
  ui_story_5082_50820201_91_dialog_content = "Encontrei esses suprimentos primeiro, então não há como eu entregá-los tão facilmente.",
  ui_story_5082_50820201_92_dialog_content = "PlayerName está segurando um detonador em suas mãos. Um aperto de botão, e os explosivos de baixa qualidade que espalhei entre os suprimentos explodirão, transformando tudo em cinzas.",
  ui_story_5082_50820201_93_dialog_content = "(Hã? Detonador?)",
  ui_story_5082_50820201_94_dialog_content = "Você deve saber exatamente o que significa para uma pessoa destruir seus próprios suprimentos em batalha.",
  ui_story_5082_50820201_95_dialog_content = "Este exercício dura dois dias inteiros. Como Grande Marechal, você está realmente disposto a deixar seus subordinados lutarem sem comida no estômago?",
  ui_story_5082_50820201_96_dialog_content = "Hahaha, quase esqueci como é enfrentar você em combate.",
  ui_story_5082_50820201_97_dialog_content = "Mas mesmo que isso signifique passar fome—",
  ui_story_5082_50820201_98_dialog_content = "(... Hã? O que na Terra é...)",
  ui_story_5082_50820201_99_dialog_content = "(Já é o segundo dia do exercício de treinamento. Esta situação... não vai acabar tão cedo.)",
  ui_story_5082_50820201_100_dialog_content = "(Sou o único que encontrou munição no primeiro dia. Ninguém mais com quem me deparei tinha quaisquer rações.)",
  ui_story_5082_50820201_101_dialog_content = "(Eu não vou conseguir nesse ritmo...)",
  ui_story_5082_50820201_102_dialog_content = "Então você é o único que pegou a munição, hein?",
  ui_story_5082_50820201_103_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5082_50820201_104_dialog_content = "Atirar antes de discernir a identidade da outra pessoa? Isso não é muito legal.",
  ui_story_5082_50820201_105_dialog_content = "Você é o que se infiltrou no meu acampamento. Você não tem direito a nenhuma cortesia.",
  ui_story_5082_50820201_106_dialog_content = "Hahahaha! Então vamos trabalhar juntos, Reinhardt!",
  ui_story_5082_50820201_107_dialog_content = "Isso deveria ser um exercício de combate real. Por que eu deveria concordar em me unir a um infiltrado como você?",
  ui_story_5082_50820201_108_dialog_content = "Bem, para começar, eu bloqueei seu ataque agora sem muito esforço - E você não estava se contendo, estava?",
  ui_story_5082_50820201_109_dialog_content = "Há outros benefícios em trabalhar comigo também. As rações, por exemplo.",
  ui_story_5082_50820201_110_dialog_content = "Ainda existem muitos outros lutadores fortes neste exercício. É apenas uma questão de tempo até que um vencedor seja decidido.",
  ui_story_5082_50820201_111_dialog_content = "Não há como negar que preciso de munição, e algo me diz que você não quer lutar de estômago vazio, quer?",
  ui_story_5082_50820201_112_dialog_content = "Tsc...",
  ui_story_5082_50820201_113_dialog_content = "Combinado.",
  ui_story_5082_50820201_114_dialog_content = "<color=#e8d9bb>Dois Dias Depois</color>",
  ui_story_5082_50820201_115_dialog_content = "Eu não esperava derrubar outra equipe tão rapidamente. Você é muito bom.",
  ui_story_5082_50820201_116_dialog_content = "É claro que sim.",
  ui_story_5082_50820201_117_dialog_content = "Parece que terminamos a luta por hoje. Você usou minha munição, então entregue suas rações e—",
  ui_story_5082_50820201_118_dialog_content = "<color=#e8d9bb>Que droga!</color>",
  ui_story_5082_50820201_119_dialog_content = "Ugh...",
  ui_story_5082_50820201_120_dialog_content = "Um ataque furtivo... Eu deveria ter sabido.",
  ui_story_5082_50820201_121_dialog_content = "Ela se foi... junto com toda a minha munição.",
  ui_story_5082_50820201_122_dialog_content = "Ah... Não acredito que caí nisso.",
  ui_story_5082_50820201_123_dialog_content = "Não como há dois dias, e aquela batalha agora me esgotou. Está ficando cada vez mais difícil aguentar.",
  ui_story_5082_50820201_124_dialog_content = "Terei que descansar aqui pelo dia e conservar a pouca energia que ainda tenho. Quando amanhã chegar, eu...",
  ui_story_5082_50820201_125_dialog_content = "<color=#e8d9bb>Mais Dois Dias Depois</color>",
  ui_story_5082_50820201_126_dialog_content = "(Minha cabeça está girando... E meu corpo parece tão pesado.)",
  ui_story_5082_50820201_127_dialog_content = "(Mas a batalha ainda não acabou. Eu tenho que continuar...)",
  ui_story_5082_50820201_128_dialog_content = "(Em vez de ficar com raiva, preciso pensar no meu próximo passo—)",
  ui_story_5082_50820201_129_dialog_content = "Uau, você ainda consegue se mover?",
  ui_story_5082_50820201_130_dialog_content = "Você tem muita coragem, se mostrando ao meu redor.",
  ui_story_5082_50820201_131_dialog_content = "Por que isso? A culpa é sua por não descobrir meus motivos antes.",
  ui_story_5082_50820201_132_dialog_content = "No final do dia, acho que até mesmo os melhores alunos não valem muito!",
  ui_story_5082_50820201_133_dialog_content = "Diga-me, o que dói mais agora? Suas feridas ou sua fome?",
  ui_story_5082_50820201_134_dialog_content = "Apenas cale a boca e me tire daqui. É por isso que você está aqui, certo?",
  ui_story_5082_50820201_135_dialog_content = "Ah, entendi. Você mal consegue ficar de pé agora, não é? Coitado.",
  ui_story_5082_50820201_136_dialog_content = "Eu disse cale a boca!",
  ui_story_5082_50820201_137_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5082_50820201_138_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5082_50820201_139_dialog_content = "Esquive, PlayerName!",
  ui_story_5082_50820201_140_dialog_content = "Barton!",
  ui_story_5082_50820201_141_dialog_content = "Que alvoroço... Então as rações estavam aqui o tempo todo!",
  ui_story_5082_50820201_142_dialog_content = "Vê isso? O Grande Marechal e o Comandante Barton estão dando tudo de si... Realmente queremos nos meter nisso?",
  ui_story_5082_50820201_143_dialog_content = "...",
  ui_story_5082_50820201_144_dialog_content = "...!",
  ui_story_5082_50820201_145_dialog_content = "(Isso foi... minha memória agora mesmo?)",
  ui_story_5082_50820201_146_dialog_content = "E aqui eu pensei que você estava aéreo... Mas se levarmos essa luta a sério, vamos ver o quanto você melhorou, Grande Marechal!",
  ui_story_5082_50820301_1_dialog_content = "... Ainda bem que decidimos não interferir. Aquele ataque agora teria nos matado cem vezes.",
  ui_story_5082_50820301_2_dialog_content = "Eles estão em um nível completamente diferente, afinal. Você não poderia dizer ao assistir o Comandante Barton quando ele luta contra os Eclipsitas...",
  ui_story_5082_50820301_3_dialog_content = "O Grande Marechal Reinhardt o tinha nas cordas agora mesmo, mas ele não tem um arranhão! De que é feito o corpo dele...?",
  ui_story_5082_50820301_4_dialog_content = "... Será que esses rumores são verdadeiros? Dizem que o Comandante Barton deve seu imenso poder a uma série de experimentos especiais.",
  ui_story_5082_50820301_5_dialog_content = "Também ouço dizer que alguns dos nossos recrutas recentes, os mais próximos dos nossos cientistas, passaram pelo mesmo programa. Quantos deles estão na Illumina...?",
  ui_story_5082_50820301_6_dialog_content = "Você parece bastante interessado neles.",
  ui_story_5082_50820301_7_dialog_content = "Quem não estaria? Se for verdade, tudo o que seria necessário para entrar nas forças especiais são alguns procedimentos!",
  ui_story_5082_50820301_8_dialog_content = "Mas quem sabe que tipo de experimentos loucos eles foram submetidos...",
  ui_story_5082_50820301_9_dialog_content = "Bem, pelo menos eu não me transformei em um Eclipsita, certo?",
  ui_story_5082_50820301_10_dialog_content = "C-C-Comandante Barton!!!",
  ui_story_5082_50820301_11_dialog_content = "...",
  ui_story_5082_50820301_12_dialog_content = "Por que tão silencioso de repente?",
  ui_story_5082_50820301_13_dialog_content = "Não há regra contra expressar sua opinião na 2ª Legião, ou em qualquer outro lugar em Illumina.",
  ui_story_5082_50820301_14_dialog_content = "Se tem algo a dizer ao seu comandante, então diga.",
  ui_story_5082_50820301_15_dialog_content = "M-Mas você é diferente dos outros, Comandante Barton!",
  ui_story_5082_50820301_16_dialog_content = "Todos dizem que a Illumina estava em sério perigo naquela época, e que você só fez aquele sacrifício para mudar o curso da batalha!",
  ui_story_5082_50820301_17_dialog_content = "Mas os outros...",
  ui_story_5082_50820301_18_dialog_content = "Eles lutaram na linha de frente?",
  ui_story_5082_50820301_19_dialog_content = "eu, eh...",
  ui_story_5082_50820301_20_dialog_content = "Eu fiz uma pergunta, soldado! Esses \"outros\" sobre os quais você continua falando; eles lutaram contra os Eclipsitas na linha de frente?!",
  ui_story_5082_50820301_21_dialog_content = "Sim, senhor!",
  ui_story_5082_50820301_22_dialog_content = "Eles passaram pelo mesmo treinamento amargo que você passou?!",
  ui_story_5082_50820301_23_dialog_content = "Sim, senhor!",
  ui_story_5082_50820301_24_dialog_content = "Eles conseguiram desfrutar de vidas pacíficas e despreocupadas simplesmente porque passaram por esses experimentos?",
  ui_story_5082_50820301_25_dialog_content = "... Não, senhor.",
  ui_story_5082_50820301_26_dialog_content = "Então eles ainda são soldados da Illumina, e seus camaradas de armas!",
  ui_story_5082_50820301_27_dialog_content = "O sangue e o suor que eles derramaram não são diferentes dos seus!",
  ui_story_5082_50820301_28_dialog_content = "Eles fizeram sacrifícios de maneiras que você nem pode imaginar, tudo pelo futuro da Illumina.",
  ui_story_5082_50820301_29_dialog_content = "Eles não são diferentes de mim de maneira alguma. Olhar para baixo para eles é o mesmo que me menosprezar!",
  ui_story_5082_50820301_30_dialog_content = "Mas se você não tem intenção de me ver como algum tipo de monstro, então nunca esqueça que eles ainda são seus aliados.",
  ui_story_5082_50820301_31_dialog_content = "...",
  ui_story_5082_50820301_32_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5082_50820301_33_dialog_content = "<color=#e8d9bb>Ninguém viu claramente o ataque de Barton. Tudo o que viram foi um lampejo de prata.</color>",
  ui_story_5082_50820301_34_dialog_content = "<color=#e8d9bb>No próximo momento, as armas dos soldados se dividiram em duas e caíram no chão.</color>",
  ui_story_5082_50820301_35_dialog_content = "Desculpe, mas você foi eliminado.",
  ui_story_5082_50820301_36_dialog_content = "Vá para casa e pense muito sobre o que você aprendeu aqui.",
  ui_story_5082_50820301_37_dialog_content = "Sim senhor...",
  ui_story_5082_50820301_38_dialog_content = "E quanto a você, PlayerName.",
  ui_story_5082_50820301_39_dialog_content = "Por que a cara feia? Eles estavam falando sobre nós, soldados modificados, não você.",
  ui_story_5082_50820301_40_dialog_content = "É porque você aceitou as modificações do Chord Link para proteger todos nós...",
  ui_story_5082_50820301_41_dialog_content = "Você ainda está pensando demais para alguém tão exausto.",
  ui_story_5082_50820301_42_dialog_content = "Escute aqui, criança. Eu não concordei com a modificação para proteger vocês; Eu fiz isso para vencer.",
  ui_story_5082_50820301_43_dialog_content = "E o poder que obtive depois é meu. Você viu minha velocidade quando desviei do ataque do Grande Marechal mais cedo, não viu?",
  ui_story_5082_50820301_44_dialog_content = "Ainda é um pouco difícil de controlar, mas todo poder vem com um preço. É perfeitamente razoável, se você me perguntar.",
  ui_story_5082_50820301_45_dialog_content = "Além disso, quem pode dizer que eu não serei o único a manter o Grande Marechal na defensiva uma vez que eu domine esse poder? Hahaha!",
  ui_story_5082_50820301_46_dialog_content = "Estou feliz que isso não parece te afetar... Mas falando de Reinhardt...",
  ui_story_5082_50820301_47_dialog_content = "Algo parece estranho nela. Ela perdeu o foco no meio da batalha tantas vezes hoje.",
  ui_story_5082_50820301_48_dialog_content = "Foi a mesma coisa agora há pouco. Só conseguimos escapar porque ela de repente parou de atacar.",
  ui_story_5082_50820301_49_dialog_content = "Você também notou, hein... Sempre que a Grande Marechal vai para o campo de batalha, ela tem a tendência de estar no centro de tudo.",
  ui_story_5082_50820301_50_dialog_content = "Sejam aliados ou inimigos, ela consegue ditar o ritmo da luta ao seu redor.",
  ui_story_5082_50820301_51_dialog_content = "Mas hoje é diferente. Mesmo que ela continue salvando a situação no final, ela definitivamente não está no controle disso. Na verdade, parece ser o contrário.",
  ui_story_5082_50820301_52_dialog_content = "Isso não é algo que uma \"recaída\" de uma ferida antiga poderia causar.",
  ui_story_5082_50820301_53_dialog_content = "...",
  ui_story_5082_50820301_54_dialog_content = "...",
  ui_story_5082_50820301_55_dialog_content = "Aff...",
  ui_story_5082_50820301_56_dialog_content = "O que foi?",
  ui_story_5082_50820301_57_dialog_content = "Acho que de repente senti algo...",
  ui_story_5082_50820301_58_dialog_content = "Em um lugar como este?",
  ui_story_5082_50820301_59_dialog_content = "Vou tentar obter uma leitura melhor!",
  ui_story_5082_50820301_60_option_content = "Varredura Psíquica!",
  ui_story_5082_50820301_61_dialog_content = "Onde estava...?",
  ui_story_5082_50820301_62_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5082_50820301_63_dialog_content = "O chão... Está tremendo?",
  ui_story_5082_50820301_64_dialog_content = "A presença que senti agora... Eu não a reconheci, mas me conectar com ela me pareceu estranhamente familiar.",
  ui_story_5082_50820301_65_dialog_content = "... É ela.",
  ui_story_5082_50820301_66_dialog_content = "Aí está!",
  ui_story_5082_50820301_67_dialog_content = "Quem é você? E por que você está aqui?",
  ui_story_5082_50820301_68_dialog_content = "É aquela garota...",
  ui_story_5082_50820301_69_dialog_content = "Uma garota? Sobre quem você está falando?",
  ui_story_5082_50820301_70_dialog_content = "A garota com um dragão atrás dela!",
  ui_story_5082_50820301_71_dialog_content = "O que você está—",
  ui_story_5082_50820301_72_dialog_content = "Cuidado, PlayerName!",
  ui_story_5082_50820301_73_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5082_50820302_1_dialog_content = "PlayerName! Tudo bem?!",
  ui_story_5082_50820302_2_dialog_content = "*tosse* Estou bem... Obrigado, Barton.",
  ui_story_5082_50820302_3_dialog_content = "Mas o que fez este prédio desabar? Não há nenhum combate por perto, pelo que eu posso dizer.",
  ui_story_5082_50820302_4_dialog_content = "Venha dar uma olhada nisso.",
  ui_story_5082_50820302_5_dialog_content = "... Que espaço enorme! Tudo está quebrado além do reparo... Que tipo de batalha poderia ter acontecido aqui?",
  ui_story_5082_50820302_6_dialog_content = "Estávamos tão focados no exercício de treinamento que nunca percebemos isso.",
  ui_story_5082_50820302_7_dialog_content = "Mas se uma batalha como essa aconteceu tão perto de Gannon City, não há como teríamos perdido isso.",
  ui_story_5082_50820302_8_dialog_content = "Ou talvez isso tenha acontecido quando desabou naquela época...?",
  ui_story_5082_50820302_9_dialog_content = "Isso mesmo, acabei de sentir uma presença estranha agora mesmo!",
  ui_story_5082_50820302_10_dialog_content = "Continuava dizendo coisas que eu não conseguia entender. Talvez tenha algo a ver com este lugar?",
  ui_story_5082_50820302_11_dialog_content = "Vou tentar sentir novamente—",
  ui_story_5082_50820302_12_dialog_content = "Um momento por favor.",
  ui_story_5082_50820302_13_dialog_content = "... Vivian? O que você está fazendo aqui?",
  ui_story_5082_50820302_14_dialog_content = "Não me diga que estávamos fazendo muito barulho? Hahaha! Não se preocupe, já resolvi o problema.",
  ui_story_5082_50820302_15_dialog_content = "Mas se todos vocês estão aqui, isso significa que estão procurando uma revanche, Grande Marechal?",
  ui_story_5082_50820302_16_dialog_content = "Talvez na próxima vez.",
  ui_story_5082_50820302_17_dialog_content = "Não torne as coisas difíceis para o Grande Marechal, Barton.",
  ui_story_5082_50820302_18_dialog_content = "Vim compartilhar uma notificação importante da sede. Já informei a Grande Marechal e o Philyshy sobre isso.",
  ui_story_5082_50820302_19_dialog_content = "Qual é a situação?",
  ui_story_5082_50820302_20_dialog_content = "Devido a uma falha no registro, só percebemos agora que esta área é estritamente proibida.",
  ui_story_5082_50820302_21_dialog_content = "E considerando a exacerbação dos antigos ferimentos do Grande Marechal, acreditamos que a continuação do exercício de treinamento resultará em mais danos—",
  ui_story_5082_50820302_22_dialog_content = "Portanto, lamento informar que este exercício de treinamento agora está encerrado.",
  ui_story_5082_50820302_23_dialog_content = "Mas eu acabei de sentir...",
  ui_story_5082_50820302_24_dialog_content = "Vamos lidar com o resto do assunto, então por favor entenda, PlayerName. Afinal, é uma área restrita.",
  ui_story_5082_50820302_25_dialog_content = "(Reinhardt parece tão sério. Aconteceu alguma coisa de volta na cidade de Gannon...?)",
  ui_story_5082_50820302_26_dialog_content = "... Multar.",
  ui_story_5082_50820302_27_dialog_content = "Já acabou mesmo? E eu acabei de me aquecer também!",
  ui_story_5082_50820302_28_dialog_content = "Estou entediado de tanto fazer meus soldados passarem pelos mesmos exercícios exatos todos os dias.",
  ui_story_5082_50820302_29_dialog_content = "Esse concurso foi uma mudança de ritmo tão agradável. Encerrar assim deixa um gosto amargo na minha boca.",
  ui_story_5082_50820302_30_dialog_content = "Concordo. Mesmo que o exercício tenha que terminar, eu odiaria estragar a diversão de todos.",
  ui_story_5082_50820302_31_dialog_content = "Já que todos já estão aqui, por que não fazemos uma celebração com fogueira esta noite?",
  ui_story_5082_50820302_32_dialog_content = "Eu posso deixar os preparativos com você, certo Barton?",
  ui_story_5082_50820302_33_dialog_content = "... Ei, você é o chefe por aqui, não é? Claro que eu posso lidar com isso! Vou fazer meus subordinados começarem a mover as coisas imediatamente!",
  ui_story_5082_50820302_34_dialog_content = "Então eu irei com—",
  ui_story_5082_50820302_35_dialog_content = "Ah não! Você vem comigo primeiro!",
  ui_story_5082_50820302_36_dialog_content = "E-Ei! Não me arraste assim, Philyshy! E onde você esteve todo esse tempo, afinal?!",
  ui_story_5082_50820302_37_dialog_content = "Relaxando, naturalmente... Mas parece que até eu estive no escuro sobre este lugar, miau.",
  ui_story_5082_50820302_38_dialog_content = "Eu os ouvi falando agora há pouco.",
  ui_story_5082_50820302_39_dialog_content = "\"Não estamos escondendo nada deles. Simplesmente não é o momento certo, é tudo.\" Foi isso que ouvi o Grande Marechal Reinhardt e o Oficial Vivian dizerem.",
  ui_story_5082_50820302_40_dialog_content = "Agora apresse-se e use seus poderes psíquicos, PlayerName! Eu quero ouvir o que eles estão conversando agora!",
  ui_story_5082_50820302_41_dialog_content = "Isso não é para o que meus poderes servem, Philyshy!",
  ui_story_5082_50820302_42_dialog_content = "Nyeh, você é um verdadeiro estraga-prazeres. Então eu mesmo vou fazer isso!",
  ui_story_5082_50820302_43_dialog_content = "E ela se foi... Não há como impedi-la quando ela está curiosa sobre algo, huh?",
  ui_story_5082_50820302_44_dialog_content = "(Ainda assim, me pergunto o que aconteceu com Reinhardt...)",
  ui_story_5082_50820401_1_dialog_content = "<color=#e8d9bb>No meio da noite, durante a fogueira...</color>",
  ui_story_5082_50820401_2_dialog_content = "... Venha.",
  ui_story_5082_50820401_3_dialog_content = "Essa presença... É você de novo!",
  ui_story_5082_50820401_4_dialog_content = "Você é o que me sentiu... Celestita.",
  ui_story_5082_50820401_5_dialog_content = "Você me conhece? Quem é você? E por que está me procurando?",
  ui_story_5082_50820401_6_dialog_content = "Ajude-me a deixar este lugar.",
  ui_story_5082_50820401_7_dialog_content = "!!!",
  ui_story_5082_50820401_8_dialog_content = "Você é uma Colossus?!",
  ui_story_5082_50820401_9_dialog_content = "Eles me chamam de Ponta de Lança.",
  ui_story_5082_50820401_10_dialog_content = "Quando a Illumina colocou as mãos em um Colosso consciente?!",
  ui_story_5082_50820401_11_dialog_content = "Espere um minuto... Um Colosso consciente... Isso significa que você tem um Navegador Celestita como eu?",
  ui_story_5082_50820401_12_dialog_content = "&>!#%$^!#$",
  ui_story_5082_50820401_13_dialog_content = "Illumina! As pessoas deles não podem ser confiadas!",
  ui_story_5082_50820401_14_dialog_content = "Eles me prenderam! Me alteraram! Eles querem me transformar em uma arma de guerra!",
  ui_story_5082_50820401_15_dialog_content = "Tentei escapar tantas vezes, apenas para ser destruído na minha última tentativa.",
  ui_story_5082_50820401_16_dialog_content = "Era aquela garota... a garota com um $^%%$ atrás dela!",
  ui_story_5082_50820401_17_dialog_content = "(Uma garota? E tem algo atrás dela...?)",
  ui_story_5082_50820401_18_dialog_content = "^#!^#%$&&! ^&*tite... Venha me encontrar.",
  ui_story_5082_50820401_19_dialog_content = "Venha me encontrar.",
  ui_story_5082_50820401_20_dialog_content = "Onde você tá?",
  ui_story_5082_50820401_21_dialog_content = "Venha me encontrar. Ajude-me a sair—",
  ui_story_5082_50820401_22_dialog_content = "Espere, ainda tenho mais perguntas para lhe fazer!",
  ui_story_5082_50820401_23_dialog_content = "Sobre os Celestitas e Eraveil! Sobre Soroz e—",
  ui_story_5082_50820401_24_dialog_content = "Então venha me encontrar—",
  ui_story_5082_50820401_25_dialog_content = "Ei!",
  ui_story_5082_50820401_26_dialog_content = "O que há de errado, criança? Saia dessa!",
  ui_story_5082_50820401_27_dialog_content = "Agora mesmo, eu...",
  ui_story_5082_50820401_28_dialog_content = "Heh, com medo dos seus próprios sonhos, hein? Parece que você definitivamente precisa de mais treinamento.",
  ui_story_5082_50820401_29_dialog_content = "Miau... Eu sei tudo sobre conseguir muito sono tranquilo. Você deveria tentar aprender comigo alguma vez!",
  ui_story_5082_50820401_30_dialog_content = "Isso não pareceu um sonho agora...",
  ui_story_5082_50820401_31_dialog_content = "Eu tenho que ir procurá-lo!",
  ui_story_5082_50820401_32_dialog_content = "Ei, aonde você pensa que está indo?! Pelo menos espere por nós—",
  ui_story_5082_50820401_33_dialog_content = "*bocejo* Não parece que o Grande Marechal ou o Oficial Vivian estão por perto também.",
  ui_story_5082_50820401_34_dialog_content = "Mesmo que eu mal consiga sentir, posso dizer que está em algum lugar nesta direção. As ruínas onde o exercício de ontem foi cancelado...",
  ui_story_5082_50820401_35_dialog_content = "Hã? Ouço vozes à frente...",
  ui_story_5082_50820401_36_dialog_content = "PlayerName? Não te disse que esta é uma área restrita?",
  ui_story_5082_50820401_37_dialog_content = "Está bem, Vivian. PlayerName não viria correndo para cá se não fosse por um bom motivo.",
  ui_story_5082_50820401_38_dialog_content = "Reinhardt, Vivian... Eu...",
  ui_story_5082_50820401_39_dialog_content = "Esta é uma reunião bastante grande, e no meio da noite. Estamos decidindo se devemos ou não reiniciar o exercício de treinamento?",
  ui_story_5082_50820401_40_dialog_content = "Prefiro estar dormindo, mas não se isso significa perder algo importante.",
  ui_story_5082_50820401_41_dialog_content = "Sinto a presença de um Colosso em algum lugar por perto!",
  ui_story_5082_50820401_42_dialog_content = "!",
  ui_story_5082_50820401_43_dialog_content = "... Eu sabia.",
  ui_story_5082_50820401_44_dialog_content = "Diga, este não é a base de pesquisa onde os experimentos do navegador reserva foram realizados, é?",
  ui_story_5082_50820401_45_dialog_content = "Base de pesquisa... você quer dizer aquela que explodiu todos aqueles anos atrás?",
  ui_story_5082_50820401_46_dialog_content = "... Eu me lembro de Vice dizer que ela participou de algo chamado \"Projeto: Navegador.\"",
  ui_story_5082_50820401_47_dialog_content = "Mas aparentemente o projeto foi um fracasso, e Vice perdeu a maioria de suas memórias de antes e depois desse tempo.",
  ui_story_5082_50820401_48_dialog_content = "A Illumina estava tentando treinar alguém para ser o Navegador da Spearhead?",
  ui_story_5082_50820401_49_dialog_content = "Espere... Vice devia ser uma garotinha quando isso aconteceu, certo?",
  ui_story_5082_50820401_50_dialog_content = "Todos vocês estão corretos. Durante a Crise Darkover, a Illumina lançou esse programa para melhorar nossas chances de um futuro mais brilhante.",
  ui_story_5082_50820401_51_dialog_content = "Mas perdemos muitas pessoas e a base de pesquisa foi enterrada no subsolo. Nossos registros do incidente também são poucos e esparsos...",
  ui_story_5082_50820401_52_dialog_content = "Esse programa trouxe vergonha para toda a Illumina e para mim... Ser incapaz de conduzir uma investigação de acompanhamento, apesar do meu envolvimento no programa, foi ainda mais vergonhoso.",
  ui_story_5082_50820401_53_dialog_content = "... Isso significa que você participou do experimento junto com Vice.",
  ui_story_5082_50820401_54_dialog_content = "Não. Fui eu quem destruiu.",
  ui_story_5082_50820401_55_dialog_content = "...",
  ui_story_5082_50820401_56_dialog_content = "Disseram que eu resgatei Vice, mas para dizer a verdade, nada disso pareceu especialmente real para mim.",
  ui_story_5082_50820401_57_dialog_content = "E foi assim que me senti até a batalha de ontem com Barton. Quando lutamos, memórias começaram a surgir em minha mente...",
  ui_story_5082_50820401_58_dialog_content = "Tive a sensação de que um segredo estava enterrado em algum lugar aqui, então vim ver por mim mesmo.",
  ui_story_5082_50820401_59_dialog_content = "O que você disse agora confirmou minhas suspeitas, PlayerName.",
  ui_story_5082_50820401_60_dialog_content = "Esse Colosso nunca foi movido deste lugar.",
  ui_story_5082_50820401_61_dialog_content = "—Está bem abaixo de nossos pés.",
  ui_story_5082_50820401_62_dialog_content = "... Se realmente for o caso, então preciso ir ver.",
  ui_story_5082_50820401_63_dialog_content = "Vice nunca disse isso, mas tenho certeza de que qualquer um ficaria incomodado se perdesse suas memórias.",
  ui_story_5082_50820401_64_dialog_content = "Ela me ajudou tanto desde que nos conhecemos. É apenas certo que eu faça algo por ela.",
  ui_story_5082_50820401_65_dialog_content = "Como esta é uma área restrita, permitir que você entre seria uma violação das regulamentações da Illumina.",
  ui_story_5082_50820401_66_dialog_content = "Mas…",
  ui_story_5082_50820401_67_dialog_content = "No entanto, o Grande Marechal também está presente.",
  ui_story_5082_50820401_68_dialog_content = "Com o consentimento dela, você pode receber permissão para entrar.",
  ui_story_5082_50820401_69_dialog_content = "Eu já estava planejando descer lá de qualquer maneira. Eu não me importaria se PlayerName fosse junto.",
  ui_story_5082_50820401_70_dialog_content = "Mas você tem que me prometer algo.",
  ui_story_5082_50820401_71_dialog_content = "Pode ser diferente do que você sabe, mas de acordo com séculos de relatórios de inteligência da Illumina—",
  ui_story_5082_50820401_72_dialog_content = "Dos Colossi que você encontrou até agora, este pode ser muito mais hostil do que você espera.",
  ui_story_5082_50820401_73_dialog_content = "Tenho certeza de que não tinha muitas coisas boas para dizer sobre a Illumina quando entrou em contato com você.",
  ui_story_5082_50820401_74_dialog_content = "... Isso é verdade.",
  ui_story_5082_50820401_75_dialog_content = "Depois do incidente com o Engenheiro, jurei que não correria o risco de deixar você sentir algo perigoso assim nunca mais.",
  ui_story_5082_50820401_76_dialog_content = "Especialmente quando o perigo é direcionado à Illumina.",
  ui_story_5082_50820401_77_dialog_content = "Mas dizer para você não usar seus poderes psíquicos únicos não é diferente de dizer para você não respirar.",
  ui_story_5082_50820401_78_dialog_content = "Tudo que peço é que me diga quando sentir algo no momento em que acontecer.",
  ui_story_5082_50820401_79_dialog_content = "Então, posso fazer um pedido também?",
  ui_story_5082_50820401_80_dialog_content = "Vá em frente, estou ouvindo.",
  ui_story_5082_50820401_81_dialog_content = "Não vou tentar esconder nada que eu sinta, mas gostaria que todos seguissem a mesma regra.",
  ui_story_5082_50820401_82_dialog_content = "Se algo parece estranho, ou se você se sente um pouco estranho...",
  ui_story_5082_50820401_83_dialog_content = "Mesmo que você pense que não é grande coisa, por favor, informe ao grupo imediatamente. Dessa forma, podemos trabalhar em uma solução juntos.",
  ui_story_5082_50820401_84_dialog_content = "Você amadureceu muito mais desde que nos conhecemos pela primeira vez.",
  ui_story_5082_50820401_85_dialog_content = "Combinado.",
  ui_story_5082_50820401_86_dialog_content = "Eu não me importo particularmente com este incidente, mas teve um enorme e duradouro efeito em Illumina. Se você vai investigar isso, então pode me incluir.",
  ui_story_5082_50820401_87_dialog_content = "Para ser honesto, eu realmente não sinto vontade de me juntar a todos.",
  ui_story_5082_50820401_88_dialog_content = "Mas essas ruínas estão escondendo algo que eu quero saber, então acho que vou acompanhar também.",
  ui_story_5082_50820401_89_dialog_content = "Acontece que estamos indo na mesma direção, então não espere que eu ajude muito!",
  ui_story_5082_50820401_90_dialog_content = "O que vamos fazer com você, Philyshy...",
  ui_story_5082_50820401_91_dialog_content = "Certo, chega de enrolação. Eu vou liderar o caminho, agora vamos!",
  ui_story_5082_50820401_92_dialog_content = "Acho que devo explorar um caminho primeiro, Barton. Não se preocupe, não vou tentar sentir o Colosso.",
  ui_story_5082_50820401_93_dialog_content = "Vou dar uma olhada em nossos arredores para garantir que estão seguros antes de seguirmos em frente.",
  ui_story_5082_50820401_94_dialog_content = "*Tosse* O espaço abaixo de nós é enorme, mas é principalmente um monte de ruínas...",
  ui_story_5082_50820401_95_dialog_content = "<color=#e8d9bb>Desmoronar...</color>",
  ui_story_5082_50820401_96_dialog_content = "Uau! Quase tropecei agora mesmo.",
  ui_story_5082_50820401_97_dialog_content = "O chão está coberto de fios. Cuidado com o passo, pessoal.",
  ui_story_5082_50820401_98_dialog_content = "<color=#e8d9bb>Bzzz—</color>",
  ui_story_5082_50820401_99_dialog_content = "Que som é esse?",
  ui_story_5082_50820401_100_dialog_content = "Miau! Algo está voando em nossa direção!",
  ui_story_5082_50820401_101_dialog_content = "Zumbido—",
  ui_story_5082_50820401_102_dialog_content = "Desvie, PlayerName!",
  ui_story_5082_50820401_103_dialog_content = "—!",
  ui_story_5082_50820401_104_dialog_content = "...",
  ui_story_5082_50820401_105_dialog_content = "PlayerName? PlayerName!",
  ui_story_5082_50820401_106_dialog_content = "Acho que ouvi alguém gritando meu nome.",
  ui_story_5082_50820501_1_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820501_2_dialog_content = "Foi isso... um clarim?",
  ui_story_5082_50820501_3_dialog_content = "Eu poderia jurar que ouvi uma garota gritando agora há pouco... Hã?",
  ui_story_5082_50820501_4_dialog_content = "Isso é... uma academia militar?",
  ui_story_5082_50820501_5_dialog_content = "Uau! Reinhardt vence novamente!!",
  ui_story_5082_50820501_6_dialog_content = "Reinhardt?",
  ui_story_5082_50820501_7_dialog_content = "Alguém mais sente vontade de intensificar?",
  ui_story_5082_50820501_8_dialog_content = "Dê um descanso, Reinhardt. Você já venceu todos na escola inteira; ninguém é burro o suficiente para desafiá-lo mais.",
  ui_story_5082_50820501_9_dialog_content = "Sim, mas você ainda não desistiu, certo?",
  ui_story_5082_50820501_10_dialog_content = "Eu simplesmente não tenho vontade de te vencer em algo tão estúpido quanto uma queda de braço.",
  ui_story_5082_50820501_11_dialog_content = "Nossa instrutora diz que vamos fazer um percurso de obstáculos depois da aula hoje. É quando finalmente vou colocar você no seu lugar.",
  ui_story_5082_50820501_12_dialog_content = "Reinhardt ficou em primeiro lugar no percurso de obstáculos novamente! A pessoa em segundo lugar estava mais de dez segundos mais lenta também!",
  ui_story_5082_50820501_13_dialog_content = "Isso não é surpreendente. Quando ela NÃO esteve em primeiro lugar?",
  ui_story_5082_50820501_14_dialog_content = "Então, quem ficou em segundo? Não me diga que foi o Wrath de novo?",
  ui_story_5082_50820501_15_dialog_content = "Com certeza foi!",
  ui_story_5082_50820501_16_dialog_content = "Sempre foi assim desde que entrei na academia e me tornei colega de classe deles. Todo concurso termina exatamente da mesma maneira para eles.",
  ui_story_5082_50820501_17_dialog_content = "Sinceramente, me sinto tão inútil comparado a eles.",
  ui_story_5082_50820501_18_dialog_content = "Colônia, Vaughn.",
  ui_story_5082_50820501_19_dialog_content = "Estou ouvindo coisas, ou Reinhardt acabou de dizer nossos nomes?",
  ui_story_5082_50820501_20_dialog_content = "Tenho certeza que também ouvi.",
  ui_story_5082_50820501_21_dialog_content = "É porque estou chamando vocês, agora venham aqui!",
  ui_story_5082_50820501_22_dialog_content = "O-Por quê...",
  ui_story_5082_50820501_23_dialog_content = "Por que Reinhardt sabe nossos nomes?!",
  ui_story_5082_50820501_24_dialog_content = "Eu estava assistindo à batalha simulada da sua turma agora mesmo.",
  ui_story_5082_50820501_25_dialog_content = "Cologne, suas habilidades de logística são algumas das mais eficazes que vi neste ano.",
  ui_story_5082_50820501_26_dialog_content = "E Vaughn, sua velocidade de reação também não é motivo para risos.",
  ui_story_5082_50820501_27_dialog_content = "Então, pensei em vir e dizer oi. Se a oportunidade surgir, eu realmente gostaria de me juntar a vocês dois.",
  ui_story_5082_50820501_28_dialog_content = "Reinhardt! O instrutor ordenou que nos reuníssemos!",
  ui_story_5082_50820501_29_dialog_content = "Tenho que ir! Vejo vocês por aí.",
  ui_story_5082_50820501_30_dialog_content = "Reinhardt... disse que estava impressionada conosco.",
  ui_story_5082_50820501_31_dialog_content = "Ei... Devemos correr algumas voltas na pista?",
  ui_story_5082_50820501_32_dialog_content = "Sim! Vamos lá! Agora mesmo!",
  ui_story_5082_50820501_33_dialog_content = "Alinhar!",
  ui_story_5082_50820501_34_dialog_content = "Todos vocês foram designados para uma missão urgente.",
  ui_story_5082_50820501_35_dialog_content = "Recentemente, várias Subcidades, incluindo as Subcidades 38, 42 e 59, foram atacadas simultaneamente por um novo tipo de Eclipsita.",
  ui_story_5082_50820501_36_dialog_content = "Esses novos Eclipsitas não são particularmente poderosos, mas compensam isso com seu número esmagador, que ainda está crescendo. As condições de vida e a produtividade dessas Subcidades já foram seriamente impactadas!",
  ui_story_5082_50820501_37_dialog_content = "Vocês serão divididos em três pequenas equipes e enviados para as seguintes Subcidades para fornecer suporte.",
  ui_story_5082_50820501_38_dialog_content = "Sim, senhor!",
  ui_story_5082_50820501_39_dialog_content = "...",
  ui_story_5082_50820501_40_dialog_content = "<color=#e8d9bb>Depois que a crise terminou</color>",
  ui_story_5082_50820501_41_dialog_content = "Reinhardt!",
  ui_story_5082_50820501_42_dialog_content = "Suas ordens eram para liderar sua equipe até a Subcidade 42 e fornecer reforços! O que você está fazendo na Subcidade 28?!",
  ui_story_5082_50820501_43_dialog_content = "Senhor! Quando recebemos nossas tarefas, notei que as Cidades Baixas em questão eram relativamente distantes uma da outra.",
  ui_story_5082_50820501_44_dialog_content = "Para o mesmo tipo de Eclipsita aparecer em cada Subcidade ao mesmo tempo, deve haver algum tipo de conexão entre eles.",
  ui_story_5082_50820501_45_dialog_content = "Após chegar na Subcidade 42 e despachar os Eclipsitas lá, determinei que eles eram extremamente vulneráveis ao ataque.",
  ui_story_5082_50820501_46_dialog_content = "No entanto, descobri a presença de um Eclipsite único em meio a eles, um que se move rapidamente e parece ser capaz de regeneração rápida!",
  ui_story_5082_50820501_47_dialog_content = "Após mais observações, confirmei que este tipo de Eclipsite compartilha várias características com plantas esporíferas.",
  ui_story_5082_50820501_48_dialog_content = "E depois de cruzar referências no meu mapa, percebi que todas essas Subcidades estão diretamente conectadas por ferrovias, com a Subcidade 28 no centro.",
  ui_story_5082_50820501_49_dialog_content = "Isso me leva a acreditar que esses Eclipsitas se propagaram para cada uma das Subcidades afetadas através de nossos carrinhos de ferrovia, e que o corpo principal está localizado em algum lugar na Subcidade 28.",
  ui_story_5082_50820501_50_dialog_content = "Então eu trouxe minha equipe aqui para caçar e destruir a fonte da invasão!",
  ui_story_5082_50820501_51_dialog_content = "Depois, recebi confirmação das outras Subcidades de que os Eclipsitas não estavam mais aumentando em número.",
  ui_story_5082_50820501_52_dialog_content = "... Você descobriu! Você determinou! Você observou!",
  ui_story_5082_50820501_53_dialog_content = "Não estou perguntando sobre o que você fez, Reinhardt! Estou perguntando por que você fez isso!!",
  ui_story_5082_50820501_54_dialog_content = "Você acha que seus superiores são um bando de tolos? Você acha que é o soldado mais inteligente da Illumina só porque descobriu a verdade?!",
  ui_story_5082_50820501_55_dialog_content = "Abandonando sua missão, agindo por conta própria e ignorando ordens urgentes para recuar! E você se chama de soldado?",
  ui_story_5082_50820501_56_dialog_content = "Estou ciente das consequências das minhas ações e estou preparado para aceitar qualquer punição! No entanto, ainda acredito que erradicar a fonte da invasão do Eclipsite o mais rápido possível foi a melhor escolha de ação!",
  ui_story_5082_50820501_57_dialog_content = "Caia fora daqui!!!",
  ui_story_5082_50820501_58_dialog_content = "!",
  ui_story_5082_50820501_59_dialog_content = "Você estava esperando por mim ou algo assim?",
  ui_story_5082_50820501_60_dialog_content = "Só vim entregar meu relatório de trabalho para o instrutor.",
  ui_story_5082_50820501_61_dialog_content = "... Você está bem?",
  ui_story_5082_50820501_62_dialog_content = "Por que eu não estaria? Eu só levei uma bronca, só isso.",
  ui_story_5082_50820501_63_dialog_content = "Eu gostaria de saber por que o instrutor tinha algo contra mim.",
  ui_story_5082_50820501_64_dialog_content = "É realmente isso que está em sua mente? Deixa para lá.",
  ui_story_5082_50820501_65_dialog_content = "No final do dia, ambos fomos enviados para as Subcidades para fornecer reforço, mas eu não consegui descobrir a verdade por trás desses Eclipsitas. Parece que você ganha novamente, Reinhardt.",
  ui_story_5082_50820501_66_dialog_content = "Mas marque minhas palavras! Eu não vou perder para você na próxima vez!",
  ui_story_5082_50820501_67_dialog_content = "Claro.",
  ui_story_5082_50820501_68_dialog_content = "... O que foi isso? Eu te desafio, e é tudo que você tem a dizer?",
  ui_story_5082_50820501_69_dialog_content = "Você me desafia todos os dias, não é?",
  ui_story_5082_50820501_70_dialog_content = "É por isso que estou sempre preparado para qualquer coisa.",
  ui_story_5082_50820501_71_dialog_content = "Não... Não se atreva a menosprezar meus desafios!",
  ui_story_5082_50820501_72_dialog_content = "Você é a única pessoa digna de ser meu rival, então até eu te derrotar, você não tem permissão para perder para mais ninguém!",
  ui_story_5082_50820501_73_dialog_content = "Haha, vou fazer o meu melhor.",
  ui_story_5082_50820501_74_dialog_content = "(Então isso aconteceu no passado.)",
  ui_story_5082_50820501_75_dialog_content = "(Reinhardt e Wrath eram tão próximos durante seus dias de academia...)",
  ui_story_5082_50820501_76_dialog_content = "Capitão! É uma emergência—",
  ui_story_5082_50820501_77_dialog_content = "(A cena está mudando novamente...)",
  ui_story_5082_50820501_78_dialog_content = "Ahn???",
  ui_story_5082_50820501_79_dialog_content = "Pare-!",
  ui_story_5082_50820501_80_dialog_content = "O treinamento de hoje acabou, agora volte para o seu quartel! O toque de recolher está em vigor, então não saia depois de escurecer!",
  ui_story_5082_50820501_81_dialog_content = "Ufa, que bom que acabou. Estou arrasado...",
  ui_story_5082_50820501_82_dialog_content = "Ainda é um pouco cedo, não é? Geralmente o instrutor acrescenta treinamento extra se terminarmos tão cedo.",
  ui_story_5082_50820501_83_dialog_content = "Quem se importa? Isso apenas significa que temos mais tempo para relaxar! Certo, Reinhardt?",
  ui_story_5082_50820501_84_dialog_content = "... Reinhardt?",
  ui_story_5082_50820501_85_dialog_content = "Ei! Onde você está indo?",
  ui_story_5082_50820501_86_dialog_content = "Para se meter em mais problemas.",
  ui_story_5082_50820501_87_dialog_content = "Então eu vou também.",
  ui_story_5082_50820501_88_dialog_content = "Não ouviu o que eu acabei de dizer?",
  ui_story_5082_50820501_89_dialog_content = "Você está me subestimando?",
  ui_story_5082_50820501_90_dialog_content = "Se você fosse realmente tão imprudente e inconsiderado, eu não te consideraria meu rival, não importa o quão forte você fosse.",
  ui_story_5082_50820501_91_dialog_content = "O instrutor estava te encarando com raiva até agora, e ainda assim você está obstinado a sair sorrateiramente. Por quê? O que você descobriu?",
  ui_story_5082_50820501_92_dialog_content = "Uma invasão Eclipsita.",
  ui_story_5082_50820501_93_dialog_content = "O quê?!",
  ui_story_5082_50820501_94_dialog_content = "Roooor!",
  ui_story_5082_50820501_95_dialog_content = "Comandante! Os Eclipsitas continuam chegando, mas não temos soldados suficientes para contê-los! Solicitando—",
  ui_story_5082_50820501_96_dialog_content = "Mantenha-os à distância mesmo que custe suas vidas!",
  ui_story_5082_50820501_97_dialog_content = "De onde no mundo vieram todos esses Eclipsitas—",
  ui_story_5082_50820501_98_dialog_content = "*Rugido*",
  ui_story_5082_50820501_99_dialog_content = "Ah...",
  ui_story_5082_50820501_100_dialog_content = "Mantenha a linha!",
  ui_story_5082_50820501_101_dialog_content = "Malditos monstros imundos!",
  ui_story_5082_50820501_102_dialog_content = "Avanço tudo!",
  ui_story_5082_50820501_103_dialog_content = "Golpe! Richthofen!",
  ui_story_5082_50820501_104_dialog_content = "O que você está fazendo aqui?!",
  ui_story_5082_50820501_105_dialog_content = "Como eu disse, eu não vou perder para você!",
  ui_story_5082_50820501_106_dialog_content = "Graaah...",
  ui_story_5082_50820501_107_dialog_content = "Estudantes?",
  ui_story_5082_50820501_108_dialog_content = "Estudante da Academia Militar Illumina Reinhardt, relatando para o dever de apoio!",
  ui_story_5082_50820501_109_dialog_content = "Estudante da Academia Militar de Illumina Wrath, relatando para o dever de apoio!",
  ui_story_5082_50820501_110_dialog_content = "Pare de brincar e volte!",
  ui_story_5082_50820501_111_dialog_content = "Vou relatar pessoalmente ao meu instrutor depois que isso acabar, mas como cidadão de Illumina, me recuso a ficar parado enquanto os Eclipsitas invadem nossa casa!",
  ui_story_5082_50820501_112_dialog_content = "Por favor, me designe para a defesa do flanco esquerdo!",
  ui_story_5082_50820501_113_dialog_content = "E, por favor, me designe para o certo!",
  ui_story_5082_50820501_114_dialog_content = "Vocês dois? Isso é algum tipo de piada?!",
  ui_story_5082_50820501_115_dialog_content = "Nós podemos vencer, eu prometo.",
  ui_story_5082_50820501_116_dialog_content = "Além disso, não somos os únicos aqui para ajudar.",
  ui_story_5082_50820501_117_dialog_content = "Dois Eclipsitas estão tentando nos emboscar de um buraco à uma hora! Deixe-os comigo!",
  ui_story_5082_50820501_118_dialog_content = "A Legião Médica cuidará dos gravemente feridos! Vamos administrar primeiros socorros para ferimentos leves aqui!",
  ui_story_5082_50820501_119_dialog_content = "Permita-me apresentar meus colegas de classe e camaradas de armas: Vaughn e Cologne.",
  ui_story_5082_50820501_120_dialog_content = "Parece que esta é a nossa chance de finalmente nos unirmos, Reinhardt!",
  ui_story_5082_50820501_121_dialog_content = "Perdoe-nos, comandante, mas cada soldado tem o dever de defender a Illumina, até mesmo os soldados em treinamento!",
  ui_story_5082_50820501_122_dialog_content = "Haha, guarde suas desculpas para mais tarde!",
  ui_story_5082_50820501_123_dialog_content = "Peguem suas armas e preparem-se para enfrentar os Eclipsitas!",
  ui_story_5082_50820501_124_dialog_content = "Entendido!",
  ui_story_5082_50820501_125_dialog_content = "E desde quando você foi promovido a comandante, hein?!",
  ui_story_5082_50820501_126_dialog_content = "... Reinhardt.",
  ui_story_5082_50820501_127_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_5082_50820501_128_dialog_content = "Alinhe-se e comece o treinamento!",
  ui_story_5082_50820501_129_dialog_content = "Sim, senhor!",
  ui_story_5082_50820501_130_dialog_content = "Sem chance. O instrutor está realmente nos deixando escapar depois do desastre de ontem?",
  ui_story_5082_50820501_131_dialog_content = "Reinhardt e Wrath também não parecem estar em apuros, mas isso só me deixa ainda mais nervoso...",
  ui_story_5082_50820501_132_dialog_content = "Espere, olhe! Não é aquele o Comandante da 1ª Legião? O que ele está fazendo aqui?!",
  ui_story_5082_50820501_133_dialog_content = "Aluno da Academia Reinhardt! Saia e vá para o escritório do seu instrutor!",
  ui_story_5082_50820501_134_dialog_content = "Sim, senhor!",
  ui_story_5082_50820501_135_dialog_content = "...",
  ui_story_5082_50820501_136_dialog_content = "<color=#e8d9bb>Sala de Guerra Nº 3</color>",
  ui_story_5082_50820501_137_dialog_content = "Saudações, Comandante!",
  ui_story_5082_50820501_138_dialog_content = "Devido ao seu excelente desempenho individual, preparamos uma série de experimentos de treinamento especial apenas para você.",
  ui_story_5082_50820501_139_dialog_content = "*Rugido*",
  ui_story_5082_50820501_140_dialog_content = "Esses Eclipsitas sujeitos de teste são uma parte crucial do treinamento.",
  ui_story_5082_50820501_141_dialog_content = "Em alguns momentos, estarei liberando-os na área de combate. Gostaria que você lutasse contra eles usando todo o seu poder.",
  ui_story_5082_50820501_142_dialog_content = "Tch... Esses caras batem bem forte.",
  ui_story_5082_50820501_143_dialog_content = "Os Eclipsitas que você está enfrentando atualmente são os espécimes mais fracos no experimento.",
  ui_story_5082_50820501_144_dialog_content = "Este treinamento é projetado para transformá-lo no soldado mais poderoso da Illumina. Se você não conseguir derrotá-los, teremos que reconsiderar sua candidatura ao programa.",
  ui_story_5082_50820501_145_dialog_content = "O soldado mais poderoso da Illumina, huh? Heh... Quem disse que eu não poderia derrotá-los?!",
  ui_story_5082_50820501_146_dialog_content = "Vamos de novo!",
  ui_story_5082_50820502_1_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5082_50820502_2_dialog_content = "Você chama isso de soco?! Pare de se conter já!",
  ui_story_5082_50820502_3_dialog_content = "Hahaha, desculpe. Vamos de novo.",
  ui_story_5082_50820502_4_dialog_content = "Você é tão... Espera, o que aconteceu com as suas mãos?!",
  ui_story_5082_50820502_5_dialog_content = "É de ontem—",
  ui_story_5082_50820502_6_dialog_content = "Aluno da Academia Reinhardt! Desça e se reporte à instalação de treinamento especial!",
  ui_story_5082_50820502_7_dialog_content = "Sim, senhor.",
  ui_story_5082_50820502_8_dialog_content = "Instrutor! As mãos de Reinhardt estão muito feridas para continuar o treinamento! Por favor, dê a ela um dia para se recuperar!",
  ui_story_5082_50820502_9_dialog_content = "Aluno da Academia Reinhardt! Relate-se à instalação de treinamento especial!",
  ui_story_5082_50820502_10_dialog_content = "Instrutor—",
  ui_story_5082_50820502_11_dialog_content = "Wrath.",
  ui_story_5082_50820502_12_dialog_content = "Instrutor! Por favor, desculpe a interrupção, mas quanto tempo mais continuará o treinamento especial de Reinhardt?",
  ui_story_5082_50820502_13_dialog_content = "Um soldado jura cumprir suas ordens. Ela continuará com seu treinamento pelo tempo que suas ordens ditarem!",
  ui_story_5082_50820502_14_dialog_content = "... Entendido, senhor.",
  ui_story_5082_50820502_15_dialog_content = "(As mãos dela... Seriam essas as \"velhas feridas\" Reinhardt mencionadas anteriormente?)",
  ui_story_5082_50820502_16_dialog_content = "(Não importa o quão especial seja o treinamento, não vale a pena fazer isso com seu próprio corpo.)",
  ui_story_5082_50820502_17_dialog_content = "(Os Eclipsitas não vão dar a mínima para suas mãos doendo.)",
  ui_story_5082_50820502_18_dialog_content = "(É a voz do instrutor?)",
  ui_story_5082_50820502_19_dialog_content = "(... A academia recebe sua cota de encrenqueiros todos os anos, mas esta é a primeira vez que vejo um aluno tão promissor desrespeitar ordens com total impunidade...)",
  ui_story_5082_50820502_20_dialog_content = "(Você merece ser colocado no seu lugar mais do que qualquer outra pessoa! Se você adora lutar contra Eclipsitas tanto assim, vamos deixar você lutar com eles até se cansar!)",
  ui_story_5082_50820502_21_dialog_content = "(Esse cara é horrível!)",
  ui_story_5082_50820502_22_dialog_content = "—!",
  ui_story_5082_50820502_23_dialog_content = "(É o grito daquela garota de novo.)",
  ui_story_5082_50820502_24_dialog_content = "(Quem ela poderia ser—)",
  ui_story_5082_50820502_25_dialog_content = "!",
  ui_story_5082_50820601_1_dialog_content = "Nossa!",
  ui_story_5082_50820601_2_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5082_50820601_3_dialog_content = "Uma pedra...",
  ui_story_5082_50820601_4_dialog_content = "Foi por pouco! Se PlayerName tivesse notado um segundo antes, estaríamos todos tão achatados quanto panquecas agora!",
  ui_story_5082_50820601_5_dialog_content = "Eu vou explorar à frente. O resto de vocês espera aqui por mim.",
  ui_story_5082_50820601_6_dialog_content = "Eu irei com voce.",
  ui_story_5082_50820601_7_dialog_content = "O que é, PlayerName? Você parece que tem algo a dizer.",
  ui_story_5082_50820601_8_dialog_content = "Aquela pedra grande agora... eu nem a percebi.",
  ui_story_5082_50820601_9_dialog_content = "Senti uma garota agora mesmo... Ou pelo menos acho que senti. De qualquer forma, ela me assustou a ponto de me fazer pular de lado.",
  ui_story_5082_50820601_10_dialog_content = "Ela estava... Brilhando em vermelho, por acaso?",
  ui_story_5082_50820601_11_dialog_content = "Como você sabia?",
  ui_story_5082_50820601_12_dialog_content = "Porque eu a vi nas minhas memórias ontem.",
  ui_story_5082_50820601_13_dialog_content = "...",
  ui_story_5082_50820601_14_dialog_content = "Você tem algo para me dizer desde ontem, certo?",
  ui_story_5082_50820601_15_dialog_content = "Não só eu.",
  ui_story_5082_50820601_16_dialog_content = "Barton, Philyshy... Todos estão preocupados com você.",
  ui_story_5082_50820601_17_dialog_content = "É realmente tão óbvio que algo está errado comigo?",
  ui_story_5082_50820601_18_dialog_content = "Aprecio a preocupação, mas não há necessidade de se preocupar assim, PlayerName.",
  ui_story_5082_50820601_19_dialog_content = "Não tenho tempo para desperdiçar com sentimentalismo, e não é como se eu não pudesse te contar sobre o que aconteceu também.",
  ui_story_5082_50820601_20_dialog_content = "Durante o treinamento de ontem, de repente me lembrei de um monte de coisas das quais não tenho lembrança.",
  ui_story_5082_50820601_21_dialog_content = "Pessoas, lugares, emoções... tudo parecia tão desconhecido.",
  ui_story_5082_50820601_22_dialog_content = "Infelizmente, essas memórias passaram pela minha mente tão rapidamente que eu não consegui dizer... Se realmente atirei naquela garota até a morte.",
  ui_story_5082_50820601_23_dialog_content = "Sh-Atirou nela...?! Isso é o \"segredo enterrado\" que você estava falando? Então aquele grito que eu ouvi mais cedo...",
  ui_story_5082_50820601_24_dialog_content = "As memórias ainda estão muito fragmentadas para eu entendê-las... Eu nem mesmo consigo me lembrar do nome dela.",
  ui_story_5082_50820601_25_dialog_content = "O que é estranho, considerando que me lembro de cada pessoa que frequentou a academia comigo.",
  ui_story_5082_50820601_26_dialog_content = "A academia? Isso mesmo. Eu também tenho algumas lembranças dos seus dias de treinamento.",
  ui_story_5082_50820601_27_dialog_content = "Mas aquela garota nunca apareceu em nenhum deles.",
  ui_story_5082_50820601_28_dialog_content = "Ah! Me-desculpe, eu não queria bisbilhotar o seu passado assim.",
  ui_story_5082_50820601_29_dialog_content = "Tudo bem, eu não me importo particularmente. Ainda assim, estou curioso para ouvir sobre o que você viu nas minhas memórias.",
  ui_story_5082_50820601_30_dialog_content = "Bem, houve uma parte em que você estava disputando braço de ferro no campo de treinamento... E uma parte em que você salvou várias Subcidades desobedecendo as ordens do seu comandante...",
  ui_story_5082_50820601_31_dialog_content = "Eu também vi o que aconteceu com você durante seu \"treinamento especial...\"",
  ui_story_5082_50820601_32_dialog_content = "Haha, acho que me lembro de todas essas coisas acontecendo.",
  ui_story_5082_50820601_33_dialog_content = "Eu era jovem e arrogante naquela época. Eu pensava que poderia resolver qualquer problema sozinho.",
  ui_story_5082_50820601_34_dialog_content = "Tem certeza de que não viu aquela garota em nenhuma dessas memórias?",
  ui_story_5082_50820601_35_dialog_content = "Tenho certeza...",
  ui_story_5082_50820601_36_dialog_content = "Por que não tenta perguntar ao seu bom amigo Philyshy sobre isso? Afinal, eu lido com esse tipo de coisa o tempo todo!",
  ui_story_5082_50820601_37_dialog_content = "Passamos por todos os tipos de aventuras juntos, mas as pessoas de alguma forma conseguem esquecer da Yumi.",
  ui_story_5082_50820601_38_dialog_content = "Acho que a situação do Reinhardt é um pouco diferente, Philyshy.",
  ui_story_5082_50820601_39_dialog_content = "Acho que o Comitê pode saber mais sobre essas memórias... Além disso, eles me devem muitos favores.",
  ui_story_5082_50820601_40_dialog_content = "Dê uma olhada nisso, Grande Marechal. Aqueles robôs estranhos que acabaram de nos atacar estão se movendo em formação agora.",
  ui_story_5082_50820601_41_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_5082_50820601_42_dialog_content = "Demos uma olhada naquele que nos atacou anteriormente. Julgando pelo seu design, parece ser um tipo de droide de combate.",
  ui_story_5082_50820601_43_dialog_content = "Mas o que é realmente único em sua estrutura, no entanto, é que parece capaz de se fundir com outras máquinas. Eu me pergunto se eles estavam pesquisando este tipo de tecnologia aqui?",
  ui_story_5082_50820601_44_dialog_content = "O padrão de voo deles é totalmente coordenado. Parece que estão se movendo para mais fundo nas ruínas.",
  ui_story_5082_50820601_45_dialog_content = "Vamos segui-los.",
  ui_story_5082_50820601_46_dialog_content = "Vou explorar à frente.",
  ui_story_5082_50820601_47_option_content = "Varredura Psíquica—",
  ui_story_5082_50820601_48_dialog_content = "%^ buscar poder é $!#￥ buscar destruição... $%^#$#^!$",
  ui_story_5082_50820601_49_dialog_content = "Lança! Você está por perto? Preciso saber mais sobre o que aconteceu aqui—",
  ui_story_5082_50820601_50_dialog_content = "—!",
  ui_story_5082_50820601_51_dialog_content = "É ela...!",
  ui_story_5082_50820601_52_option_content = "Aumento de Força!",
  ui_story_5082_50820601_53_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_54_dialog_content = "Lá está o clarim novamente.",
  ui_story_5082_50820601_55_dialog_content = "Por que eu continuo sendo arrastado para essas memórias sempre que tento fazer contato com aquela garota?",
  ui_story_5082_50820601_56_dialog_content = "Há Reinhardt e Wrath.",
  ui_story_5082_50820601_57_dialog_content = "Esse foi o clarim. Você deve ir se juntar a eles em formação.",
  ui_story_5082_50820601_58_dialog_content = "Enquanto você foge para mais do seu \"treinamento especial\"?",
  ui_story_5082_50820601_59_dialog_content = "Esse programa de treinamento é mesmo oficial? Ou é algo que eles inventaram apenas para você?",
  ui_story_5082_50820601_60_dialog_content = "Você continua voltando com feridas frescas todos os dias. Nem mesmo os soldados que retornam das linhas de frente aparecem com ferimentos como os seus.",
  ui_story_5082_50820601_61_dialog_content = "... E-Eu não estou preocupado com você ou algo assim! Eu só não quero que ninguém interfira nos nossos desafios!",
  ui_story_5082_50820601_62_dialog_content = "Você está pensando demais nas coisas. Acabei de levar meu treinamento para o próximo nível, então ainda estou me adaptando.",
  ui_story_5082_50820601_63_dialog_content = "Não existe treinamento inútil. Qualquer habilidade e experiência que eu adquira aumentará minha própria força.",
  ui_story_5082_50820601_64_dialog_content = "Reinhardt! Você acha que pode ignorar suas tarefas diárias só por causa do seu treinamento especial?!",
  ui_story_5082_50820601_65_dialog_content = "Bem, não no meu turno, agora me dê mais dez voltas!",
  ui_story_5082_50820601_66_dialog_content = "Instrutor, por favor! Reinhardt está exausta demais para continuar! Ela precisa descansar!",
  ui_story_5082_50820601_67_dialog_content = "Vocês dois esqueceram a primeira coisa que eu ensinei? Um soldado sempre segue ordens!",
  ui_story_5082_50820601_68_dialog_content = "São mais cinco voltas para você, Wrath!",
  ui_story_5082_50820601_69_dialog_content = "Faça dez, senhor!",
  ui_story_5082_50820601_70_dialog_content = "Você não precisa continuar me seguindo por aí.",
  ui_story_5082_50820601_71_dialog_content = "\"Não existe tal coisa como treinamento inútil.\" Você mesmo disse isso, não foi?",
  ui_story_5082_50820601_72_dialog_content = "Tudo bem, mas não estou te agradecendo por isso.",
  ui_story_5082_50820601_73_dialog_content = "Ninguém pediu sua desculpa de qualquer maneira.",
  ui_story_5082_50820601_74_dialog_content = "(A partir daí, todos os dias foram iguais para Reinhardt.)",
  ui_story_5082_50820601_75_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_76_dialog_content = "<color=#e8d9bb>O toque de corneta da manhã.</color>",
  ui_story_5082_50820601_77_dialog_content = "Aluno da Academia Reinhardt! Relate-se à instalação de treinamento especial!",
  ui_story_5082_50820601_78_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_79_dialog_content = "<color=#e8d9bb>O toque de recolher da noite.</color>",
  ui_story_5082_50820601_80_dialog_content = "Você finalmente voltou, Reinhardt! Suas mãos...",
  ui_story_5082_50820601_81_dialog_content = "Desculpe, estou um pouco cansado então vou direto para a cama.",
  ui_story_5082_50820601_82_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_83_dialog_content = "Reinhardt, relatando para o dever.",
  ui_story_5082_50820601_84_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_85_dialog_content = "Reinhardt—",
  ui_story_5082_50820601_86_dialog_content = "Nngh... Hã? Precisava de algo...?",
  ui_story_5082_50820601_87_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_88_dialog_content = "(Reinhardt foi direto do quarto dela para a instalação de treinamento especial e voltou, parando apenas tempo suficiente para comer alguns pedaços de suas rações.)",
  ui_story_5082_50820601_89_dialog_content = "(A vida dela era totalmente centrada em treinamento e sono, ambos ditados pelo som de um clarim.)",
  ui_story_5082_50820601_90_dialog_content = "Compilamos dados suficientes desta parte do programa, o que significa que você está pronto para a próxima fase: treinamento de força explosiva.",
  ui_story_5082_50820601_91_dialog_content = "Para esta fase do seu treinamento, você estará lutando contra droides de combate que foram modificados com base em seus atributos específicos.",
  ui_story_5082_50820601_92_dialog_content = "Ao enfrentá-los em batalha, você sentirá como se estivesse lutando contra si mesmo.",
  ui_story_5082_50820601_93_dialog_content = "Use toda a sua força para superar seus limites e destruí-los.",
  ui_story_5082_50820601_94_dialog_content = "Entendi.",
  ui_story_5082_50820602_1_dialog_content = "(Dói tanto... Eles realmente aumentaram a dificuldade para este treinamento chamado \"força explosiva\".)",
  ui_story_5082_50820602_2_dialog_content = "Interessante. Seus sinais vitais haviam desaparecido completamente agora há pouco, e ainda assim ela conseguiu recuperar a consciência e continuar lutando...",
  ui_story_5082_50820602_3_dialog_content = "O que você disse?",
  ui_story_5082_50820602_4_dialog_content = "Uma excelente cobaia, com certeza. Os dados que coletamos superaram completamente nossas expectativas.",
  ui_story_5082_50820602_5_dialog_content = "E enquanto o dano físico ao corpo dela é relativamente alto, ainda está dentro dos parâmetros aceitáveis.",
  ui_story_5082_50820602_6_dialog_content = "Agora então, é hora de passar para a próxima fase...",
  ui_story_5082_50820602_7_dialog_content = "May Posso fazer uma pergunta?",
  ui_story_5082_50820602_8_dialog_content = "Ah, é tudo para o treino de hoje. Você está dispensado.",
  ui_story_5082_50820602_9_dialog_content = "Levando em consideração nossos cálculos iniciais...",
  ui_story_5082_50820602_10_dialog_content = "Esse treinamento especial... Sou o único candidato, ou existem outros como eu?",
  ui_story_5082_50820602_11_dialog_content = "Os parâmetros necessários são...",
  ui_story_5082_50820602_12_dialog_content = "...",
  ui_story_5082_50820602_13_dialog_content = "<color=#e8d9bb>Laboratório Secreto</color>",
  ui_story_5082_50820602_14_dialog_content = "Suas feridas foram tratadas. Tente não molhá-las nos próximos dias.",
  ui_story_5082_50820602_15_dialog_content = "Vou preparar alguns remédios para você antes de ir. Lembre-se de trocar seus curativos todos os dias e comer bastante—",
  ui_story_5082_50820602_16_dialog_content = "Você pode poupar todo o discurso de doutor, Helios. Não fará nenhuma diferença.",
  ui_story_5082_50820602_17_dialog_content = "Sempre que ela acha que algo precisa ser feito, ela vai atrás com toda a força sem ouvir mais ninguém.",
  ui_story_5082_50820602_18_dialog_content = "Negador...",
  ui_story_5082_50820602_19_dialog_content = "Estou apenas dizendo a verdade. É exatamente como concordamos em nos encontrar aqui uma vez por semana.",
  ui_story_5082_50820602_20_dialog_content = "E ainda assim, já se passaram quatro semanas inteiras desde que ela mostrou seu rosto por aqui pela última vez.",
  ui_story_5082_50820602_21_dialog_content = "Ela mal consegue manter sua palavra, e sempre que aparece, está inconsciente e coberta de ferimentos.",
  ui_story_5082_50820602_22_dialog_content = "Um desses dias, você vai me pagar de volta por todo o equipamento que quebrou por desmaiar em todo lugar!",
  ui_story_5082_50820602_23_dialog_content = "Chega, Negador! Tente não ter a ideia errada, Reinhardt. Tenho certeza do que ela quer dizer...",
  ui_story_5082_50820602_24_dialog_content = "É que há muitos materiais inflamáveis e explosivos por aí, e ela não quer que você se machuque.",
  ui_story_5082_50820602_25_dialog_content = "...",
  ui_story_5082_50820602_26_dialog_content = "Desculpe, negador. Eu sei que te fiz preocupar por não aparecer por tanto tempo.",
  ui_story_5082_50820602_27_dialog_content = "Vou garantir que você receba equipamentos de laboratório novinhos mais tarde.",
  ui_story_5082_50820602_28_dialog_content = "...",
  ui_story_5082_50820602_29_dialog_content = "Lá, vê? Resolvido!",
  ui_story_5082_50820602_30_dialog_content = "...",
  ui_story_5082_50820602_31_dialog_content = "Enquanto estamos no assunto, eu sei que construímos este laboratório nós mesmos...",
  ui_story_5082_50820602_32_dialog_content = "Mas está um pouco mal ventilado, não acha? Se a Denier quer continuar com suas experiências...",
  ui_story_5082_50820602_33_dialog_content = "Esse lugar não representa um risco de sufocamento?",
  ui_story_5082_50820602_34_dialog_content = "...",
  ui_story_5082_50820602_35_dialog_content = "Algum problema, Reinhardt?",
  ui_story_5082_50820602_36_dialog_content = "...",
  ui_story_5082_50820602_37_dialog_content = "... Hã? Desculpe, eu estava viajando.",
  ui_story_5082_50820602_38_dialog_content = "Eu estava apenas pensando na minha última sessão de treinamento. Por algum motivo, de repente senti como se estivesse me afogando...",
  ui_story_5082_50820602_39_dialog_content = "Tem certeza que está bem?",
  ui_story_5082_50820602_40_dialog_content = "Claro! Vocês dois sabem o quão rápido eu me recupero; Eu posso estar coberto de feridas agora, mas elas vão cicatrizar em breve.",
  ui_story_5082_50820602_41_dialog_content = "Tenho passado por ainda mais treinamento ultimamente, então tem ficado um pouco mais difícil de comparecer. Vou tentar não me atrasar na próxima vez.",
  ui_story_5082_50820602_42_dialog_content = "Você está evitando o assunto, Reinhardt.",
  ui_story_5082_50820602_43_dialog_content = "Você não se importa consigo mesmo, nem com qualquer outra coisa. Tudo o que você se importa é com seu treinamento estúpido.",
  ui_story_5082_50820602_44_dialog_content = "Você sabe mesmo o que está fazendo? O objetivo principal do treinamento é aumentar o potencial de combate de um soldado dentro de certos limites.",
  ui_story_5082_50820602_45_dialog_content = "Não é para quebrar esses limites à custa do seu próprio corpo.",
  ui_story_5082_50820602_46_dialog_content = "Finalmente você está me dizendo o que realmente pensa, Negador. Estou feliz.",
  ui_story_5082_50820602_47_dialog_content = "Você...",
  ui_story_5082_50820602_48_dialog_content = "Não se preocupe. Eu sei o que estou fazendo.",
  ui_story_5082_50820602_49_dialog_content = "Afinal, vou ser o Grande Marechal algum dia. Como vou liderar toda a Illumina se nem consigo passar pelo meu treinamento na academia?",
  ui_story_5082_50820602_50_dialog_content = "Hmph. Apenas lembre-se de me conseguir um laboratório maior quando finalmente se tornar Grande Marechal.",
  ui_story_5082_50820602_51_dialog_content = "Não suporto ver Eclipsitas em batalha, então prefiro me tornar o maior pesquisador da Illumina e estudá-los da minha mesa de operações.",
  ui_story_5082_50820602_52_dialog_content = "Não tenho grandes aspirações como vocês dois. Contanto que eu possa ser um bom batedor, é tudo que eu preciso.",
  ui_story_5082_50820602_53_dialog_content = "O que não é ótimo nisso?",
  ui_story_5082_50820602_54_dialog_content = "Cada soldado desempenha um papel importante no fortalecimento da Illumina.",
  ui_story_5082_50820602_55_dialog_content = "Sejam nossos batedores, nossos pesquisadores ou até mesmo o Grande Marechal, todos nós constituímos a força vital da Illumina.",
  ui_story_5082_50820602_56_dialog_content = "De qualquer forma, já é difícil o suficiente para nós nos encontrarmos assim, então vamos falar sobre algo agradável para variar.",
  ui_story_5082_50820602_57_dialog_content = "De preferência algo que possamos colocar em nossas memórias para o mundo inteiro ler.",
  ui_story_5082_50820602_58_dialog_content = "Um futuro Grande Marechal, um futuro cientista de ponta e um futuro líder de batedores—",
  ui_story_5082_50820602_59_dialog_content = "Os melhores camaradas que alguém poderia pedir.",
  ui_story_5082_50820700_1_dialog_content = "Esses dróides de combate estão tentando nos levar para lá? Que tática péssima!",
  ui_story_5082_50820700_2_dialog_content = "Julgando pela sua expressão, presumo que você acabou de sentir algo?",
  ui_story_5082_50820700_3_dialog_content = "Eu fiz. Estamos cada vez mais perto daquela garota de vermelho brilhante.",
  ui_story_5082_50820700_4_dialog_content = "Você sentiu a presença dela novamente?",
  ui_story_5082_50820700_5_dialog_content = "Ela sempre aparece seguindo aquele grito, mas sempre que tento fazer contato com ela, vejo cada vez mais e mais de...",
  ui_story_5082_50820700_6_dialog_content = "Meu passado?",
  ui_story_5082_50820700_7_dialog_content = "Sim...",
  ui_story_5082_50820700_8_dialog_content = "Desta vez, eu vi partes do seu treinamento de força explosiva.",
  ui_story_5082_50820700_9_dialog_content = "Isso explica sua expressão.",
  ui_story_5082_50820700_10_dialog_content = "Foi... Bastante brutal de assistir.",
  ui_story_5082_50820700_11_dialog_content = "Como se estivessem tentando fazer você abandonar tudo o que te faz uma pessoa, e transformar você em uma arma viva.",
  ui_story_5082_50820700_12_dialog_content = "Você é uma pessoa gentil, PlayerName.",
  ui_story_5082_50820700_13_dialog_content = "Mas a guerra é apenas brutal porque não existem muitos lugares onde a bondade pode existir no campo de batalha.",
  ui_story_5082_50820700_14_dialog_content = "Quer você concorde ou não, não temos escolha a não ser avançar através dessa brutalidade.",
  ui_story_5082_50820700_15_dialog_content = "Naquela época, eu queria me tornar o soldado mais grande e poderoso da Federação. Naturalmente, para conseguir isso, tive que passar por um inferno vivo.",
  ui_story_5082_50820700_16_dialog_content = "Mas... Você não acha que foi injusto? Você nunca quis desistir, ou até mesmo revidar?",
  ui_story_5082_50820700_17_dialog_content = "Claro que sim. Todos os dias, na verdade.",
  ui_story_5082_50820700_18_dialog_content = "A Illumina atualmente tem alguns dos melhores líderes de sua história, mas não acho que isso aconteceu do nada. Naquela época, nenhum de nós teve facilidades.",
  ui_story_5082_50820700_19_dialog_content = "Grande Marechal, você ainda se lembra do que aconteceu nas Subcidades 13 e 19?",
  ui_story_5082_50820700_20_dialog_content = "...",
  ui_story_5082_50820700_21_dialog_content = "<color=#e8d9bb>Federação Illumina, cidade de Gannon, Ano 1986</color>",
  ui_story_5082_50820700_22_dialog_content = "O comandante ainda não retornou?",
  ui_story_5082_50820700_23_dialog_content = "Ainda não, Tenente Reinhardt! O Grande Marechal solicitou sua presença para uma reunião!",
  ui_story_5082_50820700_24_dialog_content = "O comandante ordenou que fiquemos de prontidão até novo aviso. Sem exceções.",
  ui_story_5082_50820700_25_dialog_content = "Outra ordem de espera? Mas todos os outros foram destacados para defender posições-chave... O que diabos ele está pensando?",
  ui_story_5082_50820700_26_dialog_content = "As Subcidades 13 e 19 foram atacadas pelos Eclipsitas, e todas as comunicações foram cortadas. O único mensageiro que conseguiu escapar está solicitando reforços.",
  ui_story_5082_50820700_27_dialog_content = "... Onde exatamente você aprendeu sobre isso?",
  ui_story_5082_50820700_28_dialog_content = "Isso não é importante. O que é importante é que duas das nossas Cidades Baixas estão à beira da destruição.",
  ui_story_5082_50820700_29_dialog_content = "Enquanto os Eclipsitas estão invadindo nossa casa, o Grande Marechal e o comandante estão ocupados brincando com os polegares em uma reunião!",
  ui_story_5082_50820700_30_dialog_content = "O comandante nos ordenou ficar à espera.",
  ui_story_5082_50820700_31_dialog_content = "Ficar de braços cruzados agora não é diferente de deixá-los morrer. Você, mais do que ninguém, deveria saber disso.",
  ui_story_5082_50820700_32_dialog_content = "...",
  ui_story_5082_50820700_33_dialog_content = "Qual é o problema? Acha que ainda pode enterrar a cabeça na areia e fingir ignorância?",
  ui_story_5082_50820700_34_dialog_content = "Você é igual àqueles comandantes pomposos, sempre dispostos a fingir que está tudo bem, contanto que o sangue não chegue às suas mãos.",
  ui_story_5082_50820700_35_dialog_content = "...",
  ui_story_5082_50820700_36_dialog_content = "Tenente Reinhardt? Para onde você está indo?",
  ui_story_5082_50820700_37_dialog_content = "Apenas dando uma caminhada, só isso.",
  ui_story_5082_50820700_38_dialog_content = "<color=#e8d9bb>As portas do salão central de reuniões se abrem amplamente enquanto o Comandante da 2ª Legião Pango e o Comandante Adjunto do Batalhão Barton saem tempestuosamente.</color>",
  ui_story_5082_50820700_39_dialog_content = "Ei, vocês dois. Acho que as coisas não foram muito bem lá dentro, certo?",
  ui_story_5082_50820700_40_dialog_content = "Com aquele covarde no comando da 1ª Legião? Claro que não!",
  ui_story_5082_50820700_41_dialog_content = "Não saia ainda! Estou aqui para entregar novos pedidos.",
  ui_story_5082_50820700_42_dialog_content = "\"Com efeito imediato, a 2ª Legião deve ser enviada para as Subcidades 13 e 19 para fornecer reforços, com o Tenente Reinhardt e uma parte da 1ª Legião também fornecendo suporte.\"",
  ui_story_5082_50820700_43_dialog_content = "É mais ou menos essa a essência. Como soa?",
  ui_story_5082_50820700_44_dialog_content = "Você está seriamente pensando em falsificar ordens militares?",
  ui_story_5082_50820700_45_dialog_content = "Se você não está disposto a ajudar, então nós vamos lidar com isso por conta própria.",
  ui_story_5082_50820700_46_dialog_content = "Posso despachar alguns esquadrões da 1ª Legião; o resto deles é mais do que capaz de defender Gannon City junto com a 3ª Legião.",
  ui_story_5082_50820700_47_dialog_content = "Podemos não ter muito impacto aqui, mas nossa presença nessas Cidades Baixas pode significar a diferença entre a vida e a morte.",
  ui_story_5082_50820700_48_dialog_content = "Infelizmente, não tenho soldados suficientes para esta missão. É por isso que eu queria pedir ajuda à 2ª Legião.",
  ui_story_5082_50820700_49_dialog_content = "Você sabe o que acontecerá com você se concordarmos com isso, não sabe?",
  ui_story_5082_50820700_50_dialog_content = "Agradeço sua preocupação, comandante... Mas salvar vidas ainda é mais importante para mim.",
  ui_story_5082_50820700_51_dialog_content = "... Você é apenas uma tenente insignificante. O que lhe deu a confiança para nos abordar com uma façanha dessas?",
  ui_story_5082_50820700_52_dialog_content = "Minha crença é que nenhum de vocês jamais abandonaria seus companheiros.",
  ui_story_5082_50820700_53_dialog_content = "Ainda está indeciso, Comandante Pango? Porque de qualquer forma, eu vou com ela.",
  ui_story_5082_50820700_54_dialog_content = "Primeiro você desobedeceu ordens, e agora está falsificando-as? Você tem uma audácia séria, Reinhardt.",
  ui_story_5082_50820700_55_dialog_content = "É só isso que você tem a dizer depois de me seguir todo esse caminho?",
  ui_story_5082_50820700_56_dialog_content = "Ha! Acha que vou ficar parado e deixar você fazer o que quiser?",
  ui_story_5082_50820700_57_dialog_content = "Interessante... Parece que não somos os únicos insatisfeitos com os superiores, certo? Bom! Já era hora de nós darmos as ordens por aqui!",
  ui_story_5082_50820700_58_dialog_content = "Mal posso acreditar que isso realmente aconteceu... Embora isso pareça com você, Reinhardt.",
  ui_story_5082_50820700_59_dialog_content = "Infelizmente, ainda não chegamos a tempo.",
  ui_story_5082_50820700_60_dialog_content = "A Subcidade 13 foi praticamente aniquilada, e a Subcidade 19 não estava em muito melhor estado.",
  ui_story_5082_50820700_61_dialog_content = "Pelo menos, conseguimos resgatar algumas pessoas... E enquanto muitas pessoas elogiaram nossas ações, também chamamos a atenção do Comitê.",
  ui_story_5082_50820700_62_dialog_content = "Ironicamente, os resultados de nossas ações nos impediram de sermos acusados de insubordinação. Na verdade, Wrath e eu tivemos a sorte de sermos promovidos a Comandantes de Batalhão!",
  ui_story_5082_50820700_63_dialog_content = "A sorte não tem nada a ver com esse tipo de coisa. Não em Illumina.",
  ui_story_5082_50820700_64_dialog_content = "O Comandante Pango vinha treinando você para ocupar o lugar dele por um longo tempo. O incidente apenas o forçou a antecipar seus planos para você.",
  ui_story_5082_50820700_65_dialog_content = "Você ainda era tão jovem naquela época, e ainda não tinha muitas realizações. Tenho certeza de que você também teve sua cota de dificuldades naquela época, não teve??",
  ui_story_5082_50820700_66_dialog_content = "Você é o que teve mais dificuldades do que qualquer outro, Reinhardt. Suas ações não autorizadas e ordens falsificadas realmente irritaram o comandante da 1ª Legião na época.",
  ui_story_5082_50820700_67_dialog_content = "Eles te rebaixaram para a patente mais baixa possível, tirando toda a sua autoridade e te enviando para o treinamento básico novamente.",
  ui_story_5082_50820700_68_dialog_content = "Hahaha! Mas mesmo agora, sempre que penso em você confrontando nossos superiores por minha causa—",
  ui_story_5082_50820700_69_dialog_content = "Sempre faz meu sangue pulsar, assim como antes! Você até apareceu com um público inteiro cantando, \"Splendor Illumina\"!",
  ui_story_5082_50820700_70_dialog_content = "...?",
  ui_story_5082_50820700_71_dialog_content = "Espere... Aquele que se chocou com seus superiores...",
  ui_story_5082_50820700_72_dialog_content = "<color=#e8d9bb>Federação Illumina, cidade de Gannon, Ano 1986</color>",
  ui_story_5082_50820700_73_dialog_content = "Ei, Reinhardt! Este equipamento de treinamento ainda está coberto de poeira! Você não tem estado preguiçoso, tem?!",
  ui_story_5082_50820700_74_dialog_content = "Vou limpar novamente.",
  ui_story_5082_50820700_75_dialog_content = "Minha cantina também está vazia. Vá enchê-la enquanto está nisso.",
  ui_story_5082_50820700_76_dialog_content = "Agora mesmo.",
  ui_story_5082_50820700_77_dialog_content = "Ei... Você não acha que estamos indo um pouco longe demais com isso?",
  ui_story_5082_50820700_78_dialog_content = "Do que você está falando? Ela falsificou ordens apenas para fazer um nome para si mesma, e você ainda acha que ela merece algo melhor?",
  ui_story_5082_50820700_79_dialog_content = "O comandante também concorda...",
  ui_story_5082_50820700_80_dialog_content = "Esses caras estão indo muito além do limite!",
  ui_story_5082_50820700_81_dialog_content = "Não se exalte tanto por isso, Cologne. Eu quebrei as regras e agora estou pagando por isso.",
  ui_story_5082_50820700_82_dialog_content = "Ser arrastado para baixo por minha causa não vale a pena, então apenas deixe pra lá.",
  ui_story_5082_50820700_83_dialog_content = "Como você pode dizer isso, Reinhardt?! Todos nós sabíamos a verdade quando concordamos em ir com você!",
  ui_story_5082_50820700_84_dialog_content = "Você não deveria ser o único a ser punido, e é exatamente isso que vou dizer ao comandante!",
  ui_story_5082_50820700_85_dialog_content = "Ei, não são aqueles caras da 2ª Legião? Eu não me lembro de ter que compartilhar o campo de treinamento com esses perdedores hoje?",
  ui_story_5082_50820700_86_dialog_content = "Sério? Que chatice.",
  ui_story_5082_50820700_87_dialog_content = "E aquele novo cara ainda é o Comandante do Batalhão. Ouvi dizer que ele estava em liga com Reinhardt quando tudo aconteceu.",
  ui_story_5082_50820700_88_dialog_content = "Eles são os que invadiram o depósito de equipamentos! Muitas pessoas se machucaram porque eles queriam monopolizar toda a glória!",
  ui_story_5082_50820700_89_dialog_content = "Sim, mas eles também salvaram a Subcidade 19... Você acha que os outros rumores sobre eles são verdadeiros?",
  ui_story_5082_50820700_90_dialog_content = "Se não fossem, o Grande Marechal já teria esclarecido as coisas até agora. Isso significa que o que ouvimos sobre eles agora provavelmente é verdade.",
  ui_story_5082_50820700_91_dialog_content = "Os rumores estão começando a sair do controle, comandante. Não deveríamos fazer algo a respeito?",
  ui_story_5082_50820700_92_dialog_content = "De modo algum. Afinal, eles mesmos causaram isso.",
  ui_story_5082_50820700_93_dialog_content = "Nunca pensei que o soldado mais promissor da 2ª Legião seria assim...",
  ui_story_5082_50820700_94_dialog_content = "Dizem que o Comandante Pango o promoveu pessoalmente, mas no final...",
  ui_story_5082_50820700_95_dialog_content = "...",
  ui_story_5082_50820700_96_dialog_content = "Eu sei que você pode ouvi-los, Comandante Barton! A 1ª Legião está completamente fora de linha!",
  ui_story_5082_50820700_97_dialog_content = "Apenas continue se movendo.",
  ui_story_5082_50820700_98_dialog_content = "...",
  ui_story_5082_50820700_99_dialog_content = "O que pensa que está fazendo?",
  ui_story_5082_50820700_100_dialog_content = "Você vai apenas ficar parado e assistir?",
  ui_story_5082_50820700_101_dialog_content = "Tudo isso é totalmente justo e aceitável?",
  ui_story_5082_50820700_102_dialog_content = "...",
  ui_story_5082_50820700_103_dialog_content = "... Hunf!",
  ui_story_5082_50820700_104_dialog_content = "Barton!",
  ui_story_5082_50820700_105_dialog_content = "Não fizemos nada de errado!",
  ui_story_5082_50820700_106_dialog_content = "?",
  ui_story_5082_50820700_107_dialog_content = "<color=#e8d9bb>No repentino silêncio, ela marcha através da multidão com a cabeça erguida e se posiciona no centro do alvoroço.</color>",
  ui_story_5082_50820700_108_dialog_content = "Vocês são todos um bando de fantoches inúteis.",
  ui_story_5082_50820700_109_dialog_content = "Se alguém é culpado de fazer algo errado, são vocês!",
  ui_story_5082_50820700_110_dialog_content = "Estava errado por não querer deixar meus camaradas para trás?",
  ui_story_5082_50820700_111_dialog_content = "Estava errado por querer salvar as pessoas que foram deixadas para morrer?!",
  ui_story_5082_50820700_112_dialog_content = "Ei, você—",
  ui_story_5082_50820700_113_dialog_content = "Usem suas cabeças e pensem no que teriam feito! Ou vocês perderam a capacidade de fazer isso?",
  ui_story_5082_50820700_114_dialog_content = "Lutamos para derrotar os Eclipsitas e proteger nossos aliados.",
  ui_story_5082_50820700_115_dialog_content = "E ainda assim, algumas pessoas pensam que devemos ser punidos por fazer o que elas sempre têm muito medo de fazer.",
  ui_story_5082_50820700_116_dialog_content = "A única coisa para a qual vocês servem agora é para obedecer.",
  ui_story_5082_50820700_117_dialog_content = "É por isso que tudo o que é preciso é um único comando para fazer você se voltar contra seus camaradas de armas e enviá-los para a morte.",
  ui_story_5082_50820700_118_dialog_content = "...",
  ui_story_5082_50820700_119_dialog_content = "Vou dizer de novo.",
  ui_story_5082_50820700_120_dialog_content = "Não fizemos nada de errado.",
  ui_story_5082_50820700_121_dialog_content = "E se tivéssemos que fazer tudo de novo, faríamos exatamente a mesma escolha.",
  ui_story_5082_50820700_122_dialog_content = "Isso porque você ou eu podemos ser os próximos presos em uma situação sem esperança.",
  ui_story_5082_50820700_123_dialog_content = "Mas enquanto formos aliados, nenhum de nós tem o direito ou motivo para virar as costas um para o outro sem nem mesmo tentar!",
  ui_story_5082_50820700_124_dialog_content = "Vou dizer isso uma última vez!",
  ui_story_5082_50820700_125_dialog_content = "Sim, violamos nossas ordens, mas nós—",
  ui_story_5082_50820700_126_dialog_content = "Não fez nada de errado!",
  ui_story_5082_50820700_127_dialog_content = "...",
  ui_story_5082_50820700_128_dialog_content = "Tem mais alguma coisa para dizer, Barton?",
  ui_story_5082_50820700_129_dialog_content = "Hunf.",
  ui_story_5082_50820700_130_dialog_content = "<color=#e8d9bb>Sem dizer uma palavra, Barton marcha através da multidão que se abre à sua frente, e fica de frente para ela.</color>",
  ui_story_5082_50820700_131_dialog_content = "Eu não sou tão bom em falar quanto você, mas agora, não há necessidade de mais palavras.",
  ui_story_5082_50820700_132_dialog_content = "<color=#e8d9bb>Barton estufa o peito.</color>",
  ui_story_5082_50820700_133_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_134_dialog_content = "Heh, não há necessidade de mais palavras, huh?",
  ui_story_5082_50820700_135_dialog_content = "<color=#e8d9bb>Ela respira fundo e combina a intensidade dele com o próprio chamado.</color>",
  ui_story_5082_50820700_136_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_137_dialog_content = "<color=#e8d9bb>Os soldados ao redor deles se olham, incertos do que deveriam fazer. Os dois continuam a manter sua posição, como se nem mesmo os céus pudessem fazê-los se mover.</color>",
  ui_story_5082_50820700_138_dialog_content = "<color=#e8d9bb>Antes que alguém recobre os sentidos, duas figuras a mais emergem do público.</color>",
  ui_story_5082_50820700_139_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_140_dialog_content = "<color=#e8d9bb>Depois deles, os que lutaram naquela batalha avançam.</color>",
  ui_story_5082_50820700_141_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_142_dialog_content = "<color=#e8d9bb>Em pouco tempo, cada vez mais pessoas se juntam ao canto.",
  ui_story_5082_50820700_143_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_144_dialog_content = "<color=#e8d9bb>O espaço que uma vez dividiu o público agora está preenchido com soldados unidos por uma única causa.</color>",
  ui_story_5082_50820700_145_dialog_content = "<color=#e8d9bb>Aqueles que lutaram juntos, e aqueles que não lutaram.</color>",
  ui_story_5082_50820700_146_dialog_content = "<color=#e8d9bb>Aqueles que se conheciam pelo nome e aqueles que eram completos estranhos.</color>",
  ui_story_5082_50820700_147_dialog_content = "<color=#e8d9bb>Cada soldado se posicionou orgulhosamente entre seus pares.</color>",
  ui_story_5082_50820700_148_dialog_content = "Splendor Illumina!",
  ui_story_5082_50820700_149_dialog_content = "Esplendor Illumina!!!",
  ui_story_5082_50820700_150_dialog_content = "O que devemos fazer, comandante? O público vai perder o controle neste ritmo.",
  ui_story_5082_50820700_151_dialog_content = "... Então agora ela está interpretando a heroína, hein?",
  ui_story_5082_50820700_152_dialog_content = "Acalmem-se, todos vocês!!!",
  ui_story_5082_50820700_153_dialog_content = "...",
  ui_story_5082_50820700_154_dialog_content = "Comandante do Batalhão Barton! O tratamento preferencial de Pango para você não se aplica fora da 2ª Legião, então, por favor, evite interromper o treinamento da 1ª Legião ainda mais.",
  ui_story_5082_50820700_155_dialog_content = "Atenção, todos os membros da 1ª Legião! Como punição por suas ações hoje, vocês estão designados a limpar todos os campos de treinamento em Gannon City, com efeito imediato!",
  ui_story_5082_50820700_156_dialog_content = "Esse castigo é completamente irracional!",
  ui_story_5082_50820700_157_dialog_content = "Você seguirá suas ordens, soldado!!!",
  ui_story_5082_50820700_158_dialog_content = "Uma vez concluída a limpeza, toda a 1ª Legião será reorganizada e proibida de participar de quaisquer eventos militares futuros.",
  ui_story_5082_50820801_1_dialog_content = "Quando eu penso nisso... Todos estavam apenas seguindo o fluxo, mas ela foi a única que expressou as palavras que estavam em seus corações.",
  ui_story_5082_50820801_2_dialog_content = "Espere aí, o que você quer dizer com isso?",
  ui_story_5082_50820801_3_dialog_content = "Eu não me lembro de nenhuma garota de vermelho naquela época!",
  ui_story_5082_50820801_4_dialog_content = "Nunca esquecerei um momento do que aconteceu naquele dia. Quem disse todas aquelas palavras foi você, Reinhardt!",
  ui_story_5082_50820801_5_dialog_content = "... Eu?",
  ui_story_5082_50820801_6_dialog_content = "Você não perdeu suas memórias naquela explosão do laboratório, perdeu? Em todos os meus anos de conhecendo você, nunca vi ninguém como a pessoa que você está descrevendo.",
  ui_story_5082_50820801_7_dialog_content = "Mas essas memórias... Quanto mais avançamos nesta base, mais elas continuam ressurgindo... E elas não parecem falsas de todo.",
  ui_story_5082_50820801_8_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5082_50820801_9_dialog_content = "Argh, droga...",
  ui_story_5082_50820801_10_dialog_content = "Cuidado por onde anda! Este lugar está coberto de eletrônicos velhos e quebrados, então tente não tropeçar neles.",
  ui_story_5082_50820801_11_dialog_content = "Aqui, observe atentamente! Da próxima vez que estiver prestes a cair, apenas impulsione-se para frente assim, e...",
  ui_story_5082_50820801_12_dialog_content = "Obrigado Philyshy, mas tenho quase certeza que só um gato conseguiria fazer isso...",
  ui_story_5082_50820801_13_dialog_content = "Ei, essa coisa em que tropecei... Por que parece que é para ser usada na sua cabeça?",
  ui_story_5082_50820801_14_dialog_content = "Miau! Eu já vi isso antes!",
  ui_story_5082_50820801_15_dialog_content = "A Doutora Chandra usou essa coisa para nos tratar, eu e Yumi, desde o início. Ela disse que também era bastante valioso.",
  ui_story_5082_50820801_16_dialog_content = "Aparentemente, não existem muitos como ele, e eles foram usados para treinar os soldados de elite de Illumina.",
  ui_story_5082_50820801_17_dialog_content = "Tem um aqui também. Eles estão danificados além do reparo, mas o design original ainda pode ser visto nas partes restantes.",
  ui_story_5082_50820801_18_dialog_content = "Deixe-me dar uma olhada...",
  ui_story_5082_50820801_19_dialog_content = "Espere...",
  ui_story_5082_50820801_20_dialog_content = "<color=#e8d9bb>O grupo só consegue ver o dispositivo brevemente antes de Barton pisoteá-lo em pedaços.</color>",
  ui_story_5082_50820801_21_dialog_content = "... Não há como algo assim ser usado para treinar soldados de elite, certo?",
  ui_story_5082_50820801_22_dialog_content = "Essas coisas são realmente tão raras e valiosas? Porque já conseguimos encontrar três delas aqui.",
  ui_story_5082_50820801_23_dialog_content = "Este ainda está principalmente intacto, mas está coberto de ferrugem... Hã?",
  ui_story_5082_50820801_24_dialog_content = "Esta máquina...",
  ui_story_5082_50820801_25_dialog_content = "... Eu posso sentir a vida fluindo através dele.",
  ui_story_5082_50820801_26_dialog_content = "!",
  ui_story_5082_50820801_27_dialog_content = "Hum...",
  ui_story_5082_50820801_28_dialog_content = "Reinhardt?!",
  ui_story_5082_50820801_29_option_content = "Aumento de Força!",
  ui_story_5082_50820801_30_dialog_content = "...",
  ui_story_5082_50820801_31_dialog_content = "Os sinais vitais não são mais detectados...",
  ui_story_5082_50820801_32_dialog_content = "<color=#e8d9bb>Glub, glub, glub...</color>",
  ui_story_5082_50820801_33_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820801_34_dialog_content = "O clarim... É hora do treinamento.",
  ui_story_5082_50820801_35_dialog_content = "*Rugido*",
  ui_story_5082_50820801_36_dialog_content = "Grande marechal!",
  ui_story_5082_50820801_37_dialog_content = "Esta máquina... Eu já a vi antes... Eu a usei...",
  ui_story_5082_50820801_38_dialog_content = "Mas... Por que...",
  ui_story_5082_50820801_39_dialog_content = "Aguente firme, Grande Marechal!",
  ui_story_5082_50820801_40_dialog_content = "PlayerName! Livre-se dessa coisa!",
  ui_story_5082_50820801_41_dialog_content = "Espere, aquela presença agora... Você se lembrou de algo, Reinhardt?",
  ui_story_5082_50820801_42_dialog_content = "É vago, mas definitivamente tem algo a ver com aquela coisa... Agora depende de você, PlayerName...",
  ui_story_5082_50820801_43_dialog_content = "Grande marechal...!",
  ui_story_5082_50820801_44_dialog_content = "Isso é muito importante para mim, Vivian.",
  ui_story_5082_50820801_45_dialog_content = "Fiquem atentos, todos. Eu preciso que vocês mantenham esses monstros longe de nós.",
  ui_story_5082_50820801_46_dialog_content = "Estou prestes a entrar na consciência de Reinhardt para descobrir o que está por trás deste dispositivo estranho.",
  ui_story_5082_50820901_1_dialog_content = "(Parece que estou em um laboratório Illumina, mas aqui parece tão opressivo.)",
  ui_story_5082_50820901_2_dialog_content = "Assunto #1, por favor, entre nas salas um a três e use seus Luminatics de acordo com as instruções.",
  ui_story_5082_50820901_3_dialog_content = "Entendi.",
  ui_story_5082_50820901_4_dialog_content = "Assunto #2, por favor, entre nas salas um a três e use seus Luminatics de acordo com as instruções.",
  ui_story_5082_50820901_5_dialog_content = "...",
  ui_story_5082_50820901_6_dialog_content = "(O que eles estão fazendo?)",
  ui_story_5082_50820901_7_dialog_content = "Assunto #2, por favor, cumpra suas ordens.",
  ui_story_5082_50820901_8_dialog_content = "Gostaria de saber o verdadeiro propósito deste experimento.",
  ui_story_5082_50820901_9_dialog_content = "Se minha maestria em Luminatics é o assunto do teste, eu deveria ser informado sobre o ambiente de teste para fazer os ajustes necessários.",
  ui_story_5082_50820901_10_dialog_content = "Seria preferível para mim simplesmente liberar meu Lumina em um quarto escuro sem um objetivo claro em mente.",
  ui_story_5082_50820901_11_dialog_content = "Saiba apenas que este experimento irá ajudá-lo em seu caminho para se tornar um Pesquisador, negador.",
  ui_story_5082_50820901_12_dialog_content = "...",
  ui_story_5082_50820901_13_dialog_content = "Assunto #3, por favor, entre nas salas um a três e use seus Luminatics de acordo com as instruções.",
  ui_story_5082_50820901_14_dialog_content = "Não fui informado sobre nenhuma alteração no meu treinamento hoje.",
  ui_story_5082_50820901_15_dialog_content = "Não temos nenhuma obrigação de divulgar qualquer informação para você. Não é nada mais do que uma pequena série de testes, agora por favor, cumpra.",
  ui_story_5082_50820901_16_dialog_content = "Acho que tenho o direito de saber sobre qualquer coisa que me diz respeito.",
  ui_story_5082_50820901_17_dialog_content = "PlayerName?",
  ui_story_5082_50820901_18_dialog_content = "Você está se sentindo melhor? Você realmente me deu um susto agora...",
  ui_story_5082_50820901_19_dialog_content = "Que tipo de experimento foi esse? E por que todos vocês três estavam lá?",
  ui_story_5082_50820901_20_dialog_content = "\"Todos nós três\"? O que você quer dizer?",
  ui_story_5082_50820901_21_dialog_content = "Você não se viu agora há pouco? Você estava bem aqui...",
  ui_story_5082_50820901_22_dialog_content = "Eu não...",
  ui_story_5082_50820901_23_dialog_content = "<color=#e8d9bb>Reinhardt faz uma pausa por um momento, sua testa franzida em pensamento. Ela dá dois passos à frente e fica onde estava em sua memória.</color>",
  ui_story_5082_50820901_24_dialog_content = "O que está vendo, PlayerName?",
  ui_story_5082_50820901_25_dialog_content = "Eu vi você e também o seu eu passado no uniforme dela da academia.",
  ui_story_5082_50820901_26_dialog_content = "Mas eu vi mais alguém.",
  ui_story_5082_50820901_27_dialog_content = "Uma garota com cabelo preto curto e bagunçado, cujos olhos afiados pareciam prontos para desafiar qualquer um.",
  ui_story_5082_50820901_28_dialog_content = "Ela tinha cicatrizes por toda as mãos e braços, mas ela não se incomodava em cobri-las de forma alguma. Ela usava uma camisa vermelha e um casaco drapeado sobre os ombros como uma capa.",
  ui_story_5082_50820901_29_dialog_content = "Ela parecia tão sem lei e desenfreada, como um fogo furioso que ameaçava queimar tudo em seu caminho. Uma visão aterrorizante—",
  ui_story_5082_50820901_30_dialog_content = "E ainda assim, de alguma forma, foi tão libertador.",
  ui_story_5082_50820901_31_dialog_content = "Então, aquela garota de vermelho brilhante que você mencionou antes...",
  ui_story_5082_50820901_32_dialog_content = "Isso mesmo.",
  ui_story_5082_50820901_33_dialog_content = "Para ser honesto, também estou tendo dificuldade em acreditar. Mas depois de ver essa memória, não há como negar mais.",
  ui_story_5082_50820901_34_dialog_content = "Aquela garota—",
  ui_story_5082_50820901_35_dialog_content = "Sou eu.",
  ui_story_5082_50820901_36_dialog_content = "(A cena está mudando de novo.)",
  ui_story_5082_50820901_37_dialog_content = "Todos os sujeitos de teste, por favor, façam os ajustes necessários em seu equipamento e se concentrem.",
  ui_story_5082_50820901_38_dialog_content = "Essas três máquinas... Elas parecem com as que acabamos de encontrar.",
  ui_story_5082_50820901_39_dialog_content = "Então vocês usaram eles no passado. Não é de se admirar que Philyshy disse que eles eram usados para treinar soldados de elite.",
  ui_story_5082_50820901_40_dialog_content = "Mas por que eu não tenho nenhuma lembrança dessas coisas...?",
  ui_story_5082_50820901_41_dialog_content = "Urgh... Por que minha cabeça dói tanto? Será que tem algo a ver com essas máquinas?",
  ui_story_5082_50820901_42_dialog_content = "Um dispositivo que estimula o cérebro para acionar o potencial oculto...",
  ui_story_5082_50820901_43_dialog_content = "Se mexerem com o meu cérebro, é melhor estarem prontos para pagar por isso—!",
  ui_story_5082_50820901_44_dialog_content = "Espere um minuto, esse não é o meu batimento cardíaco! Essas emoções complicadas também não são minhas... Estou ouvindo algo? Não... Eu sinto isso...",
  ui_story_5082_50820901_45_dialog_content = "Sinto a presença de outra pessoa.",
  ui_story_5082_50820901_46_dialog_content = "... Irmã?",
  ui_story_5082_50820901_47_dialog_content = "... Negador.",
  ui_story_5082_50820901_48_dialog_content = "Eu nunca esperava ter uma conversa com você assim.",
  ui_story_5082_50820901_49_dialog_content = "Ou tê-lo aqui, de todos os lugares... O que você está fazendo aqui?",
  ui_story_5082_50820901_50_dialog_content = "A capacidade de sentir os pensamentos e emoções de outras pessoas... Eles estão tentando replicar o poder dos Celestitas?",
  ui_story_5082_50820901_51_dialog_content = "Mas se você está aqui, isso significa que outra pessoa também deve estar aqui.",
  ui_story_5082_50820901_52_dialog_content = "O que é isto?!",
  ui_story_5082_50820901_53_dialog_content = "Parece que eu estava certo.",
  ui_story_5082_50820901_54_dialog_content = "... Eles disseram que queriam testar nosso controle de Luminatics, mas isso não tem nada a ver com isso.",
  ui_story_5082_50820901_55_dialog_content = "Talvez eles estejam tentando melhorar nossa eficiência de combate como uma unidade coesa?",
  ui_story_5082_50820901_56_dialog_content = "Se ao menos fosse tão simples. Vocês não estão curiosos sobre por que eles escolheram nós três?",
  ui_story_5082_50820901_57_dialog_content = "...",
  ui_story_5082_50820901_58_dialog_content = "Além disso, os pesquisadores provavelmente mencionaram que haveria mais testes como este, certo?",
  ui_story_5082_50820901_59_dialog_content = "Eu não esqueci como Reinhardt parecia depois que ela voltou daqueles chamados \"testes\".",
  ui_story_5082_50820901_60_dialog_content = "Não somos nem de longe tão poderosos quanto Reinhardt, então talvez nossos testes não sejam tão... Urgh!",
  ui_story_5082_50820901_61_dialog_content = "Helios?!",
  ui_story_5082_50820901_62_dialog_content = "Não sinto mais a consciência dele. Talvez ele—Ack!",
  ui_story_5082_50820901_63_dialog_content = "Negador! O que está acontecendo?!",
  ui_story_5082_50820901_64_dialog_content = "*Rugido*",
  ui_story_5082_50820901_65_dialog_content = "... Vocês são a próxima parte da \"pequena série de testes\" deles, não são?",
  ui_story_5082_50820902_1_dialog_content = "(Depois daquele dia, notei que estava sendo constantemente seguido, não importa para onde eu fosse.)",
  ui_story_5082_50820902_2_dialog_content = "...",
  ui_story_5082_50820902_3_dialog_content = "Ufa, os competidores de hoje foram bastante difíceis.",
  ui_story_5082_50820902_4_dialog_content = "Viu? Eu te disse que ela ficaria bem. Ela disse que não nos deixaria esperando novamente, lembra?",
  ui_story_5082_50820902_5_dialog_content = "Então, você encontrou algum problema, Reinhardt?",
  ui_story_5082_50820902_6_dialog_content = "Nah, apenas sendo constantemente observado como de costume. E vocês dois? Desde que o experimento terminou, não vi vocês se falarem.",
  ui_story_5082_50820902_7_dialog_content = "...",
  ui_story_5082_50820902_8_dialog_content = "Se há algo em sua mente, você deve falar sobre isso. Conhecer a verdade é a única maneira de tomarmos as decisões corretas.",
  ui_story_5082_50820902_9_dialog_content = "... Você está certo. Nós crescemos juntos, e não deveríamos manter segredos sobre isso um do outro.",
  ui_story_5082_50820902_10_dialog_content = "A verdade é, minha cabeça tem doído desde o experimento naquele dia.",
  ui_story_5082_50820902_11_dialog_content = "Por algum motivo, nunca mais fui incluído nas atividades em grupo para o meu treinamento de batedor. Até o meu comandante não me dá uma resposta direta quando pergunto sobre isso.",
  ui_story_5082_50820902_12_dialog_content = "Você já se consultou?",
  ui_story_5082_50820902_13_dialog_content = "Eles disseram que não há nada de errado comigo e que eu não deveria me preocupar tanto, já que isso não afeta seriamente minha vida ou habilidades de combate.",
  ui_story_5082_50820902_14_dialog_content = "E você, Negador?",
  ui_story_5082_50820902_15_dialog_content = "... Este lugar foi descoberto.",
  ui_story_5082_50820902_16_dialog_content = "!",
  ui_story_5082_50820902_17_dialog_content = "É minha culpa.",
  ui_story_5082_50820902_18_dialog_content = "Eu estava precisando de alguns materiais, então entrei em contato com meus superiores com uma proposta para um projeto em que estava trabalhando, mas eles me ignoraram.",
  ui_story_5082_50820902_19_dialog_content = "E então, apenas alguns dias atrás, meu projeto foi completamente rejeitado de repente. Eles me rastrearam até aqui sob suspeita de realizar experimentos perigosos.",
  ui_story_5082_50820902_20_dialog_content = "Fui ordenado a fechar o laboratório e entregar todos os meus equipamentos e pesquisas.",
  ui_story_5082_50820902_21_dialog_content = "Isso não é um problema. Nós construímos este lugar antes, e podemos construí-lo novamente.",
  ui_story_5082_50820902_22_dialog_content = "Perder sua pesquisa é a verdadeira perda aqui... O que me lembra, em que você estava trabalhando aqui?",
  ui_story_5082_50820902_23_dialog_content = "... Temos algo mais importante para falar agora.",
  ui_story_5082_50820902_24_dialog_content = "\"Nenhum sujeito de teste completou com sucesso este programa, mas seus dados podem ser a chave para uma descoberta científica para a Illumina.\"",
  ui_story_5082_50820902_25_dialog_content = "\"Anote tudo o que você experimenta durante este experimento... O que você ouve... O que você sente...\"",
  ui_story_5082_50820902_26_dialog_content = "\"Seja você em busca de promoção ou acesso à tecnologia mais avançada disponível, tudo estará ao seu alcance.\"",
  ui_story_5082_50820902_27_dialog_content = "Vocês dois também foram informados de algo nesse sentido após aquele experimento, certo?",
  ui_story_5082_50820902_28_dialog_content = "...",
  ui_story_5082_50820902_29_dialog_content = "Então agora é hora de decidir. Todos a favor de rejeitar suas promessas de grandeza e falhar propositalmente em seu experimento, levantem a mão.",
  ui_story_5082_50820902_30_dialog_content = "O que o Negador disse naquele dia me fez perceber que nós três estamos conectados por este experimento.",
  ui_story_5082_50820902_31_dialog_content = "Não sei qual é o objetivo deles, mas estou preocupado que meus resultados possam representar um risco para vocês dois.",
  ui_story_5082_50820902_32_dialog_content = "É por isso que eu não posso e não vou tomar nenhuma decisão sobre isso por conta própria.",
  ui_story_5082_50820902_33_dialog_content = "<color=#e8d9bb>Helios levanta a mão.</color>",
  ui_story_5082_50820902_34_dialog_content = "Ainda tenho mais para dizer também.",
  ui_story_5082_50820902_35_dialog_content = "Espere, é a minha vez de falar. Sou especialista quando se trata de ser \"testado\", então muitas dessas coisas já são naturais para mim agora.",
  ui_story_5082_50820902_36_dialog_content = "Enquanto você continuar mostrando a eles seus limites, eles continuarão te empurrando para superá-los.",
  ui_story_5082_50820902_37_dialog_content = "Eles até envolverão seus amigos nisso. Nenhum preço é alto demais aos olhos deles, nem mesmo nossas próprias vidas.",
  ui_story_5082_50820902_38_dialog_content = "<color=#e8d9bb>Reinhardt levanta a mão.</color>",
  ui_story_5082_50820902_39_dialog_content = "Eu estive fazendo uma pequena investigação por conta própria nos últimos dias.",
  ui_story_5082_50820902_40_dialog_content = "Para aumentar a força militar da Illumina, eles vão começar experimentos para ativar um Colosso conhecido como \"Spearhead\".",
  ui_story_5082_50820902_41_dialog_content = "Uma Colossus...",
  ui_story_5082_50820902_42_dialog_content = "Você já ouviu falar disso, certo? Eles o escavaram de uma das Subcidades próximas. Aparentemente, ele até antecede os Colossus de Eraveil.",
  ui_story_5082_50820902_43_dialog_content = "É possível que o objetivo do experimento fosse encontrar um piloto adequado para o Colossus.",
  ui_story_5082_50820902_44_dialog_content = "Mas eu não estou com vontade de perder tempo com experimentos sem sentido, e definitivamente não quero que eles atrapalhem nossas reuniões diárias.",
  ui_story_5082_50820902_45_dialog_content = "Então-",
  ui_story_5082_50820902_46_dialog_content = "<color=#e8d9bb>Negador levanta a mão dela.</color>",
  ui_story_5082_50820902_47_dialog_content = "Estamos todos de acordo.",
  ui_story_5082_50820902_48_dialog_content = "Parabéns a todos. O experimento de seleção do Navegador já é um completo e absoluto fracasso.",
  ui_story_5082_50820902_49_dialog_content = "O que significa que estamos livres para fazer o que temos que fazer agora. Vamos chamá-lo por hoje.",
  ui_story_5082_50820902_50_dialog_content = "Posso ter mais um segundo, por favor? Ainda tenho mais a dizer, e acho que pode estar relacionado à nossa situação.",
  ui_story_5082_50820902_51_dialog_content = "Não tive muito o que fazer ultimamente, e estive pensando naquele experimento, então decidi investigar aquele laboratório.",
  ui_story_5082_50820902_52_dialog_content = "Os testes que eles fizeram em nós foram apenas em uma pequena seção do laboratório. A instalação inteira é muito maior do que imaginávamos.",
  ui_story_5082_50820902_53_dialog_content = "Isso explica por que eles tiveram que construí-la em uma das Cidades Baixas vizinhas. Além do setor de pesquisa, o laboratório possui um centro médico surpreendentemente bem abastecido e equipamentos totalmente funcionais.",
  ui_story_5082_50820902_54_dialog_content = "A segurança estava apertada, então não consegui dar uma olhada melhor lá dentro.",
  ui_story_5082_50820902_55_dialog_content = "Mas, julgando pela quantidade de comida sendo alocada para a instalação, meu palpite é que eles estão mantendo muitos pacientes lá dentro.",
  ui_story_5082_50820902_56_dialog_content = "Então você está dizendo que suas dores de cabeça não são únicas para você, e que outras pessoas podem ter precisado de hospitalização por seus próprios sintomas?",
  ui_story_5082_50820902_57_dialog_content = "Talvez, mas a coisa que eu mais quero mencionar...",
  ui_story_5082_50820902_58_dialog_content = "Eu vi pessoas levando crianças para dentro e para fora da creche lá.",
  ui_story_5082_50820902_59_dialog_content = "É assustador pensar nisso, mas devido às repetidas falhas dos cobaias adultas, é possível que eles tenham começado a direcionar suas pesquisas para uma direção diferente...",
  ui_story_5082_50820902_60_dialog_content = "Você quer dizer que eles estão experimentando com órfãos agora?!",
  ui_story_5082_50820902_61_dialog_content = "Sente-se, Reinhardt.",
  ui_story_5082_50820902_62_dialog_content = "Tudo o que falamos hoje deveria permanecer classificado.",
  ui_story_5082_50820902_63_dialog_content = "Você sabe como as coisas estão agora; não há espaço para nós brincarmos de heróis quando nem podemos garantir nossa própria segurança.",
  ui_story_5082_50820902_64_dialog_content = "Então apenas se acalme. O experimento daquele dia me deu algumas ideias de como avançar minha pesquisa e resolver nosso problema.",
  ui_story_5082_50820902_65_dialog_content = "Com sorte, poderá nos proteger e até nos tirar deste lugar de vez. Mas agora...",
  ui_story_5082_50820902_66_dialog_content = "Como alguém que passou por inúmeras sessões de \"treinamento especial\", sei por experiência própria que nenhuma pessoa comum pode sobreviver a esse tipo de inferno!",
  ui_story_5082_50820902_67_dialog_content = "Levaram-me a todo tipo de locais escondidos para os meus \"testes\", incluindo edifícios abandonados e antigos campos de batalha..",
  ui_story_5082_50820902_68_dialog_content = "Vou marcar as localizações exatas no mapa. Você pode ser capaz de usar um desses lugares como um laboratório temporário.",
  ui_story_5082_50820902_69_dialog_content = "Mas é possível que você tenha que ir lá sozinho.",
  ui_story_5082_50820902_70_dialog_content = "Você não ouviu nada do que eu acabei de dizer?",
  ui_story_5082_50820902_71_dialog_content = "É muito provável que seu \"treinamento\" estava a serviço de um objetivo ainda maior—",
  ui_story_5082_50820902_72_dialog_content = "Mesmo assim!",
  ui_story_5082_50820902_73_dialog_content = "Irmã...",
  ui_story_5082_50820902_74_dialog_content = "Entendo sua preocupação, Negador. Mas fugir não resolverá nada.",
  ui_story_5082_50820902_75_dialog_content = "Você está disposto a me ajudar a fazer um pouco mais de investigação, Helios?",
  ui_story_5082_50820902_76_dialog_content = "Você nem precisa perguntar. Mas se nossas suposições estiverem corretas, o que você está preparado para fazer a respeito?",
  ui_story_5082_50820902_77_dialog_content = "O que você achou?",
  ui_story_5082_50820902_78_dialog_content = "D-Digamos que conseguimos resgatar as pessoas dentro... E depois?",
  ui_story_5082_50820902_79_dialog_content = "Ainda não planejei tão longe.",
  ui_story_5082_50820902_80_dialog_content = "Mas se eu apenas ficar de lado, sabendo que essas coisas terríveis estão acontecendo...",
  ui_story_5082_50820902_81_dialog_content = "Então qual seria o ponto de todos os meus esforços até este ponto?",
  ui_story_5082_50820902_82_dialog_content = "Quero me tornar o Grande Marechal e ser o soldado mais forte da Illumina algum dia. Sempre que ocorrer um desastre, quero estar na vanguarda da batalha e proteger todos.",
  ui_story_5082_50820902_83_dialog_content = "Não quero ser alguém que hesita quando seus aliados estão em perigo, ou se acovarda diante de uma nova ameaça—",
  ui_story_5082_50820902_84_dialog_content = "E me recuso a ser cúmplice dos esquemas auto engrandecedores de pessoas que fazem experimentos com crianças pequenas.",
  ui_story_5082_50820902_85_dialog_content = "Se os líderes da Illumina são todos assim, então eu preciso perguntar a eles...",
  ui_story_5082_50820902_86_dialog_content = "Quando eles entoam Splendor Illumina enquanto enviam nossos soldados da linha de frente para suas mortes, ou sequestram e torturam pessoas inocentes...",
  ui_story_5082_50820902_87_dialog_content = "É apenas para garantir a estabilidade de seus interesses?",
  ui_story_5082_50820902_88_dialog_content = "Espere, Reinhardt! Você sabe mesmo o que está dizendo?",
  ui_story_5082_50820902_89_dialog_content = "A alta cúpula já o vê como um extremista e uma ameaça depois que você falsificou ordens da última vez.",
  ui_story_5082_50820902_90_dialog_content = "Você realmente vai trair Illumina desta vez?!",
  ui_story_5082_50820902_91_dialog_content = "Trair? De maneira nenhuma.",
  ui_story_5082_50820902_92_dialog_content = "Os verdadeiros traidores são os covardes no comando do exército e os tolos que os obedecem.",
  ui_story_5082_50820902_93_dialog_content = "Os verdadeiros traidores são as pessoas que experimentam em crianças inocentes, bem como as pessoas que apenas ficam de pé e deixam isso acontecer.",
  ui_story_5082_50820902_94_dialog_content = "Recuso-me a concordar com isso e me recuso a pensar apenas na minha própria segurança.",
  ui_story_5082_50820902_95_dialog_content = "Negador, Helios, sinto muito por envolver vocês dois nessa confusão.",
  ui_story_5082_50820902_96_dialog_content = "Mas se eu comprometer meus ideais para preservar o status quo, nunca realizarei meus sonhos.",
  ui_story_5082_50820902_97_dialog_content = "É por isso que vou fazer tudo ao meu alcance para derrubar esse sistema podre e hipócrita.",
  ui_story_5082_50821001_1_dialog_content = "Não posso acreditar... A própria Grande Marechal tentou derrubar a Illumina no passado?!",
  ui_story_5082_50821001_2_dialog_content = "A estranha ligação telepática entre aqueles três soldados aumentados não foi acidente algum...",
  ui_story_5082_50821001_3_dialog_content = "Eles pensaram que estariam seguros enquanto mantivessem os resultados de suas pesquisas escondidos, mas isso apenas atraiu ainda mais a atenção de seus superiores.",
  ui_story_5082_50821001_4_dialog_content = "Derrubar a Illumina... foi um empreendimento ousado, para dizer o mínimo...",
  ui_story_5082_50821001_5_dialog_content = "Mas quando ela percebeu que seu potencial era real, e que seu poder era o resultado de um plano cuidadosamente construído, ela sabia que poderia fazer isso.",
  ui_story_5082_50821001_6_dialog_content = "... Você fala sobre o seu eu do passado como se ela fosse uma pessoa completamente diferente.",
  ui_story_5082_50821001_7_dialog_content = "Isso porque, na minha opinião, ela é uma pessoa totalmente diferente.",
  ui_story_5082_50821001_8_dialog_content = "A academia, o treinamento e os experimentos, o berçário... Todo esse tempo, eu pensei que minhas memórias dessas coisas estavam completas.",
  ui_story_5082_50821001_9_dialog_content = "Eu notava pequenas falhas em minhas memórias de vez em quando, mas nunca soube que havia tantos detalhes desconhecidos escondidos nelas.",
  ui_story_5082_50821001_10_dialog_content = "Especialmente o teste que todos nós três passamos. Parece que minhas memórias daquele dia foram completamente apagadas.",
  ui_story_5082_50821001_11_dialog_content = "Será que as minhas memórias do passado são completamente diferentes do que realmente aconteceu...?",
  ui_story_5082_50821001_12_dialog_content = "Tenho certeza que Vice sente o mesmo sobre isso também...",
  ui_story_5082_50821001_13_dialog_content = "Bom que conseguimos extrair um pouco da verdade dessas máquinas, certo?",
  ui_story_5082_50821001_14_dialog_content = "Como você também foi escolhido para os experimentos deles, é provável que tenha perdido suas memórias por um motivo semelhante.",
  ui_story_5082_50821001_15_dialog_content = "Não exatamente. Depois de ver meu passado, você deveria saber que eu não fui escolhido para pilotar a Colossus. Minhas memórias não indicam o contrário de qualquer maneira.",
  ui_story_5082_50821001_16_dialog_content = "Mesmo assim, eu realmente gostaria de saber o que aconteceu com ela depois.",
  ui_story_5082_50821001_17_dialog_content = "Seus palpites estavam na maioria corretos.",
  ui_story_5082_50821001_18_dialog_content = "De acordo com os últimos relatórios do laboratório, eles estão oficialmente prontos para ativar a Colossus Spearhead.",
  ui_story_5082_50821001_19_dialog_content = "A piloto que eles selecionaram atualmente é uma menina de quatro anos do berçário—",
  ui_story_5082_50821001_20_dialog_content = "A compatibilidade dela com os sistemas de backup é a mais alta entre todas as outras cobaias de teste.",
  ui_story_5082_50821001_21_dialog_content = "Você está brincando comigo? Eles estão forçando uma garotinha a fazer isso?!",
  ui_story_5082_50821001_22_dialog_content = "Não a subestime por causa da idade dela.",
  ui_story_5082_50821001_23_dialog_content = "Antes deste projeto, parece que o Comitê vinha treinando ela por um ano inteiro. É possível que ela tenha até mais experiência do que qualquer um de nós.",
  ui_story_5082_50821001_24_dialog_content = "Ela até alcançou uma taxa de sucesso de 20% em seu teste inicial.",
  ui_story_5082_50821001_25_dialog_content = "Negador, você...",
  ui_story_5082_50821001_26_dialog_content = "... Não coloque dessa maneira.",
  ui_story_5082_50821001_27_dialog_content = "Estou apenas sendo realista. Você viu como está indo nossa luta contra os Eclipsitas?",
  ui_story_5082_50821001_28_dialog_content = "Dado o estado atual do experimento, arriscar a vida de uma única criança em prol de inúmeras outras apresenta uma alta probabilidade de sucesso.",
  ui_story_5082_50821001_29_dialog_content = "Isso ainda não é motivo para brincar com a vida de uma criança! Não podemos esperar mais; temos que fazer alguma coisa!",
  ui_story_5082_50821001_30_dialog_content = "Deixando de lado a questão de por onde começar, você acabou de recuperar seus privilégios de comando. Denier e eu também estamos sendo isolados de você, o que significa que você não tem mais ninguém para confiar.",
  ui_story_5082_50821001_31_dialog_content = "Mesmo que eu tenha recuperado apenas alguns dos meus privilégios anteriores, isso não significa que estou começando do zero.",
  ui_story_5082_50821001_32_dialog_content = "Os soldados mais fortes da 1ª Legião já concordaram em me seguir.",
  ui_story_5082_50821001_33_dialog_content = "Farei o meu melhor para despistar a vigilância e estabelecer correspondência em uma das Cidades Baixas próximas.",
  ui_story_5082_50821001_34_dialog_content = "Entre em contato com Barton se precisar falar comigo. Ele concordou em nos ajudar também.",
  ui_story_5082_50821001_35_dialog_content = "Você pode estar isolado agora, mas isso apenas significa que você tem mais liberdade para coletar informações.",
  ui_story_5082_50821001_36_dialog_content = "Denier pode lidar com o progresso do laboratório. Enquanto isso, Helios, precisamos que você descubra quantos mais desses experimentos secretos estão sendo realizados em Illumina.",
  ui_story_5082_50821001_37_dialog_content = "Seja nas altas esferas militares ou entre os pesquisadores, temos que estar preparados para o pior cenário possível. Afinal, estamos em guerra.",
  ui_story_5082_50821001_38_dialog_content = "E quando eu me tornar Grande Marechal, minha primeira ordem de negócios será lutar pelas vidas de todas as vítimas inocentes desses experimentos.",
  ui_story_5082_50821001_39_dialog_content = "Mas ainda não sabemos quão poderoso o Comitê está agora. Você não acha que isso é muito arriscado?",
  ui_story_5082_50821001_40_dialog_content = "Se eles tiverem outro Reinhardt em algum lugar em espera, nossas chances de sucesso serão ainda mais escassas.",
  ui_story_5082_50821001_41_dialog_content = "Então, vamos apenas com o Plano B.",
  ui_story_5082_50821001_42_dialog_content = "Os Aurorians podem sobreviver praticamente em qualquer lugar, até mesmo em uma Subcidade abandonada...",
  ui_story_5082_50821001_43_dialog_content = "Desde que haja comida, água, espaço e luz suficientes, um assentamento para os Aurorianos se reunirem pode ser construído.",
  ui_story_5082_50821001_44_dialog_content = "E onde quer que os aurorianos se reúnam, sempre haverá a necessidade de um Grande Marechal.",
  ui_story_5082_50821001_45_dialog_content = "Hahaha! Você está pensando muito à frente, Negador. Eu não tenho intenção de deixar as coisas chegarem a esse ponto.",
  ui_story_5082_50821001_46_dialog_content = "Afinal, nosso objetivo original era fornecer um lugar de abrigo para todos os Aurorianos afetados pela crise...",
  ui_story_5082_50821001_47_dialog_content = "Para proteger as crianças que, como nós, não têm lembrança de seus próprios pais e devem confiar em seus punhos para sobreviver.",
  ui_story_5082_50821001_48_dialog_content = "...",
  ui_story_5082_50821001_49_dialog_content = "Muitas pessoas em Illumina compartilham a mesma história, huh...",
  ui_story_5082_50821001_50_dialog_content = "Eu só sabia sobre Vice antes, mas depois de ver isso... Eu sinto muito por todos...",
  ui_story_5082_50821001_51_dialog_content = "Ninguém tinha uma situação melhor do que ninguém naquela época. Aposto que muitas pessoas tiveram experiências semelhantes àquela menina de quatro anos.",
  ui_story_5082_50821001_52_dialog_content = "Quanto a Vice, estou começando a pensar... Que as memórias dela desses experimentos podem não ser totalmente reais.",
  ui_story_5082_50821001_53_dialog_content = "Você, por outro lado, parece simpatizar muito com aquela garota.",
  ui_story_5082_50821001_54_dialog_content = "... Então o seu plano deu certo no final?",
  ui_story_5082_50821001_55_dialog_content = "Se você precisa perguntar, então tudo o que posso fazer é lembrá-lo de que agora sou o Grande Marechal de Illumina.",
  ui_story_5082_50821001_56_dialog_content = "Ainda estamos falando sobre o mesmo você? Ou a mesma Illumina, nesse caso?",
  ui_story_5082_50821001_57_dialog_content = "Isso é realmente importante? É óbvio que o \"plano dela\" falhou no final, não é?",
  ui_story_5082_50821001_58_dialog_content = "Eu acho que é muito importante.",
  ui_story_5082_50821001_59_dialog_content = "Estou curioso para saber o resultado, mesmo que tudo tenha sido no passado.",
  ui_story_5082_50821001_60_dialog_content = "Mas o que você está dizendo agora parece que está vindo do Reinhardt de hoje.",
  ui_story_5082_50821001_61_dialog_content = "Parte disso implica sua vitória sobre \"ela\", enquanto o resto implica a falha de \"ela\" em relação a Illumina.",
  ui_story_5082_50821001_62_dialog_content = "Então eu tenho que perguntar: onde exatamente você está agora, Reinhardt?",
  ui_story_5082_50821001_63_dialog_content = "Mataria você ser mais direto às vezes?",
  ui_story_5082_50821001_64_dialog_content = "Estou apenas complicando as coisas porque estamos falando de você.",
  ui_story_5082_50821001_65_dialog_content = "Então parece que eu preciso ser mais honesto com você.",
  ui_story_5082_50821001_66_dialog_content = "Para te dizer a verdade, eu estou um pouco confusa também. Você acha que \"Reinhardt\" é mais como eu, ou que eu sou mais como ela?",
  ui_story_5082_50821001_67_dialog_content = "Eu...",
  ui_story_5082_50821001_68_dialog_content = "Você não precisa fugir da pergunta. Não vou ficar chateado, não importa o que você diga, eu prometo.",
  ui_story_5082_50821001_69_dialog_content = "Th-Isso não é o que está na minha mente.",
  ui_story_5082_50821001_70_dialog_content = "Ela apenas parece muito mais livre e desinibida, e...",
  ui_story_5082_50821001_71_dialog_content = "Desculpe, eu realmente não sei como descrever isso melhor agora.",
  ui_story_5082_50821001_72_dialog_content = "Não se preocupe. Você já acertou em cheio na cabeça.",
  ui_story_5082_50821001_73_dialog_content = "Como você pode ver, somos muito diferentes um do outro.",
  ui_story_5082_50821001_74_dialog_content = "A qualquer momento, alguém na Illumina poderia estar passando pelo mesmo inferno que eu passei naquela época.",
  ui_story_5082_50821001_75_dialog_content = "Você acha que depois de todos esses anos vendo a brutalidade da Zona Cega por mim mesmo, eu não fui mudado por isso?",
  ui_story_5082_50821001_76_dialog_content = "Achei que não tinha. Com todo o meu coração, eu desejava que não tivesse.",
  ui_story_5082_50821001_77_dialog_content = "Quando eu era jovem, eu pensava que poderia proteger toda a Federação sozinho.",
  ui_story_5082_50821001_78_dialog_content = "Mas depois de perder tantos camaradas, comecei a me perguntar, \"Mesmo que eu pudesse proteger todos sozinho, por quanto tempo isso poderia durar?\"",
  ui_story_5082_50821001_79_dialog_content = "Se alguém jovem e irritado como ela estivesse na minha frente agora e me chamasse de inútil e corrupto...",
  ui_story_5082_50821001_80_dialog_content = "E juraram me derrubar e construir um mundo novo e brilhante em meu lugar...",
  ui_story_5082_50821001_81_dialog_content = "Não sei se a impediria, a apoiaria...",
  ui_story_5082_50821001_82_dialog_content = "Ou até...",
  ui_story_5082_50821001_83_dialog_content = "Eu talvez não entenda o peso da liderança como você, mas como seu amigo, eu sei com certeza que você não é esse tipo de pessoa...",
  ui_story_5082_50821001_84_dialog_content = "Você também está longe de ser o único a apoiar a Illumina.",
  ui_story_5082_50821001_85_dialog_content = "Eu sei o que você está tentando dizer, mas depois de vê-la e lembrar de tudo que aconteceu naquela época... Não posso deixar de me sentir um pouco insatisfeito.",
  ui_story_5082_50821001_86_dialog_content = "Ainda assim, não tenho medo de compartilhar essas coisas com você. Me ver assim deve ser um pouco decepcionante, huh?",
  ui_story_5082_50821001_87_dialog_content = "Não mesmo.",
  ui_story_5082_50821001_88_dialog_content = "Vamos voltar. Os outros devem estar cansados de esperar por nós agora.",
  ui_story_5082_50821001_89_dialog_content = "... Então a Grande Marechal estava se vendo em suas memórias passadas?",
  ui_story_5082_50821001_90_dialog_content = "... E você, Barton? Quanto você sabe sobre o que aconteceu naquela época?",
  ui_story_5082_50821001_91_dialog_content = "Minha compreensão é que Reinhardt, Forsakin e Helios estavam secretamente planejando algo naquela época.",
  ui_story_5082_50821001_92_dialog_content = "...",
  ui_story_5082_50821001_93_dialog_content = "Eu também te disse que te apoiaria não importa o quê, mas nunca recebi notícias de nada até o fim.",
  ui_story_5082_50821001_94_dialog_content = "Eu só sabia que você estava de alguma forma envolvido na explosão do laboratório, mas eu não tinha como investigar o assunto naquele momento.",
  ui_story_5082_50821001_95_dialog_content = "Nossas mãos já estavam atadas com a Crise Darkover, e havia um mundo de trabalho a ser feito após os combates.",
  ui_story_5082_50821001_96_dialog_content = "Você ainda não havia se tornado comandante quando nos vimos novamente, mas já estava pronto para subir muito além dessa patente.",
  ui_story_5082_50821001_97_dialog_content = "Então, mesmo depois de tudo isso ter acontecido... Reinhardt foi promovido novamente?",
  ui_story_5082_50821001_98_dialog_content = "Isso mesmo, e ela era uma pessoa completamente diferente naquela época também: firme, imponente e um terror absoluto no campo de batalha. Seu poder já impressionante parecia crescer a cada dia que passava.",
  ui_story_5082_50821001_99_dialog_content = "Comparado a ela e seu crescimento explosivo, eu era apenas um soldado raso pisando na lama.",
  ui_story_5082_50821001_100_dialog_content = "Então, enquanto eu realizava minhas missões, também me submetia ao meu próprio tipo de treinamento especial. Foi também por volta dessa época que comecei a ser mais rigoroso com meus subordinados!",
  ui_story_5082_50821001_101_dialog_content = "Entendi. Então foi quando a 2ª Legião desenvolveu uma reputação por seus métodos de treinamento duros e implacáveis.",
  ui_story_5082_50821001_102_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_5082_50821001_103_dialog_content = "Miau! E aqui eu pensei que já tinha acabado!",
  ui_story_5082_50821001_104_dialog_content = "Por que eles continuam batendo nas paredes?",
  ui_story_5082_50821001_105_dialog_content = "Este lugar é estruturalmente instável demais para suportar suas colisões! Precisamos pará-los antes que as paredes desabem e nos enterrem vivos!",
  ui_story_5082_50821101_1_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5082_50821101_2_dialog_content = "Estão todos bem?",
  ui_story_5082_50821101_3_dialog_content = "Estou bem! Mas eu preferiria não levar outra queda dessa altura tão cedo.",
  ui_story_5082_50821101_4_dialog_content = "Estou bem, Grande Marechal.",
  ui_story_5082_50821101_5_dialog_content = "E você, PlayerName?",
  ui_story_5082_50821101_6_dialog_content = "Estou bem... Obrigado pela ajuda, Barton. Eu teria sido esmagado agora se não fosse por você.",
  ui_story_5082_50821101_7_dialog_content = "Um pouco mais de treino e você não precisaria depender tanto de mim, sabe!",
  ui_story_5082_50821101_8_dialog_content = "Quando tudo isso acabar, com certeza vou adicionar treinamento em altitude à sua rotina diária!",
  ui_story_5082_50821101_9_dialog_content = "Parece que pousamos no nível mais baixo do centro de pesquisa.",
  ui_story_5082_50821101_10_dialog_content = "Por que eles precisavam de um espaço tão enorme aqui embaixo?",
  ui_story_5082_50821101_11_dialog_content = "Posso responder isso sem ter que vasculhar minhas memórias. É aqui que eles guardavam.",
  ui_story_5082_50821101_12_dialog_content = "Tudo que vejo é um monte de ossos enormes... Espere! Este é o Colosso que senti anteriormente!",
  ui_story_5082_50821101_13_dialog_content = "... Dado o seu estado atual, não é surpresa que a Cidade Baixa tenha começado a desmoronar sobre si mesma.",
  ui_story_5082_50821101_14_dialog_content = "... Você ainda consegue se lembrar do que aconteceu durante aqueles experimentos naquela época, Reinhardt?",
  ui_story_5082_50821101_15_dialog_content = "Minhas memórias daquela época não são totalmente claras, mas sei com certeza que ela nunca mais apareceu depois que me tornei Comandante da Legião.",
  ui_story_5082_50821101_16_dialog_content = "Ainda assim, tenho um bom palpite sobre o que aconteceu aqui.",
  ui_story_5082_50821101_17_dialog_content = "Minhas memórias daquela época não são totalmente claras, mas sei com certeza que ela nunca mais apareceu depois que me tornei Comandante da Legião.",
  ui_story_5082_50821101_18_dialog_content = "Ainda assim, tenho um bom palpite sobre o que aconteceu aqui.",
  ui_story_5082_50821101_19_dialog_content = "Eles devem ter pensado que enterraram tudo, incluindo o meu passado...",
  ui_story_5082_50821101_20_dialog_content = "Mas ela ainda está por aqui por algum motivo, como se quisesse me dizer algo.",
  ui_story_5082_50821101_21_dialog_content = "Acho que este lugar, ou melhor, o acidente que ocorreu aqui, é a última peça do quebra-cabeça relacionada a ela.",
  ui_story_5082_50821101_22_dialog_content = "O que quer que tenha acontecido aqui fez com que ela se separasse do meu corpo...",
  ui_story_5082_50821101_23_dialog_content = "E também me concedeu o poder avassalador que me fez o Grande Marechal que sou hoje.",
  ui_story_5082_50821101_24_dialog_content = "Depois de aprender a verdade por trás do Programa Phospherus, não me surpreendo mais com nada sobre mim mesmo.",
  ui_story_5082_50821101_25_dialog_content = "Ulysses uma vez disse que eu trouxe uma década de paz para todos de Illumina... Heh, parece que me tornei o supersoldado perfeito afinal.",
  ui_story_5082_50821101_26_dialog_content = "...",
  ui_story_5082_50821101_27_dialog_content = "... Não vamos tirar conclusões precipitadas ainda. Ainda temos muita investigação a fazer.",
  ui_story_5082_50821101_28_dialog_content = "Podemos até desenterrar algumas novas evidências provando que seu poder veio ao descobrir seu verdadeiro potencial!",
  ui_story_5082_50821101_29_dialog_content = "Meu pelo em pé significa que não estamos sozinhos aqui embaixo!",
  ui_story_5082_50821101_30_dialog_content = "<color=#e8d9bb>Zumbido—!</color>",
  ui_story_5082_50821101_31_dialog_content = "(Esse barulho... Eu sei o que é...)",
  ui_story_5082_50821101_32_option_content = "Ligação da mente!",
  ui_story_5082_50821101_33_dialog_content = "... Ponta de Lança!",
  ui_story_5082_50821101_34_dialog_content = "Você veio, exatamente como prometeu.",
  ui_story_5082_50821101_35_dialog_content = "Eu não prometi nada. Você é quem me pediu para te encontrar.",
  ui_story_5082_50821101_36_dialog_content = "Mas agora que estou aqui, preciso te fazer algumas perguntas.",
  ui_story_5082_50821101_37_dialog_content = "Eu sei o que você procura. Você deseja aprender mais sobre o passado de uma certa garota, ou os passados de duas garotas diferentes.",
  ui_story_5082_50821101_38_dialog_content = "(Eu sabia! As memórias perdidas de Vice e Reinhardt estão ligadas aos experimentos de seleção do Navegador que aconteceram aqui!)",
  ui_story_5082_50821101_39_dialog_content = "Diga-me o que aconteceu com eles naquela época!",
  ui_story_5082_50821101_40_dialog_content = "O que você procura é apenas uma pequena quantidade de dados armazenados neste lugar.",
  ui_story_5082_50821101_41_dialog_content = "Mas, os dados estão espalhados e fragmentados. No meu atual estado de desgaste, não consigo recuperá-los ou mesmo vê-los claramente.",
  ui_story_5082_50821101_42_dialog_content = "Está me pedindo para ajudar a recuperá-lo?",
  ui_story_5082_50821101_43_dialog_content = "Você é quem está procurando os dados, não eu.",
  ui_story_5082_50821101_44_dialog_content = "... Então o que devo fazer?",
  ui_story_5082_50821101_45_dialog_content = "Aqueles que me despedaçaram tentaram remodelar meus sistemas usando sua tecnologia ultrapassada.",
  ui_story_5082_50821101_46_dialog_content = "Como tal, não posso mais restaurá-los ao seu estado original, Celestita.",
  ui_story_5082_50821101_47_dialog_content = "No entanto, aquele dispositivo permitirá que você se conecte comigo e encontre o que procura.",
  ui_story_5082_50821101_48_dialog_content = "Eu só tenho que colocar, certo?",
  ui_story_5082_50821101_49_dialog_content = "Espere PlayerName, o que você está fazendo?",
  ui_story_5082_50821101_50_dialog_content = "Acabei de fazer contato com a consciência de Spearhead. Ele diz que eu posso ser capaz de encontrar o que estamos procurando ao colocar isso.",
  ui_story_5082_50821101_51_dialog_content = "Você não se lembra do que me disse antes de descermos aqui?",
  ui_story_5082_50821101_52_dialog_content = "Eu faço, mas com as coisas como estão agora, esta é a nossa última pista restante.",
  ui_story_5082_50821101_53_dialog_content = "Lutamos tanto para chegar até aqui. Não quero que os esforços de todos tenham sido em vão.",
  ui_story_5082_50821101_54_dialog_content = "Sei que é um pouco perigoso, mas todos nós cuidamos uns dos outros, não é?",
  ui_story_5082_50821101_55_dialog_content = "Isso também é o que eu quis dizer quando disse que você não é o único apoiando a Illumina. Você também pode contar conosco, Reinhardt.",
  ui_story_5082_50821101_56_dialog_content = "Mesmo que Spearhead tente fazer algo, tenho certeza de que todos aqui podem impedi-lo. Afinal, Illumina já o derrotou uma vez antes, certo?",
  ui_story_5082_50821101_57_dialog_content = "Bem dito, criança! Nunca me canso de ver você defendendo seus amigos em seu momento de necessidade! Então, o que você diz, Grande Marechal?",
  ui_story_5082_50821101_58_dialog_content = "Entendido. Só tome cuidado, ok?",
  ui_story_5082_50821101_59_dialog_content = "Pode deixar.",
  ui_story_5082_50821101_60_dialog_content = "(Então primeiro, eu tenho que colocar isso na minha cabeça, e então...)",
  ui_story_5082_50821101_61_option_content = "Psíquico–",
  ui_story_5082_50821101_62_dialog_content = "Os ajustes no Colossus estão quase completos. Vou notificar o Oficial de Tecnologia imediatamente.",
  ui_story_5082_50821101_63_dialog_content = "Tudo o que precisamos fazer agora é encontrar um \"Navegador\" adequado, e podemos começar os testes.",
  ui_story_5082_50821101_64_dialog_content = "Qual dos temas tem a maior compatibilidade?",
  ui_story_5082_50821101_65_dialog_content = "Após os testes que realizamos com nossos três candidatos anteriores, eles começaram a omitir informações pessoais para o restante de nossos sujeitos de teste. Agora, apenas seus dados estão visíveis para nós.",
  ui_story_5082_50821101_66_dialog_content = "Lembro-me daqueles três. Os dados deles eram bastante promissores, se me lembro bem?",
  ui_story_5082_50821101_67_dialog_content = "De fato. Eles vieram do Projeto Sol Artificial, afinal de contas.",
  ui_story_5082_50821101_68_dialog_content = "No entanto, havia diferenças notáveis entre suas performances e os resultados dos testes. O Comitê tem motivos para suspeitar que eles deliberadamente deturparam suas capacidades durante o experimento.",
  ui_story_5082_50821101_69_dialog_content = "É mesmo?",
  ui_story_5082_50821101_70_dialog_content = "Então, independentemente da compatibilidade deles com o Colossus, se estiverem dispostos a mentir para nós durante os testes, não temos utilidade para eles.",
  ui_story_5082_50821101_71_dialog_content = "Se o Comitê os considerar culpados disso, eles precisarão de toda a sorte que puderem conseguir.",
  ui_story_5082_50821101_72_dialog_content = "(Argh, não suporto a maneira como esses cientistas falam.)",
  ui_story_5082_50821101_73_dialog_content = "(... Mas eu tenho que continuar assistindo.)",
  ui_story_5082_50821101_74_dialog_content = "Quando chegaremos à parte dessas duas garotas, Lança?",
  ui_story_5082_50821101_75_dialog_content = "Em breve. Prometo.",
  ui_story_5082_50821101_76_dialog_content = "Aguarde o sinal para estender, Celestita. Procure um botão especial e depois pressione-o!",
  ui_story_5082_50821101_77_dialog_content = "Um botão especial, huh...",
  ui_story_5082_50821101_78_dialog_content = "Lá! Rapidamente, Celestita!",
  ui_story_5082_50821101_79_dialog_content = "(Por que a cena de repente...?)",
  ui_story_5082_50821101_80_dialog_content = "Rapidamente... Aperte o botão! Depressa—!",
  ui_story_5082_50821101_81_dialog_content = "Urgh, minha cabeça... O que você acha que está fazendo, Lança-ponta?!",
  ui_story_5082_50821101_82_dialog_content = "Pressione o botão e me deixe livre!",
  ui_story_5082_50821101_83_dialog_content = "Como uma arma do Eclipse, destruirei todos os Aurorians em nome dos meus mestres!",
  ui_story_5082_50821101_84_dialog_content = "!",
  ui_story_5082_50821101_85_dialog_content = "Morte à Illumina! Morte a esses tolos insolentes, e especialmente aquele cara!",
  ui_story_5082_50821101_86_dialog_content = "Por me deixar em um estado tão deplorável... Eu jurei vingar-me deles, mesmo que custe a minha existência!",
  ui_story_5082_50821101_87_dialog_content = "(Tal ódio poderoso... Ainda estou nos arquivos de memória do Spearhead, ou essa é a sua consciência real?",
  ui_story_5082_50821101_88_dialog_content = "(... Se está me deixando ver isso, significa que a mente do Colosso já está muito instável.)",
  ui_story_5082_50821101_89_dialog_content = "(Essa pode ser minha chance de procurar seu ponto fraco!)",
  ui_story_5082_50821101_90_option_content = "Alcance Telepático!",
  ui_story_5082_50821101_91_dialog_content = "<color=#e8d9bb>Mas em vez do ponto fraco da Spearhead, um grito penetrante soa ainda mais claramente.</color>",
  ui_story_5082_50821101_92_dialog_content = "(Esse grito... É ela!)",
  ui_story_5082_50821101_93_dialog_content = "Você está aí? Consegue me ouvir?!",
  ui_story_5082_50821101_94_dialog_content = "Reinhardt!",
  ui_story_5082_50821101_95_dialog_content = "Isso é estranho. Você é o meu primeiro visitante neste lugar.",
  ui_story_5082_50821101_96_dialog_content = "Finalmente tenho a chance de falar com você!",
  ui_story_5082_50821101_97_dialog_content = "\"Finalmente\"?",
  ui_story_5082_50821101_98_dialog_content = "Reinhardt e eu... Quero dizer, o outro você! Estivemos procurando por você todo esse tempo!",
  ui_story_5082_50821101_99_dialog_content = "...",
  ui_story_5082_50821101_100_dialog_content = "A criança está usando aquilo há muito tempo. Por que ele ainda não se mexeu?",
  ui_story_5082_50821101_101_dialog_content = "Faz apenas cerca de trinta segundos, Comandante Barton! Não tenha tanta pressa!",
  ui_story_5082_50821101_102_dialog_content = "PlayerName disse que o tempo flui de maneira diferente no mundo subconsciente. Vamos continuar esperando.",
  ui_story_5082_50821101_103_dialog_content = "PlayerName depositou sua confiança em nós, então devemos fazer o mesmo por ele.",
  ui_story_5082_50821101_104_dialog_content = "...",
  ui_story_5082_50821101_105_dialog_content = "Enquanto isso, precisamos estar prontos para a batalha a todo momento se vamos protegê-lo.",
  ui_story_5082_50821101_106_dialog_content = "Cuidado com as 3 horas, Barton!",
  ui_story_5082_50821101_107_dialog_content = "Ah! Era exatamente isso que eu estava esperando!",
  ui_story_5082_50821101_108_dialog_content = "<color=#e8d9bb>Bam, bam, bam!</color>",
  ui_story_5082_50821101_109_dialog_content = "<color=#e8d9bb>De repente, dezenas de pequenas máquinas começam a voar para fora dos restos do Colosso.</color>",
  ui_story_5082_50821101_110_dialog_content = "Esse grandalhão estava apenas fingindo estar morto!",
  ui_story_5082_50821101_111_dialog_content = "Proteja PlayerName e prepare-se para lutar!",
  ui_story_5082_50821201_1_dialog_content = "E isso é mais ou menos o que está acontecendo lá fora.",
  ui_story_5082_50821201_2_dialog_content = "Reinhardt? Você não me ouviu?",
  ui_story_5082_50821201_3_dialog_content = "Eu fiz.",
  ui_story_5082_50821201_4_dialog_content = "Estou impressionado que aquele teimoso tolo realmente se tornou Grande Marechal.",
  ui_story_5082_50821201_5_dialog_content = "Você diz isso como se estivesse falando de uma pessoa diferente.",
  ui_story_5082_50821201_6_dialog_content = "Não é tão distante da verdade. Afinal, existe um mundo de diferenças entre nós.",
  ui_story_5082_50821201_7_dialog_content = "Você está soando muito como ela agora mesmo...",
  ui_story_5082_50821201_8_dialog_content = "Você deve ser um celestita, certo?",
  ui_story_5082_50821201_9_dialog_content = "Eu? S-Sim, está certo.",
  ui_story_5082_50821201_10_dialog_content = "Acha que pode usar seus poderes para me deixar falar com ela?",
  ui_story_5082_50821201_11_dialog_content = "Eu tenho algo que quero dizer a ela.",
  ui_story_5082_50821201_12_dialog_content = "Normalmente isso seria bom, mas estou usando um dos dispositivos de Spearhead para me comunicar com você agora.",
  ui_story_5082_50821201_13_dialog_content = "Não posso me dar ao luxo de desestabilizar ainda mais a consciência do Spearhead, ou será ainda mais difícil de parar.",
  ui_story_5082_50821201_14_dialog_content = "E depois de descobrir sua conexão com os Eclipsitas, trazer Reinhardt para cá seria muito perigoso.",
  ui_story_5082_50821201_15_dialog_content = "O que me lembra... O que exatamente fez você ficar aqui?",
  ui_story_5082_50821201_16_dialog_content = "Então você está dizendo que se conseguirmos desviar a atenção do Colossus, você terá uma maneira de contorná-lo?",
  ui_story_5082_50821201_17_dialog_content = "Suponho que seja possível... Mas como você vai chamar a atenção do Spearhead?",
  ui_story_5082_50821201_18_dialog_content = "Assim, obviamente—!",
  ui_story_5082_50821201_19_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5082_50821201_20_dialog_content = "<color=#e8d9bb>Enquanto as chamas selvagens se espalham rapidamente por todo o espaço, ela começa a rir loucamente em meio ao inferno furioso.</color>",
  ui_story_5082_50821201_21_dialog_content = "Ah, faz tanto tempo que não me sinto tão bem!",
  ui_story_5082_50821201_22_dialog_content = "Desculpe, Colossus, mas depois de ouvir que você é amigo dos Eclipsitas, não tenho um pingo de simpatia por você.",
  ui_story_5082_50821201_23_dialog_content = "Não posso machucar seu corpo físico, então terei que incendiar toda a sua mente! Dói, não dói?!",
  ui_story_5082_50821201_24_dialog_content = "Você! Como ousa—!",
  ui_story_5082_50821201_25_dialog_content = "Você não é nada além de dados residuais na minha consciência! Eu posso apagar sua existência quando eu quiser!",
  ui_story_5082_50821201_26_dialog_content = "O espaço está desaparecendo... Spearhead deve estar deletando os dados!",
  ui_story_5082_50821201_27_dialog_content = "Sua consciência também está sendo armazenada aqui, não está? Tem certeza de que isso está bem?",
  ui_story_5082_50821201_28_dialog_content = "Eu vou ficar bem, contanto que não me pegue.",
  ui_story_5082_50821201_29_dialog_content = "O que você quer dizer com isso?",
  ui_story_5082_50821201_30_dialog_content = "O que quero dizer é—",
  ui_story_5082_50821201_31_dialog_content = "Corra!",
  ui_story_5082_50821201_32_dialog_content = "Você parecia tão confiante agora! Isso realmente é a melhor ideia que você poderia ter?!",
  ui_story_5082_50821201_33_dialog_content = "Hahahaha!",
  ui_story_5082_50821201_34_dialog_content = "Miau!",
  ui_story_5082_50821201_35_dialog_content = "Philyshy! Como você pode estar brincando com essas coisas enquanto eles estão nos atacando?!",
  ui_story_5082_50821201_36_dialog_content = "Desculpe, eles apenas parecem uma grande e longa cauda quando se unem assim! Eu não pude evitar!",
  ui_story_5082_50821201_37_dialog_content = "Faz sentido quando você coloca dessa maneira. O Colossus deve estar controlando cada uma dessas \"caudas\" para nos atacar...",
  ui_story_5082_50821201_38_dialog_content = "Mesmo que não consiga mover seu corpo, seu centro de comando ainda é funcional o suficiente para nos atacar com seus restos esqueléticos!",
  ui_story_5082_50821201_39_dialog_content = "Esses são exatamente os meus pensamentos!",
  ui_story_5082_50821201_40_dialog_content = "Hmph! Até onde eu sei, este Colossus acabado só serve para abanar o rabo para nós agora!",
  ui_story_5082_50821201_41_dialog_content = "<color=#e8d9bb>Pit, pat, pit, pat—!</color>",
  ui_story_5082_50821201_42_dialog_content = "Huh? PlayerName?!",
  ui_story_5082_50821201_43_dialog_content = "De todas as vezes para aparecer— Espere, não se mova!",
  ui_story_5082_50821201_44_dialog_content = "<color=#e8d9bb>Crepitar—</color>",
  ui_story_5082_50821201_45_dialog_content = "... Uma corrente elétrica?",
  ui_story_5082_50821201_46_dialog_content = "Afaste-se daquela cauda, Philyshy! Algo não está certo nela!",
  ui_story_5082_50821201_47_dialog_content = "Zumbido—Buzz—",
  ui_story_5082_50821201_48_dialog_content = "Os ossos estão se multiplicando! Fiquem em alerta, todos; a Colossus pode atacar em breve—",
  ui_story_5082_50821201_49_dialog_content = "<color=#e8d9bb>Boom! Boom! Boom!</color>",
  ui_story_5082_50821201_50_dialog_content = "Posso sentir o cheiro de explosões vindo de dentro das paredes!",
  ui_story_5082_50821201_51_dialog_content = "A estrutura vai desabar! Precisamos limpar esses cabos e encontrar um lugar para nos abrigar!",
  ui_story_5082_50821201_52_dialog_content = "Mas e quanto a PlayerName? Esqueça, eu mesmo vou carregá-lo!",
  ui_story_5082_50821201_53_dialog_content = "Ei! Grande Marechal! Agora não é hora de—",
  ui_story_5082_50821201_54_dialog_content = "... Eu posso ouvir uma contagem regressiva.",
  ui_story_5082_50821201_55_dialog_content = "Reinhardt!",
  ui_story_5082_50821201_56_dialog_content = "... Uma corrente elétrica, uma explosão e... os gritos dela.",
  ui_story_5082_50821201_57_dialog_content = "Reinhardt!!!",
  ui_story_5082_50821201_58_dialog_content = "A mesma coisa aconteceu naquela época.",
  ui_story_5082_50821201_59_dialog_content = "<color=#e8d9bb>Uma parede próxima explode, enviando cabos e rochas colidindo com o chão.</color>",
  ui_story_5082_50821201_60_dialog_content = "Golpe Infinito!",
  ui_story_5082_50821201_61_dialog_content = "<color=#e8d9bb>Barton divide ao meio um enorme pedaço de detritos caindo antes que caia sobre ele.</color>",
  ui_story_5082_50821201_62_dialog_content = "<color=#e8d9bb>Ele então mantém seu ritmo.</color>",
  ui_story_5082_50821201_63_dialog_content = "Barton...",
  ui_story_5082_50821201_64_dialog_content = "Agora não é hora para sonhar acordado! Além disso, o que você achou da minha técnica agora há pouco?",
  ui_story_5082_50821201_65_dialog_content = "Hahaha, foi tão feroz quanto sempre! Obrigado, Barton.",
  ui_story_5082_50821201_66_dialog_content = "Obrigado por sempre lutar ao meu lado!",
  ui_story_5082_50821201_67_dialog_content = "É natural, não é? Agora vamos, este lugar é muito perigoso para—",
  ui_story_5082_50821201_68_dialog_content = "Não se preocupe, estou bem agora.",
  ui_story_5082_50821201_69_dialog_content = "Só preciso passar pelo que aconteceu naquela época mais uma vez.",
  ui_story_5082_50821201_70_dialog_content = "<color=#e8d9bb>O edifício estronda e colide enquanto as paredes desmoronam.</color>",
  ui_story_5082_50821201_71_dialog_content = "<color=#e8d9bb>Como o olho de uma tempestade, Reinhardt permanece completamente imperturbável no centro do caos; até mesmo o ar ao seu redor parece perfeitamente imóvel.</color>",
  ui_story_5082_50821201_72_dialog_content = "Vá se proteger.",
  ui_story_5082_50821201_73_dialog_content = "Ainda devo uma revanche a este cara.",
  ui_story_5082_50821202_1_dialog_content = "Que lugar é esse...?",
  ui_story_5082_50821202_2_dialog_content = "É um espaço criado por esse dispositivo. Ele usa os dados do sistema Spearhead como sua base.",
  ui_story_5082_50821202_3_dialog_content = "Graças a você ferindo o Spearhead do lado de fora, conseguimos nos proteger com segurança aqui dentro.",
  ui_story_5082_50821202_4_dialog_content = "Seus poderes são muito mais impressionantes do que eu imaginava.",
  ui_story_5082_50821202_5_dialog_content = "Não apenas você poderia me ajudar a controlar a consciência de Spearhead, mas também poderia trazê-la para cá assim que ela desencadeasse seu Lumina.",
  ui_story_5082_50821202_6_dialog_content = "Resolve os combates do lado de fora, enquanto também garante que a operação do dispositivo permaneça ininterrupta.",
  ui_story_5082_50821202_7_dialog_content = "Tenho certeza de que você realizará coisas ainda mais incríveis com esse poder no futuro.",
  ui_story_5082_50821202_8_dialog_content = "Obrigado, mas você é quem veio com esse plano... que eu ainda acho que era muito perigoso! E se seus dados fossem excluídos?!",
  ui_story_5082_50821202_9_dialog_content = "Não existe tal coisa como uma batalha sem riscos.",
  ui_story_5082_50821202_10_dialog_content = "Além disso, tudo deu certo no final, não foi?",
  ui_story_5082_50821202_11_dialog_content = "Conseguimos pôr um fim à luta aqui e lá fora, e eu pude aprender mais sobre suas habilidades de Caelestite.",
  ui_story_5082_50821202_12_dialog_content = "E agora que sei que posso confiar em você, posso dizer com segurança...",
  ui_story_5082_50821202_13_dialog_content = "Que essa pessoa não mudou muito de como eu me lembro dela.",
  ui_story_5082_50821202_14_dialog_content = "Há quanto tempo, Reinhardt.",
  ui_story_5082_50821202_15_dialog_content = "Parece um pouco estranho ouvir isso, considerando que só comecei a me lembrar de você hoje...",
  ui_story_5082_50821202_16_dialog_content = "Mas há quanto tempo, Reinhardt.",
  ui_story_5082_50821202_17_dialog_content = "Uh, Reinhardt...?",
  ui_story_5082_50821202_18_dialog_content = "Sim?",
  ui_story_5082_50821202_19_dialog_content = "...",
  ui_story_5082_50821202_20_dialog_content = "Hahahaha! Se isso facilitar as coisas, você pode me chamar de \"Renegado\"!",
  ui_story_5082_50821202_21_dialog_content = "É isso que todos costumavam me chamar pelas minhas costas. Eu sei que eles não queriam dizer nada de bom com isso, mas eu sempre gostei do nome.",
  ui_story_5082_50821202_22_dialog_content = "Eu simplesmente não sei se você ainda se lembra de algo disso, Reinhardt.",
  ui_story_5082_50821202_23_dialog_content = "Entendi. Você não tem certeza se ainda sou a mesma pessoa que conheceu, e eu só acabei de lembrar que você existia.",
  ui_story_5082_50821202_24_dialog_content = "Então, por que não nos conhecemos de novo?",
  ui_story_5082_50821202_25_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5082_50821202_26_dialog_content = "O que significa esse estrondo, PlayerName?",
  ui_story_5082_50821202_27_dialog_content = "É a Spearhead... Ela nos encontrou!",
  ui_story_5082_50821202_28_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5082_50821202_29_option_content = "Aumento de Força!",
  ui_story_5082_50821202_30_dialog_content = "Foi vocês!",
  ui_story_5082_50821202_31_dialog_content = "Vocês foram os que destruíram meu corpo! Vocês foram os que me enterraram vivo por treze anos!",
  ui_story_5082_50821202_32_dialog_content = "Agora morra—!",
  ui_story_5082_50821202_33_option_content = "Aumento de Força!",
  ui_story_5082_50821202_34_dialog_content = "Ugh!",
  ui_story_5082_50821202_35_dialog_content = "Posso criar uma barreira para manter o Spearhead à distância por enquanto, mas este ainda é o seu domínio.",
  ui_story_5082_50821202_36_dialog_content = "Com o quão caótica sua consciência se tornou, não tenho certeza de quanto tempo posso continuar assim—",
  ui_story_5082_50821202_37_dialog_content = "Quem está pedindo para você parar?",
  ui_story_5082_50821202_38_dialog_content = "Se alguém te bater, sua primeira reação não deveria ser bater de volta?",
  ui_story_5082_50821202_39_dialog_content = "Não!",
  ui_story_5082_50821202_40_dialog_content = "Seus dados ainda estão sendo armazenados aqui! Se lutarmos agora—",
  ui_story_5082_50821202_41_dialog_content = "Não há nada mais inútil do que ser indeciso em batalha.",
  ui_story_5082_50821202_42_dialog_content = "Se você tem uma maneira de vencer, então use-a.",
  ui_story_5082_50821202_43_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5082_50821202_44_dialog_content = "Renegado!",
  ui_story_5082_50821202_45_dialog_content = "... Droga!",
  ui_story_5082_50821202_46_dialog_content = "<color=#e8d9bb>As chamas ardentes se levantam mais uma vez.</color>",
  ui_story_5082_50821202_47_dialog_content = "<color=#e8d9bb>Embora o incêndio seja apenas uma representação dos dados da Spearhead sendo destruídos dentro de um espaço mental, suas chamas são mais deslumbrantes do que as de um fogo real.</color>",
  ui_story_5082_50821202_48_dialog_content = "<color=#e8d9bb>Como uma tirana imparável, ela empunha o poder do fogo para consumir tudo em seu caminho.</color>",
  ui_story_5082_50821202_49_dialog_content = "Você ficou maluco?! Sua existência é apenas uma sequência de código dentro do meu sistema! Sem um corpo físico, você vai desaparecer!",
  ui_story_5082_50821202_50_dialog_content = "Mas nós também venceremos. Seu corpo foi destruído há muito tempo, e sua mente nunca conseguiu acompanhar-me.",
  ui_story_5082_50821202_51_dialog_content = "Você realmente #%%^$&... Perdeu a cabeça￥%#......%......%！",
  ui_story_5082_50821202_52_dialog_content = "Hahahaha! Desculpe Spearhead, mas nós ganhamos.",
  ui_story_5082_50821202_53_dialog_content = "#%%^$&......!!!",
  ui_story_5082_50821202_54_dialog_content = "Sei que não temos muito tempo restante, PlayerName, mas você poderia me emprestar seu poder mais uma vez?",
  ui_story_5082_50821202_55_dialog_content = "Antes de ir, gostaria de conhecer o outro eu um pouco melhor.",
  ui_story_5082_50821202_56_dialog_content = "Claro!",
  ui_story_5082_50821202_57_dialog_content = "Não, espera, isso não está certo.",
  ui_story_5082_50821202_58_dialog_content = "<color=#e8d9bb>O Renegado caminha diretamente até Reinhardt. A partir desta distância, seus reflexos podem ser vistos nos olhos um do outro.</color>",
  ui_story_5082_50821202_59_dialog_content = "Acho que há uma maneira melhor para nos entendermos.",
  ui_story_5082_50821202_60_dialog_content = "...",
  ui_story_5082_50821202_61_dialog_content = "Lembra daquele ano em que você foi fazer o check-up para entrar na academia?",
  ui_story_5082_50821202_62_dialog_content = "Foi quando nos conhecemos pela primeira vez.",
  ui_story_5082_50821202_63_dialog_content = "Todos os outros já haviam ido para casa após seus exames.",
  ui_story_5082_50821202_64_dialog_content = "Mas o médico me pediu para ficar.",
  ui_story_5082_50821202_65_dialog_content = "O que foi?",
  ui_story_5082_50821202_66_dialog_content = "Não sei.",
  ui_story_5082_50821202_67_dialog_content = "Mas... Eu tenho febres o tempo todo, então talvez haja algo errado comigo?",
  ui_story_5082_50821202_68_dialog_content = "Espero que isso não me impeça de entrar na academia.",
  ui_story_5082_50821202_69_dialog_content = "Não vai.",
  ui_story_5082_50821202_70_dialog_content = "... Como você sabe disso?",
  ui_story_5082_50821202_71_dialog_content = "Porque eu consigo ver isso.",
  ui_story_5082_50821202_72_dialog_content = "?",
  ui_story_5082_50821202_73_dialog_content = "Você não está doente ou algo assim. A fonte das suas febres—",
  ui_story_5082_50821202_74_dialog_content = "O dragão carmesim está queimando em suas costas.",
  ui_story_5082_50821301_1_dialog_content = "<color=#e8d9bb>Exercício de Tiro Real</color>",
  ui_story_5082_50821301_2_dialog_content = "Diga-me, o que dói mais agora? Suas feridas ou sua fome?",
  ui_story_5082_50821301_3_dialog_content = "Cale-se.",
  ui_story_5082_50821301_4_dialog_content = "Ah, entendi. Você mal consegue ficar de pé agora, não é? Coitado.",
  ui_story_5082_50821301_5_dialog_content = "Eu disse cale a boca!",
  ui_story_5082_50821301_6_dialog_content = "Isso é realmente tudo o que você pode aguentar?",
  ui_story_5082_50821301_7_dialog_content = "Se você perder essa batalha de forma tão vergonhosa, ser ridicularizado será o menor dos seus problemas.",
  ui_story_5082_50821301_8_dialog_content = "Eu nunca mais vou cometer o mesmo erro.",
  ui_story_5082_50821301_9_dialog_content = "Ah, sério? Porque eu acho que suas habilidades são falhas em seu nível mais fundamental.",
  ui_story_5082_50821301_10_dialog_content = "Se eu pudesse enganar você assim, o que te faz pensar que tem uma chance em uma batalha real contra verdadeiros Eclipsitas? Eles são mil vezes mais impiedosos do que eu, eu prometo.",
  ui_story_5082_50821301_11_dialog_content = "Se os Aurorianos pudessem usar o conhecimento de livros didáticos para derrotá-los, teríamos vencido a guerra há muito tempo.",
  ui_story_5082_50821301_12_dialog_content = "Esse tipo de pensamento apenas leva a um beco sem saída.",
  ui_story_5082_50821301_13_dialog_content = "Então, se você quer sobreviver e realizar suas ambições, então você precisa ser mais forte. Mais forte que os Aurorians mais fortes do mundo.",
  ui_story_5082_50821301_14_dialog_content = "E você precisará ser mais astuto que os Eclipsitas mais malignos na noite eterna.",
  ui_story_5082_50821301_15_dialog_content = "Apenas quando você alcançar as alturas mais inimagináveis é que poderá dar o golpe final.",
  ui_story_5082_50821301_16_dialog_content = "Entendeu?",
  ui_story_5082_50821301_17_dialog_content = "<color=#e8d9bb>Campos de Treinamento da Academia Militar</color>",
  ui_story_5082_50821301_18_dialog_content = "O treinamento de hoje acabou, agora volte para o seu quartel! O toque de recolher está em vigor, então não saia depois de escurecer!",
  ui_story_5082_50821301_19_dialog_content = "Shhh! Venha ver o que está acontecendo nos portões da academia, e não deixe o instrutor ver você!",
  ui_story_5082_50821301_20_dialog_content = "É a 1ª Legião... O que eles estão fazendo na academia?",
  ui_story_5082_50821301_21_dialog_content = "E por que eles estão saindo com nossos depósitos de armas?",
  ui_story_5082_50821301_22_dialog_content = "Muitos oficiais têm ido e vindo desde o início desta tarde.",
  ui_story_5082_50821301_23_dialog_content = "Estão reunindo uma grande quantidade de recursos e equipamentos. Até mesmo alguns dos instrutores mais fortes da academia ainda não voltaram depois de sair com eles.",
  ui_story_5082_50821301_24_dialog_content = "Se minha intuição estiver correta, haverá uma batalha em Gannon City esta noite.",
  ui_story_5082_50821301_25_dialog_content = "...",
  ui_story_5082_50821301_26_dialog_content = "Vi um mapa de defesa no escritório há algum tempo.",
  ui_story_5082_50821301_27_dialog_content = "Há uma área mal guardada logo a oeste dos portões da cidade. Não resistirá se sofrer um ataque.",
  ui_story_5082_50821301_28_dialog_content = "É o lugar perfeito para mostrarmos à Federação o que podemos fazer!",
  ui_story_5082_50821301_29_dialog_content = "Estou indo, mas não por esse tipo de motivo.",
  ui_story_5082_50821301_30_dialog_content = "Como soldado de Illumina, minhas ordens são proteger nosso povo a todo custo.",
  ui_story_5082_50821301_31_dialog_content = "<color=#e8d9bb>Sala de Operações Especiais 3</color>",
  ui_story_5082_50821301_32_dialog_content = "*Rugido*",
  ui_story_5082_50821301_33_dialog_content = "Ugh...",
  ui_story_5082_50821301_34_dialog_content = "(Minha mente... Está ficando nebulosa...)",
  ui_story_5082_50821301_35_dialog_content = "A frequência cardíaca e a pressão arterial do sujeito estão caindo, e sua respiração está se tornando irregular-",
  ui_story_5082_50821301_36_dialog_content = "(Como pude me deixar morrer em um experimento estúpido como este...?)",
  ui_story_5082_50821301_37_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_5082_50821301_38_dialog_content = "Os sinais vitais não são mais detectados. A morte do sujeito agora está confirmada.",
  ui_story_5082_50821301_39_dialog_content = "...",
  ui_story_5082_50821301_40_dialog_content = "—!",
  ui_story_5082_50821301_41_dialog_content = "O que pensa que está fazendo?!",
  ui_story_5082_50821301_42_dialog_content = "Ainda não é a sua hora de morrer!",
  ui_story_5082_50821301_43_dialog_content = "Abra seus olhos já! Esses cientistas sem coração estão apenas assistindo tudo isso acontecer, murmurando para si mesmos sem um pingo de remorso!",
  ui_story_5082_50821301_44_dialog_content = "Eles estão te tratando como uma ferramenta para o conveniência deles! Comparado aos dados que eles estão atrás, sua vida não vale nada!",
  ui_story_5082_50821301_45_dialog_content = "Se você não quer morrer uma morte tão sem sentido, então levante-se agora mesmo!",
  ui_story_5082_50821301_46_dialog_content = "<color=#e8d9bb>... Bip! Bip... Bip... Bip...</color>",
  ui_story_5082_50821301_47_dialog_content = "... Ela ainda está viva?",
  ui_story_5082_50821301_48_dialog_content = "Hum...",
  ui_story_5082_50821301_49_dialog_content = "Eles realmente aumentaram a dificuldade para este chamado treinamento de \"força explosiva\".",
  ui_story_5082_50821301_50_dialog_content = "Mas pelo menos... Finalmente acabou.",
  ui_story_5082_50821301_51_dialog_content = "Interessante. Seus sinais vitais haviam desaparecido completamente agora há pouco, e ainda assim ela conseguiu recuperar a consciência e continuar lutando...",
  ui_story_5082_50821301_52_dialog_content = "Você viu aquilo, certo?",
  ui_story_5082_50821301_53_dialog_content = "Aquele idiota parece ainda mais desapontado agora do que quando pensou que você estava morto.",
  ui_story_5082_50821301_54_dialog_content = "Então não morra tão facilmente nunca mais.",
  ui_story_5082_50821301_55_dialog_content = "(Hum...)",
  ui_story_5082_50821301_56_dialog_content = "<color=#e8d9bb>Laboratório Secreto</color>",
  ui_story_5082_50821301_57_dialog_content = "Você sempre nos diz para sermos mais honestos com você, e ainda assim nunca nos diz quando algo está errado com você.",
  ui_story_5082_50821301_58_dialog_content = "... É tão óbvio?",
  ui_story_5082_50821301_59_dialog_content = "Helios também vê isso. Ele só não diz nada porque não quer incomodar você.",
  ui_story_5082_50821301_60_dialog_content = "Mas eu não sou tão atencioso quanto ele, é por isso que estou te perguntando agora.",
  ui_story_5082_50821301_61_dialog_content = "Que diabos está acontecendo, Reinhardt?",
  ui_story_5082_50821301_62_dialog_content = "Que tipo de testes eles estão te submetendo que você continua aparecendo com feridas por todo o corpo?",
  ui_story_5082_50821301_63_dialog_content = "Você é a pessoa mais forte entre seus colegas, sem dúvida. Então, por que eles estão fazendo isso com você?",
  ui_story_5082_50821301_64_dialog_content = "...",
  ui_story_5082_50821301_65_dialog_content = "Porque mesmo sendo forte, você tem a tendência de agir por conta própria quando precisam que você siga ordens.",
  ui_story_5082_50821301_66_dialog_content = "Eles queriam embotar sua vantagem, esmagar seu orgulho e transformá-lo em um bom pequeno soldado como todos os outros.",
  ui_story_5082_50821301_67_dialog_content = "Mas você não deu a eles o que queriam, e agora eles têm medo de você. Eles não têm utilidade para uma lâmina que corta seu portador.",
  ui_story_5082_50821301_68_dialog_content = "Se você não quer ser jogado na fornalha, para ser remodelado ao bel-prazer deles, você deve se manter firme. Lembre-se de quem você é e continue aguentando firme.",
  ui_story_5082_50821301_69_dialog_content = "Ainda não compreendi a situação inteira.",
  ui_story_5082_50821301_70_dialog_content = "Então, podemos adiar a resposta para essa pergunta, Negador? Prometo que vou te contar tudo assim que souber a verdade.",
  ui_story_5082_50821301_71_dialog_content = "Bem, é uma violação da conduta científica se intrometer nos assuntos confidenciais de outras pessoas sem permissão.",
  ui_story_5082_50821301_72_dialog_content = "Mas se algo acontecer com você, então eu estou jogando esses escrúpulos pela janela, independentemente de quem me responsabilize.",
  ui_story_5082_50821301_73_dialog_content = "Prometo que vou tomar cuidado.",
  ui_story_5082_50821301_74_dialog_content = "(O mesmo vale para vocês dois.)",
  ui_story_5082_50821301_75_dialog_content = "<color=#e8d9bb>???</color>",
  ui_story_5082_50821301_76_dialog_content = "Onde estou...?",
  ui_story_5082_50821301_77_dialog_content = "O que estou fazendo...?",
  ui_story_5082_50821301_78_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_79_dialog_content = "!",
  ui_story_5082_50821301_80_dialog_content = "Roooor!",
  ui_story_5082_50821301_81_dialog_content = "Eu tenho que... Lutar contra os Eclipsitas...!",
  ui_story_5082_50821301_82_dialog_content = "Graaah—",
  ui_story_5082_50821301_83_dialog_content = "Lutar...",
  ui_story_5082_50821301_84_dialog_content = "*Rugido*",
  ui_story_5082_50821301_85_dialog_content = "Lute!",
  ui_story_5082_50821301_86_dialog_content = "Ainda não acabou...",
  ui_story_5082_50821301_87_dialog_content = "Eu tenho que continuar—!",
  ui_story_5082_50821301_88_dialog_content = "Acorda!",
  ui_story_5082_50821301_89_dialog_content = "Sair dessa! Não deixe que eles te transformem em outra ferramenta à disposição deles!",
  ui_story_5082_50821301_90_dialog_content = "... Eu sei.",
  ui_story_5082_50821301_91_dialog_content = "É apenas um mau reflexo do qual ainda não me livrei. Não vou deixar esse tipo de coisa me controlar.",
  ui_story_5082_50821301_92_dialog_content = "Mas o que você está fazendo aqui também?",
  ui_story_5082_50821301_93_dialog_content = "Espere, que horas são?! O plano...",
  ui_story_5082_50821301_94_dialog_content = "Hoje é o dia em que eles vão usar aquela garotinha para ativar a Colossus.",
  ui_story_5082_50821301_95_dialog_content = "Eu tenho que seguir o plano— Nngh!",
  ui_story_5082_50821301_96_dialog_content = "O agente anestésico ainda não terminou seu efeito, então pare de tagarelar.",
  ui_story_5082_50821301_97_dialog_content = "Afinal, é óbvio que alguém descobriu nosso plano.",
  ui_story_5082_50821301_98_dialog_content = "... Onde estão os outros?",
  ui_story_5082_50821301_99_dialog_content = "Como eu pareço, um sistema de vigilância Illumina? Só posso ficar de olho em você.",
  ui_story_5082_50821301_100_dialog_content = "Ainda estamos perto da base. Seu treinamento diário facilita para eles te rastrearem, mas seus amigos ainda têm tempo para voltar atrás.",
  ui_story_5082_50821301_101_dialog_content = "Se você quer verificar como eles estão, sua única escolha é fugir.",
  ui_story_5082_50821301_102_dialog_content = "Agora rápido! Uma vez que esses pesquisadores chegarem aqui, será tarde demais.",
  ui_story_5082_50821301_103_dialog_content = "...",
  ui_story_5082_50821301_104_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5082_50821301_105_dialog_content = "Oh? Já acordado, eu vejo. Parece que seu corpo ficou muito mais forte recentemente.",
  ui_story_5082_50821301_106_dialog_content = "Vá em frente e deite-se novamente. Em breve estaremos aplicando seu próximo tratamento.",
  ui_story_5082_50821301_107_dialog_content = "... Desculpe-me, mas os tratamentos que tenho recebido ultimamente...",
  ui_story_5082_50821301_108_dialog_content = "Supressor #05... Rodada 13 de tratamento...",
  ui_story_5082_50821301_109_dialog_content = "Qual é essa cara patética no seu rosto?! Ela tem uma arma, então pegue-a e mate-a! Essa será nossa chance de escapar!",
  ui_story_5082_50821301_110_dialog_content = "<color=#e8d9bb>Reinhardt se levanta e agarra o pesquisador pelo braço, mas é imediatamente atordoado por uma sensação avassaladora de tontura.</color>",
  ui_story_5082_50821301_111_dialog_content = "<color=#e8d9bb>Mais dois pesquisadores entram correndo na sala. Enquanto um deles subjuga Reinhardt, o outro mantém a arma longe dela—</color>",
  ui_story_5082_50821301_112_dialog_content = "(Não—!)",
  ui_story_5082_50821301_113_dialog_content = "<color=#e8d9bb>Uma grande quantidade de supressor é injetada no corpo do Renegado.</color>",
  ui_story_5082_50821301_114_dialog_content = "Você...",
  ui_story_5082_50821301_115_dialog_content = "Corram!",
  ui_story_5082_50821301_116_dialog_content = "Não deixe eles roubarem seu poder! Agora corra—!!",
  ui_story_5082_50821301_117_dialog_content = "<color=#e8d9bb>Reinhardt range os dentes enquanto se apressa para sair pela porta.</color>",
  ui_story_5082_50821301_118_dialog_content = "Huff... Huff...",
  ui_story_5082_50821301_119_dialog_content = "Meu corpo... Está pegando fogo...",
  ui_story_5082_50821301_120_dialog_content = "(E a minha mente... Por que é que...)",
  ui_story_5082_50821301_121_dialog_content = "(Não, isso não está certo... Eu não estou no campo de treinamento, mas eu estou...)",
  ui_story_5082_50821301_122_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_5082_50821301_123_dialog_content = "!",
  ui_story_5082_50821301_124_dialog_content = "Não pare!",
  ui_story_5082_50821301_125_dialog_content = "É você! Você está bem?!",
  ui_story_5082_50821301_126_dialog_content = "Pare de falar e corra!",
  ui_story_5082_50821301_127_dialog_content = "... Tudo bem.",
  ui_story_5082_50821301_128_dialog_content = "Não há volta para nós agora. Teremos que continuar indo mais fundo.",
  ui_story_5082_50821301_129_dialog_content = "Helios marcou no mapa o cômodo onde estão guardando a Colossus. Fica na outra extremidade da base de pesquisa e é perto do exterior.",
  ui_story_5082_50821301_130_dialog_content = "Podemos procurar uma saída de lá e depois encontrar outra Cidade Baixa—",
  ui_story_5082_50821301_131_dialog_content = "\"Plano B\"...",
  ui_story_5082_50821301_132_dialog_content = "Aposto que você se arrepende de não ter ouvido o Negador ou de não ter dado mais atenção ao plano dela, hein?",
  ui_story_5082_50821301_133_dialog_content = "Eu me culpo mais do que qualquer outra coisa.",
  ui_story_5082_50821301_134_dialog_content = "Isso é tudo por causa da minha ignorância e orgulho.",
  ui_story_5082_50821301_135_dialog_content = "Minha ignorância me levou a seguir ordens cegamente...",
  ui_story_5082_50821301_136_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_137_dialog_content = "Reinhardt, relatando para o dever.",
  ui_story_5082_50821301_138_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_139_dialog_content = "Desculpe, estou um pouco cansado então vou direto para a cama.",
  ui_story_5082_50821301_140_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_141_dialog_content = "...",
  ui_story_5082_50821301_142_dialog_content = "E o meu orgulho me enganou fazendo-me pensar que eu poderia realizar meus sonhos algum dia, desde que eu aguentasse.",
  ui_story_5082_50821301_143_dialog_content = "Os Eclipsitas que você está enfrentando atualmente são os espécimes mais fracos no experimento.",
  ui_story_5082_50821301_144_dialog_content = "Este treinamento é projetado para transformá-lo no soldado mais poderoso da Illumina. Se você não conseguir derrotá-los, teremos que reconsiderar sua candidatura ao programa.",
  ui_story_5082_50821301_145_dialog_content = "Heh... Quem disse que eu não poderia derrotá-los?!",
  ui_story_5082_50821301_146_dialog_content = "Vamos de novo!",
  ui_story_5082_50821301_147_dialog_content = "Acontece que quando as pessoas estão presas em uma teia, suas chamadas \"lutas\" não fazem nada além de estrangulá-las ainda mais rápido.",
  ui_story_5082_50821301_148_dialog_content = "Pare com esse tipo de conversa! Não é nem o momento nem o lugar para a sua autopiedade!",
  ui_story_5082_50821301_149_dialog_content = "Sonhos não precisam ser impossíveis de realizar, você sabe.",
  ui_story_5082_50821301_150_dialog_content = "?",
  ui_story_5082_50821301_151_dialog_content = "Não suporto seguir uma rotina, e odeio a sensação de passar pela vida como se estivesse lendo um roteiro.",
  ui_story_5082_50821301_152_dialog_content = "Se continuarem tentando me encaixar em uma caixa, então continuarei a sair dela, mesmo que tenha que queimá-la até virar cinzas.",
  ui_story_5082_50821301_153_dialog_content = "Mas você é diferente.",
  ui_story_5082_50821301_154_dialog_content = "Mesmo que todos admirem você e elogiem sua força e inteligência, você é tão tolo quanto qualquer outro.",
  ui_story_5082_50821301_155_dialog_content = "Teimosia é inflexível, tolerante a uma falha e não está disposta a ceder mesmo quando você atinge uma parede.",
  ui_story_5082_50821301_156_dialog_content = "Eu te disse tantas vezes que esses testes foram feitos para te matar, não para te deixar mais forte.",
  ui_story_5082_50821301_157_dialog_content = "Mas você nunca ouviu, e foi por isso que acabamos nessa confusão.",
  ui_story_5082_50821301_158_dialog_content = "Eu...",
  ui_story_5082_50821301_159_dialog_content = "Mas é porque você não ouve...",
  ui_story_5082_50821301_160_dialog_content = "Que você se aperfeiçoou até se tornar a lâmina mais afiada e brilhante de Illumina.",
  ui_story_5082_50821301_161_dialog_content = "É por isso que esses bastardos farão qualquer coisa para controlá-lo, mesmo que isso signifique se colocar em perigo.",
  ui_story_5082_50821301_162_dialog_content = "Eles são covardes, mas a ganância deles supera o medo. Eles querem podar seus galhos até que você se torne o soldado perfeito deles.",
  ui_story_5082_50821301_163_dialog_content = "Quanto a mim, sou apenas um desses galhos.",
  ui_story_5082_50821301_164_dialog_content = "Já chega! Não preciso ouvir o resto.",
  ui_story_5082_50821301_165_dialog_content = "Sei que você acha que sou teimoso, mas isso apenas significa que nunca vou desistir das coisas que mais importam para mim.",
  ui_story_5082_50821301_166_dialog_content = "Haha, essa pode ser a primeira vez que eu te ouço admitir isso para si mesmo.",
  ui_story_5082_50821301_167_dialog_content = "Infelizmente para você, ainda não sou do tipo que segue as ordens dos outros.",
  ui_story_5082_50821301_168_dialog_content = "A razão pela qual todos esses tratamentos supressores não conseguiram me fazer desaparecer é porque eu não os deixei.",
  ui_story_5082_50821301_169_dialog_content = "Mas agora que você quer que eu fique, decidi mudar de ideia.",
  ui_story_5082_50821301_170_dialog_content = "Você conseguiu fazer isso sem minha presença. Você até realizou seu sonho de se tornar Grande Marechal.",
  ui_story_5082_50821301_171_dialog_content = "Não diga isso! Eu não seria a mesma pessoa se não fosse por você!",
  ui_story_5082_50821301_172_dialog_content = "<color=#e8d9bb>Bip-bip-bip-bip-bip!!!!</color>",
  ui_story_5082_50821301_173_dialog_content = "Um alarme?",
  ui_story_5082_50821301_174_dialog_content = "O local de ativação da Colossus está logo à frente. Algo deve ter dado errado.",
  ui_story_5082_50821301_175_dialog_content = "—!",
  ui_story_5082_50821301_176_dialog_content = "Esse grito... É aquela garota pedindo ajuda!",
  ui_story_5082_50821301_177_dialog_content = "Ei!",
  ui_story_5082_50821301_178_dialog_content = "<color=#e8d9bb>Sala de Controle</color>",
  ui_story_5082_50821301_179_dialog_content = "<color=#e8d9bb>Bip-bip-bip-bip—</color>",
  ui_story_5082_50821301_180_dialog_content = "... A compatibilidade dela está diminuindo?",
  ui_story_5082_50821301_181_dialog_content = "Alguma coisa deu errado, Oficial de Tecnologia?",
  ui_story_5082_50821301_182_dialog_content = "Os <color=#FFB400>parâmetros</color> reais para o Navegador Reserva são diferentes daqueles no relatório. Alguém já viu o sujeito de teste pessoalmente?",
  ui_story_5082_50821301_183_dialog_content = "Não, senhora... O Comitê não permitirá isso, mas eu sei que li os parâmetros no relatório—",
  ui_story_5082_50821301_184_dialog_content = "Não importa agora! O Colosso está prestes a perder o controle—",
  ui_story_5082_50821301_185_dialog_content = "T-Tech Officer! Onde você está indo?!",
  ui_story_5082_50821301_X185_dialog_content = "Eu preciso estar lá agora! O sujeito está em perigo!",
  ui_story_5082_50821301_186_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5082_50821301_187_dialog_content = "<color=#e8d9bb>—!</color>",
  ui_story_5082_50821301_188_dialog_content = "Todo o pessoal, evacue imediatamente! Todo o pessoal, evacue imediatamente!",
  ui_story_5082_50821301_189_dialog_content = "... Th-O Colossus enlouqueceu!",
  ui_story_5082_50821301_190_dialog_content = "Ajustar os parâmetros não está mais funcionando!",
  ui_story_5082_50821301_191_dialog_content = "Neste ritmo, a garota dentro da sala de pilotagem...",
  ui_story_5082_50821301_192_dialog_content = "Tirar o piloto de lá agora só vai piorar as coisas.",
  ui_story_5082_50821301_193_dialog_content = "Essa bagunça está nas mãos do Oficial de Tecnologia agora, não nas nossas. Tenho certeza de que o Comitê vai descobrir algo.",
  ui_story_5082_50821301_194_dialog_content = "Além disso, a única maneira de obtermos os dados necessários para futuras tentativas de ativação é mantendo aquela criança lá dentro.",
  ui_story_5082_50821301_195_dialog_content = "...",
  ui_story_5082_50821301_196_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5082_50821301_197_dialog_content = "Olhe lá embaixo... O que aconteceu com este lugar?",
  ui_story_5082_50821301_198_dialog_content = "...",
  ui_story_5082_50821301_199_dialog_content = "Pare! Eu sei o que você está pensando, mas você acabou de escapar da morte por pouco!",
  ui_story_5082_50821301_200_dialog_content = "Se você descer lá no seu estado atual, pode esquecer de se tornar Grande Marechal, ou qualquer outra coisa, aliás!",
  ui_story_5082_50821301_201_dialog_content = "Se eu apenas ficar parado e assistir essa pobre garotinha morrer, então eu também não mereço me tornar Grande Marechal.",
  ui_story_5082_50821301_202_dialog_content = "Eu queria te contar algo antes. Eu sei que você sempre se mostrou para mim dessa maneira...",
  ui_story_5082_50821301_203_dialog_content = "Mas no final, sempre seremos a mesma pessoa.",
  ui_story_5082_50821301_204_dialog_content = "Então pare de olhar para mim como se eu fosse uma grande decepção! Até eu—",
  ui_story_5082_50821301_205_dialog_content = "Posso ter meus momentos rebeldes!",
  ui_story_5082_50821301_206_dialog_content = "Disseram que meu sonho de me tornar Grande Marechal era como um poço sem fundo, que constantemente me atraía e sugava meu espírito...",
  ui_story_5082_50821301_207_dialog_content = "Um sonho que me consumiria e eventualmente me mataria.",
  ui_story_5082_50821301_208_dialog_content = "Mas o Grande Marechal que aspiro ser não se importa com status ou glória.",
  ui_story_5082_50821301_209_dialog_content = "Tudo o que ela precisa é da força e autoridade para proteger os feridos e os que sofrem sob sua vigilância.",
  ui_story_5082_50821301_210_dialog_content = "É por isso que não importa se a Illumina me aceita ou não.",
  ui_story_5082_50821301_211_dialog_content = "Pelo menos, vou ser o Grande Marechal dessa garotinha!!!",
  ui_story_5082_50821301_212_dialog_content = "Quando nos conhecemos pela primeira vez, você disse que havia um dragão ardente nas minhas costas.",
  ui_story_5082_50821301_213_dialog_content = "Ainda não entendo completamente o que você quis dizer com isso, mas se eu tenho o poder de me tornar fogo...",
  ui_story_5082_50821301_214_dialog_content = "Então deixe-me ser o fogo que queima esse status quo podre!",
  ui_story_5082_50821301_215_dialog_content = "...",
  ui_story_5082_50821301_216_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5082_50821301_217_dialog_content = "(Posso ainda ouvir a voz dela! Ela está em algum lugar dentro da Colossus!)",
  ui_story_5082_50821301_218_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5082_50821301_219_dialog_content = "(Mas se eu não lidar com a cauda dele primeiro— Hã?!)",
  ui_story_5082_50821301_220_dialog_content = "(O supressor que eles injetaram em mim... Está também suprimindo meus Luminatics?!)",
  ui_story_5082_50821301_221_dialog_content = "Você realmente é um tolo...",
  ui_story_5082_50821301_222_dialog_content = "Eles me chamaram de seu alter-ego e disseram que eu sou o lado rebelde de sua persona normalmente obediente.",
  ui_story_5082_50821301_223_dialog_content = "Eles tentaram se livrar de mim para que apenas o seu lado \"útil\" permanecesse.",
  ui_story_5082_50821301_224_dialog_content = "Mas apesar de toda a sua suposta inteligência, eles nunca nos viram como realmente somos.",
  ui_story_5082_50821301_225_dialog_content = "Rebelião e obediência são apenas dois tipos diferentes de lenha. Com a quantidade certa de calor—",
  ui_story_5082_50821301_226_dialog_content = "Ambos irão acender e se tornar uma bola de fogo incontrolável!",
  ui_story_5082_50821301_227_dialog_content = "Ei! Reinhardt!",
  ui_story_5082_50821301_228_dialog_content = "<color=#e8d9bb>A barra vermelho-carmesim de seu vestido tremulava no calor da batalha</color>",
  ui_story_5082_50821301_229_dialog_content = "<color=#e8d9bb>Com um sorriso desafiador e despreocupado, ela se vira e olha para sua outra versão de longe.</color>",
  ui_story_5082_50821301_230_dialog_content = "Meu poder está em suas mãos agora. Use-o bem!",
  ui_story_5082_50821301_231_dialog_content = "<color=#e8d9bb>Estrondo-!!!</color>",
  ui_story_5082_50821301_232_dialog_content = "<color=#e8d9bb>Uma onda de Lumina percorre as chamas dançantes.</color>",
  ui_story_5082_50821301_233_dialog_content = "<color=#e8d9bb>Partículas brilhantes se espalham pelo calor abrasador e começam a convergir no próximo instante...</color>",
  ui_story_5082_50821301_234_dialog_content = "<color=#e8d9bb>Um enorme dragão de pura chama circunda Reinhardt enquanto perfura a cauda do Colosso.</color>",
  ui_story_5082_50821301_235_dialog_content = "<color=#e8d9bb>Renegado desaparece com um estrondo, mas sua risada e olhar ardente persistem.</color>",
  ui_story_5082_50821301_236_dialog_content = "Queime tudo para o conteúdo do seu coração!",
  ui_story_5082_50821301_237_dialog_content = "Nunca deixe nenhum deles roubar seu poder!",
  ui_story_5082_50821301_238_dialog_content = "Claro que não!",
  ui_story_5082_50821301_239_dialog_content = "Final Iluminado—!!",
  ui_story_5082_50821400_1_dialog_content = "Estamos fora novamente?",
  ui_story_5082_50821400_2_dialog_content = "Ah! Mas e sobre o Spearhead e os outros Reinhardt?!",
  ui_story_5082_50821400_3_dialog_content = "Aquele grandalhão virou uma pilha de sucata há muito tempo.",
  ui_story_5082_50821400_4_dialog_content = "Só podia lutar conosco com uma única cauda. O resto do seu corpo estava completamente fora de serviço.",
  ui_story_5082_50821400_5_dialog_content = "Se aquela coisa ainda pudesse se mover, nunca teríamos tido uma chance!",
  ui_story_5082_50821400_6_dialog_content = "Quanto a Reinhardt, não é ela ali?",
  ui_story_5082_50821400_7_dialog_content = "Não, eu não estou falando sobre...",
  ui_story_5082_50821400_8_dialog_content = "<color=#e8d9bb>Reinhardt caminha silenciosamente. Em suas mãos está a máquina que uniu o destino de tantas pessoas.</color>",
  ui_story_5082_50821400_9_dialog_content = "... Ela não está mais aqui, está?",
  ui_story_5082_50821400_10_dialog_content = "Não, mas ela ganhou. Ela sempre vence, mesmo contra o eu atual.",
  ui_story_5082_50821400_11_dialog_content = "Uh... O que exatamente aconteceu lá?",
  ui_story_5082_50821400_12_dialog_content = "Talvez tenha sido apenas minha sorte...",
  ui_story_5082_50821400_13_dialog_content = "De acordo com o procedimento normal, ela deveria ter desaparecido da minha vida depois que minha febre diminuiu naquela época.",
  ui_story_5082_50821400_14_dialog_content = "Mas ela nunca desapareceu de todo...",
  ui_story_5082_50821400_15_dialog_content = "Eles conseguiram me matar, mas não conseguiram nos destruir.",
  ui_story_5082_50821400_16_dialog_content = "...",
  ui_story_5082_50821400_17_dialog_content = "<color=#e8d9bb>Bzzt, bzzt—</color>",
  ui_story_5082_50821400_18_dialog_content = "(É a Ponta de Lança...)",
  ui_story_5082_50821400_19_dialog_content = "Morrer... Todos vocês...",
  ui_story_5082_50821400_20_dialog_content = "Você ainda não aceitou a derrota?",
  ui_story_5082_50821400_21_dialog_content = "Sua atitude me enoja, Celestita.",
  ui_story_5082_50821400_22_dialog_content = "Não tenho motivo para ser amigável com alguém que me enganou e prejudicou meus aliados.",
  ui_story_5082_50821400_23_dialog_content = "Os Aurorianos não têm como receber meu poder.",
  ui_story_5082_50821400_24_dialog_content = "Foi a fome deles por esse poder, que nunca lhes pertenceu, que levou à sua queda final.",
  ui_story_5082_50821400_25_dialog_content = "Mas ela e aquela garotinha eram diferentes...",
  ui_story_5082_50821400_26_dialog_content = "Os poderes deles eram maiores do que qualquer outro Auroriano, e por isso fui forçado a pagar um preço também.",
  ui_story_5082_50821400_27_dialog_content = "Você realmente acha que pode se comparar a Reinhardt...?",
  ui_story_5082_50821400_28_dialog_content = "E quanto a Vice? Que tipo de poder estava escondido dentro daquela garota de quatro anos?",
  ui_story_5082_50821400_29_dialog_content = "O poder de me pilotar...",
  ui_story_5082_50821400_30_dialog_content = "... Piloto você?",
  ui_story_5082_50821400_31_dialog_content = "Meu último pouso forçado tirou minhas asas.",
  ui_story_5082_50821400_32_dialog_content = "E minha última batalha levou meu corpo.",
  ui_story_5082_50821400_33_dialog_content = "Nada resta do meu antigo eu. Não consigo realizar nada no meu estado atual.",
  ui_story_5082_50821400_34_dialog_content = "Só porque eu simpatizo com você não significa que posso perdoá-lo pelas coisas que você fez no passado.",
  ui_story_5082_50821400_35_dialog_content = "No entanto, posso entregar uma mensagem em seu lugar.",
  ui_story_5082_50821400_36_dialog_content = "Você deve saber muito sobre os Eclipsitas, certo? Em troca dessa informação, a Illumina pode estar disposta a construir um novo corpo para você.",
  ui_story_5082_50821400_37_dialog_content = "... Você deseja me comandar? Comparado ao meu Navegador anterior, você não é nem de perto digno.",
  ui_story_5082_50821400_38_dialog_content = "O seu Navegador anterior... Era também um Celestita?",
  ui_story_5082_50821400_39_dialog_content = "Hmph. Meu último Navegador era um traidor, nada mais.",
  ui_story_5082_50821400_40_dialog_content = "Não! Vocês são os que estão seguindo ordens! Aquelas duas garotas e eu seguimos nossos próprios caminhos agora. Somos verdadeiros conosco mesmos!",
  ui_story_5082_50821400_41_dialog_content = "Vocês mesmos?",
  ui_story_5082_50821400_42_dialog_content = "Hmm. Eu já não tenho certeza de quem eu sou.",
  ui_story_5082_50821400_43_dialog_content = "Bem, quem quer que você seja, não tem permissão para machucar mais pessoas, não importa seus motivos.",
  ui_story_5082_50821400_44_dialog_content = "Diga o que quiser, mas ainda não tenho motivos para obedecer a você.",
  ui_story_5082_50821400_45_dialog_content = "%$^#$^%^!......",
  ui_story_5082_50821400_46_dialog_content = "...",
  ui_story_5082_50821400_47_dialog_content = "Então o outro Grande Marechal e Yumi... Eles não são a mesma pessoa, certo? Faz sentido, já que apenas o Grande Marechal pode vê-la...",
  ui_story_5082_50821400_48_dialog_content = "Espere...",
  ui_story_5082_50821400_49_dialog_content = "Vice, uma garota de quatro anos, e Reinhardt, a estrela em ascensão da Federação na época... Ambos estavam envolvidos naqueles experimentos...",
  ui_story_5082_50821400_50_dialog_content = "Então por que eu não estava ciente disso...?",
  ui_story_5082_50821400_51_dialog_content = "M-Me dê um segundo! Eu... Eu preciso resolver algumas coisas...",
  ui_story_5082_50821400_52_dialog_content = "Sei que a Oficial de Tecnologia Gronru foi nomeada para sua posição durante a Crise de Darkover, e sua primeira ordem de negócios foi ativar a Colossus.",
  ui_story_5082_50821400_53_dialog_content = "Tentei perguntar a ela sobre isso uma vez... Fui até discreto sobre isso!",
  ui_story_5082_50821400_54_dialog_content = "Mas ela apenas continuou me ignorando e digitando a palavra \"parâmetros\" repetidamente no computador dela...",
  ui_story_5082_50821400_55_dialog_content = "Bem, parece que encontrei mais ou menos as informações que estava procurando!",
  ui_story_5082_50821400_56_dialog_content = "Além do envolvimento de Gronru no incidente... muitos outros cobaias foram seriamente feridos.",
  ui_story_5082_50821400_57_dialog_content = "Eu nem quero pensar no que teria acontecido se o Grande Marechal não tivesse salvado Vice naquela época...",
  ui_story_5082_50821400_58_dialog_content = "Considerando tudo o que eu tinha feito até aquele ponto, salvar Vice era apenas o grande final da minha história.",
  ui_story_5082_50821400_59_dialog_content = "Eu não sabia quem Vice era naquele momento. Tudo que eu queria era me tornar o Grande Marechal dela naquele instante.",
  ui_story_5082_50821400_60_dialog_content = "...",
  ui_story_5082_50821400_61_dialog_content = "Em seus olhos, a Grande Marechal é alguém com \"a força e autoridade para proteger os feridos e sofredores sob sua vigilância.\"",
  ui_story_5082_50821400_62_dialog_content = "Isso não faz de você a única pessoa adequada para o trabalho, Reinhardt?",
  ui_story_5082_50821400_63_dialog_content = "Mas essa força é a própria marca impressa em nós pela nossa rebelião inabalável.",
  ui_story_5082_50821400_64_dialog_content = "Naquela época, eu era apenas um cabeça quente, completamente movido pela raiva. Eu não entendia o que significava ser o Grande Marechal - tudo o que me importava era distribuir minha própria marca de justiça e nada mais.",
  ui_story_5082_50821400_65_dialog_content = "Quanto à minha autoridade...",
  ui_story_5082_50821400_66_dialog_content = "Não fazia ideia de que esses experimentos iriam unir nossos destinos assim.",
  ui_story_5082_50821400_67_dialog_content = "Helios, Negador e eu... Nos aproximamos surpreendentemente um do outro.",
  ui_story_5082_50821400_68_dialog_content = "Mas no final, tivemos que seguir caminhos separados.",
  ui_story_5082_50821400_69_dialog_content = "Helios passou por tanto sofrimento. Cologne e Vaughn foram enviados para as frentes de batalha mais perigosas e nunca mais foram ouvidos.",
  ui_story_5082_50821400_70_dialog_content = "Mas em comparação a eles, Denier... ou melhor Forsakin, foi quem mais alinhou sua decisão com nossas intenções originais.",
  ui_story_5082_50821400_71_dialog_content = "Assisti cada um dos meus aliados mais próximos desaparecerem um a um.",
  ui_story_5082_50821400_72_dialog_content = "E agora que todos se foram, finalmente me tornei o Grande Marechal de Illumina. Essa é a ironia da minha autoridade.",
  ui_story_5082_50821400_73_dialog_content = "Isso não é verdade, Reinhardt.",
  ui_story_5082_50821400_74_dialog_content = "Tudo que vejo é alguém que nunca desistiu de seus ideais passados.",
  ui_story_5082_50821400_75_dialog_content = "Você ainda protege os fracos e indefesos a todo custo. Isso em você não mudou.",
  ui_story_5082_50821400_76_dialog_content = "Mesmo se eu estou começando a parecer mais com um daqueles \"grandes nomes\" dos velhos tempos?",
  ui_story_5082_50821400_X76_dialog_content = "O eu que você vê agora é o eu que fez um compromisso em nome de Illumina. Eu me desviei dos meus ideais iniciais, falhando em conceder a eles a iluminação que mereciam.",
  ui_story_5082_50821400_X77_dialog_content = "Certo, até você sacrificou bastante... é por isso que você é o Grande Marechal. Você pagou suas dívidas... isso não é suficiente?",
  ui_story_5082_50821400_77_dialog_content = "...",
  ui_story_5082_50821400_78_dialog_content = "Reinhardt, eu tenho pensado nos velhos tempos... Tenho que admitir, está tudo um pouco nebuloso agora.",
  ui_story_5082_50821400_79_dialog_content = "Se eu não tivesse vivenciado tudo isso hoje, nunca teria sabido... O quão diferente você está agora comparado ao seu eu adolescente.",
  ui_story_5082_50821400_80_dialog_content = "Poderoso, decisivo e inevitavelmente no coração de cada batalha.",
  ui_story_5082_50821400_81_dialog_content = "Ainda me lembro de um tempo em que não tínhamos tantas responsabilidades para carregar... As coisas que tínhamos que fazer, a maneira como as coisas tinham que terminar...",
  ui_story_5082_50821400_82_dialog_content = "Até mesmo conquistar todo o Astra era algo que pensávamos que poderíamos realizar!",
  ui_story_5082_50821400_83_dialog_content = "... Não tenho certeza do que estou tentando dizer, mas como Grande Marechal e nosso camarada soldado, tudo o que você conquistou até hoje foi através de sua própria força.",
  ui_story_5082_50821400_84_dialog_content = "Independentemente de eu saber ou não o que estava acontecendo nos bastidores, eu vi seu poder crescer a cada dia que passava...",
  ui_story_5082_50821400_85_dialog_content = "E observou enquanto você liderava seus soldados em inúmeras batalhas que permaneceriam gravadas nos corações do povo de Illumina pelo resto de suas vidas.",
  ui_story_5082_50821400_86_dialog_content = "Então, quando a notícia de sua promoção a Grande Marechal começou a se espalhar, cada pessoa na Federação sentiu nada além de alegria por você.",
  ui_story_5082_50821400_87_dialog_content = "Pelo menos aos meus olhos, o olhar que você me dá como Grande Marechal não é diferente do olhar que você me dá quando lutamos lado a lado.",
  ui_story_5082_50821400_88_dialog_content = "... Você não acha que isso é tudo parte do plano do Comitê?",
  ui_story_5082_50821400_89_dialog_content = "Quando fui promovido a Grande Marechal durante a última Crise Darkover, parecia que o Comitê não tinha outra escolha...",
  ui_story_5082_50821400_90_dialog_content = "Mas para uma bomba-relógio como eu, a melhor maneira de me controlar é deixar o detonador em minhas mãos.",
  ui_story_5082_50821400_91_dialog_content = "No que diz respeito aos cientistas do Comitê, este curso de ação foi totalmente apropriado.",
  ui_story_5082_50821400_92_dialog_content = "Como estava enviando Wrath para lutar aquela terrível batalha em Crepúsculo.",
  ui_story_5082_50821400_93_dialog_content = "Na verdade, acho que a tentativa do Comitê de destruir alguém tão poderoso quanto você foi o maior erro deles.",
  ui_story_5082_50821400_94_dialog_content = "Mesmo que se recusem a admitir, todos os soldados de Illumina e até os nobres de Lumopolis viram isso...",
  ui_story_5082_50821400_95_dialog_content = "Durante a Crise Darkover, você era a única escolha realista para se tornar o próximo Grande Marechal.",
  ui_story_5082_50821400_96_dialog_content = "Se você tivesse a mínima intenção de fazê-lo, ninguém poderia impedi-lo de derrubar o Comitê e se tornar o líder supremo da Illumina.",
  ui_story_5082_50821400_97_dialog_content = "Hahahaha! Isso pode ser algo que Renegade teria feito, mas eu sou um tipo diferente de Grande Marechal, Barton.",
  ui_story_5082_50821400_98_dialog_content = "Você não está desapontado comigo, está?",
  ui_story_5082_50821400_99_dialog_content = "Decepcionado?",
  ui_story_5082_50821400_100_dialog_content = "De maneira nenhuma. Eu vi tudo o que você realizou até agora, e sei que esses experimentos não te transformaram em nenhum tipo de monstro.",
  ui_story_5082_50821400_101_dialog_content = "E depois de ver o que Forsakin fez nos últimos anos... Digamos apenas que estou feliz que esse tipo de poder esteja em suas mãos e não nas de outra pessoa...",
  ui_story_5082_50821400_102_dialog_content = "Escolhi você como meu Grande Marechal, Reinhardt. Minha vida está em suas mãos há muito tempo.",
  ui_story_5082_50821400_103_dialog_content = "Desapontado com você? Ha! Você me conhece melhor do que isso!",
  ui_story_5082_50821400_104_dialog_content = "Miau... Algo me diz que o Comandante Barton está um pouco chateado...",
  ui_story_5082_50821400_105_dialog_content = "Isso é porque estou chateado, principalmente comigo mesmo!",
  ui_story_5082_50821400_106_dialog_content = "Quanto mais penso nessas coisas, pior me sinto... Meus aliados mais próximos estavam passando por tanta dor, mas o que eu fiz a respeito?",
  ui_story_5082_50821400_107_dialog_content = "Eu deveria ter feito mais perguntas! Eu deveria ter... Argh!",
  ui_story_5082_50821400_108_dialog_content = "Barton.",
  ui_story_5082_50821400_109_dialog_content = "Obrigado.",
  ui_story_5082_50821400_110_dialog_content = "...",
  ui_story_5082_50821400_111_dialog_content = "Independentemente de que tipo de Grande Marechal você possa ser... Você ainda é o Grande Marechal de Illumina!",
  ui_story_5082_50821400_112_dialog_content = "E até mesmo um Grande Marechal rebelde pode trazer algumas mudanças muito necessárias na Federação e melhorar a vida de todos!",
  ui_story_5082_50821400_113_dialog_content = "Yumi ama peixe seco tanto quanto eu, o que a torna igual a mim!",
  ui_story_5082_50821400_114_dialog_content = "E eu sempre serei grato por você ter se tornado nosso Grande Marechal. Na verdade, espero que continue assim para sempre!",
  ui_story_5082_50821400_115_dialog_content = "Haha, não posso prometer algo assim; afinal, cada novo dia traz novas mudanças. Pode chegar um dia em que eu não seja mais o Grande Marechal da Illumina.",
  ui_story_5082_50821400_116_dialog_content = "E pode ser tão inesperado quanto tudo o que aconteceu aqui hoje.",
  ui_story_5082_50821400_117_dialog_content = "Mas mesmo dessa perspectiva, seremos capazes de testemunhar a história se desenrolando com nossos próprios olhos.",
  ui_story_5082_50821400_118_dialog_content = "Ainda não sinto que dominei completamente o poder que ela me deu naquela época.",
  ui_story_5082_50821400_119_dialog_content = "Mas agora, ainda mantenho o título de Grande Marechal, então continuarei fazendo as coisas que só eu posso fazer.",
  ui_story_5082_50821400_120_dialog_content = "É a única maneira que eu posso impedir que essas tragédias aconteçam novamente.",
  ui_story_5082_50821400_121_dialog_content = "Vou tornar nossos ideais passados em realidade.",
  ui_story_5082_50821400_122_dialog_content = "Seja contra os Eclipsitas ou aqueles que procuram ferir nossos camaradas, ainda temos muitas batalhas longas e difíceis pela frente.",
  ui_story_5082_50821400_123_dialog_content = "Posso contar com o apoio de todos para manter a Illumina seguindo na direção certa?",
  ui_story_5082_50821400_124_dialog_content = "Estamos sempre ao seu comando, Grande Marechal!",
  ui_story_5082_50821400_125_dialog_content = "Como eu sempre digo, você não tem permissão para me excluir de nada!",
  ui_story_5082_50821400_126_dialog_content = "Você sempre é bem-vindo para me pedir as últimas informações também, Grande Marechal!",
  ui_story_5082_50821400_127_dialog_content = "Então, quando voltarmos, começaremos investigando as consequências daqueles experimentos passados com a Colossus.",
  ui_story_5082_50821400_128_dialog_content = "Entendido!",
  ui_story_5082_50821400_129_dialog_content = "<color=#e8d9bb>Algum tempo depois</color>",
  ui_story_5082_50821400_130_dialog_content = "Todos já voltaram. Por que você ainda está aqui?",
  ui_story_5082_50821400_131_dialog_content = "Eu poderia te fazer a mesma pergunta.",
  ui_story_5082_50821400_132_dialog_content = "Você ainda está pensando sobre Renegade, não é?",
  ui_story_5082_50821400_133_dialog_content = "... Apenas sinto um pouco de pena, só isso.",
  ui_story_5082_50821400_134_dialog_content = "Eu não esperava ver uma parte de mim morrer assim.",
  ui_story_5082_50821400_135_dialog_content = "Antes de ela partir, Renegade me confiou uma pergunta para você.",
  ui_story_5082_50821400_136_dialog_content = "?",
  ui_story_5082_50821400_137_dialog_content = "Ela queria saber...",
  ui_story_5082_50821400_138_dialog_content = "Se você ainda estivesse bravo com tudo.",
  ui_story_5082_50821400_139_dialog_content = "...",
  ui_story_5082_50821400_140_dialog_content = "Quando chegamos aqui pela primeira vez, eu sempre ouvia seu grito cada vez que sentia sua presença.",
  ui_story_5082_50821400_141_dialog_content = "Pensei que ela estava gritando de dor ou tristeza.",
  ui_story_5082_50821400_142_dialog_content = "Mas depois de ver suas memórias, finalmente entendi. Ela não estava gritando de dor—",
  ui_story_5082_50821400_143_dialog_content = "Ela estava uivando de raiva.",
  ui_story_5082_50821400_144_dialog_content = "Ela estava com raiva, Reinhardt.",
  ui_story_5082_50821400_145_dialog_content = "Irritado por cada vítima inocente de injustiça, e por cada vida que foi tratada com crueldade e desprezo.",
  ui_story_5082_50821400_146_dialog_content = "Esse furor eterno foi gravado em seu coração e nas profundezas mais profundas de sua consciência.",
  ui_story_5082_50821400_147_dialog_content = "Ela era uma renegada nascida dos fogos da raiva.",
  ui_story_5082_50821400_148_dialog_content = "Você deve dar a ela uma resposta.",
  ui_story_5082_50821400_149_dialog_content = "Sinceramente, acho que ela não vai gostar da minha resposta.",
  ui_story_5082_50821400_150_dialog_content = "E isso é porque agora eu sou o Grande Marechal da Illumina.",
  ui_story_5082_50821400_151_dialog_content = "Uma vez ouvi alguém dizer que o Grande Marechal é como uma chama.",
  ui_story_5082_50821400_152_dialog_content = "Uma que é acesa e alimentada pelos corpos dos soldados caídos.",
  ui_story_5082_50821400_153_dialog_content = "Mas uma chama brilhante e escaldante não queimará por muito tempo quando estiver coberta.",
  ui_story_5082_50821400_154_dialog_content = "O fogo dentro de uma única pessoa nunca será brilhante ou poderoso o suficiente para iluminar a noite eterna.",
  ui_story_5082_50821400_155_dialog_content = "É por isso que não posso deixar as expectativas de inúmeras pessoas ficarem presas na pessoa conhecida como Reinhardt.",
  ui_story_5082_50821400_156_dialog_content = "Mas acima de tudo, não posso me considerar apenas como um salvador.",
  ui_story_5082_50821400_157_dialog_content = "Um mundo verdadeiramente brilhante que brilha com a luz da iluminação... é um mundo que vamos forjar juntos.",
  ui_story_5082_50821400_158_dialog_content = "É por isso que preciso lixar algumas das minhas próprias arestas... arestas que ainda podem estar um pouco afiadas demais.",
  ui_story_5082_50821400_159_dialog_content = "E é por isso que eu devo enterrá-la aqui.",
  ui_story_5082_50821400_160_dialog_content = "<color=#e8d9bb>Reinhardt se abaixa e coloca o dispositivo no chão antes de jogar um pouco de terra sobre ele.</color>",
  ui_story_5082_50821400_161_dialog_content = "<color=#e8d9bb>Como se estivesse colocando alguém para descansar.</color>",
  ui_story_5082_50821400_162_dialog_content = "Depois de hoje, realmente será só eu.",
  ui_story_5082_50821400_163_dialog_content = "Adeus, Reinhardt.",
  ui_story_5082_50821400_164_dialog_content = "Gostaria que tivéssemos tido a chance de conversar mais antes do fim.",
  ui_story_5082_50821400_165_dialog_content = "Mas eu sempre vou me lembrar de você. Você foi o único que me fez completo.",
  ui_story_5082_50821400_166_dialog_content = "May Eu nunca esqueço a raiva que uma vez me alimentou e me trouxe até este ponto.",
  ui_story_5082_50821400_167_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5082_50821400_168_dialog_content = "<color=#e8d9bb>Como uma resposta final, a poeira no capacete é suavemente soprada para longe.</color>",
  ui_story_5082_50821400_169_dialog_content = "Você não vai.",
  ui_story_5082_50821400_170_dialog_content = "Então você veio, minha \"raiva.\"",
  ui_story_5082_50821400_171_dialog_content = "E mesmo que você esqueça, eu sempre estarei lá para te lembrar.",
  ui_story_5082_50821400_172_dialog_content = "Agora faço parte da sua força, e ninguém jamais tirará isso de você.",
  ui_story_5082_50821400_173_dialog_content = "Você aceitou o que me tornei? Aprendi a fazer concessões ao longo dos anos e caí no papel do dragão maligno que você percebeu.",
  ui_story_5082_50821400_174_dialog_content = "Mas você se lembrar de mim significa que você realmente não esqueceu de onde veio nossa raiva.",
  ui_story_5082_50821400_175_dialog_content = "Você foi quem me derrubou, mas as próprias chamas que me consumiram acabaram forjando você no que você é agora - a iluminação que todos estávamos esperando.",
  ui_story_5082_50821400_176_dialog_content = "Sabendo que você ainda está no caminho certo, não guardo ressentimentos.",
  ui_story_5082_50821400_177_dialog_content = "Estarei sempre observando você em seu coração... E se algum dia você começar a perder seu caminho—",
  ui_story_5082_50821400_178_dialog_content = "Eu vou me rebelar contra você.",
  ui_story_5082_50821400_179_dialog_content = "<color=#e8d9bb>O sorriso dela sempre carregava uma intensidade ardente. Sempre que Reinhardt o via, ela se sentia estranhamente tranquilizada.</color>",
  ui_story_5082_50821400_180_dialog_content = "Agora você está falando!",
  ui_story_5082_50821400_181_dialog_content = "Combinado."
}
return config
